TURATH_CHUNK(77,[{"num":15400,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  إِنَّمَا كَانَ فِرَاشُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي يَنَامُ عَلَيْهِ أَدَمًا حَشْوُهُ لِيفٌ."],"takhrij":"صحيح: رواه مسلم في اللباس (2082: 38) عن علي بن حجر السعدي، أخبرنا علي بن مسهر، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب في الفراش","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2082:38).","chapter_en":"Furnishings and Bedding","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في أنواع اللباس وألوانه","group_en":"Collection of What Has Been Narrated Concerning Types and Colors of Clothing","part_no":63,"group_no":1,"chapter_no":34,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The bed upon which the Messenger of Allah ﷺ slept was nothing more than tanned leather stuffed with palm fiber.”"]},"buhuth":{"en":["In another route from Hishām with the same chain: “The sleeping-place of the Messenger of Allah ﷺ upon which he slept.”","The word “al-ḍijʿāʿ,” with kasrah on the ḍād, comes from al-iḍṭijāʿ (lying down), just as jilsah comes from julūs. What is meant is the thing upon which he would lie."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9624,15167],"tks":"صحيح: رواه مسلم (2082: 38)."},{"num":15401,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، أَنَّهَا قَالَتْ: كَانَ يُفْرَشُ لِي حِيَالَ مُصَلَّى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَكَانَ يُصَلِّي وَأَنَا حِيَالُهُ."],"takhrij":"صحيح: رواه أبو داود (4148)، وابن ماجه (957)، وأحمد (26733) كلهم من حديث خالد الحذاء، عن أبي قلابة، عن زينب بن أبي سلمة، عن أم سلمة فأخبرته.","grade":"صحيح","chapter_ar":"باب في الفراش","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4148), Ibn Mājah (957), and Aḥmad (26733).","chapter_en":"Furnishings and Bedding","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في أنواع اللباس وألوانه","group_en":"Collection of What Has Been Narrated Concerning Types and Colors of Clothing","part_no":63,"group_no":1,"chapter_no":34,"content":{"translation":{"en":["Umm Salamah narrated: “A sleeping place would be spread out for me opposite the prayer-place of the Messenger of Allah ﷺ, and he would pray while I was lying opposite him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4148)، وابن ماجه (957)، وأحمد (26733)."},{"num":15402,"demo":false,"sanad":"","matn":["عن مُعَاوِيَةَ بن سُوَيْدٍ بْنِ مقرن، قَالَ: دَخَلْتُ عَلَى الْبَرَاءِ بْنِ عَازِبٍ، فَسَمِعْتُهُ يَقُولُ:  أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ، وَنَهَانَا عَنْ سَبْعٍ: أَمَرَنَا بِعِيَادَةِ الْمَرِيضِ، وَاتِّبَاعِ الْجَنَازَةِ، وَتَشْمِيتِ الْعَاطِسِ، وَإِبْرَارِ الْقَسَمِ، أَوِ الْمُقْسِمِ، وَنَصْرِ الْمَظْلُومِ، وَإِجَابَةِ الدَّاعِي، وَإِفْشَاءِ السَّلَامِ، وَنَهَانَا عَنْ خَوَاتِيمَ أَوْ عَنْ تَخَتُّمٍ بِالذَّهَبِ، وَعَنْ شُرْبٍ بِالْفِضَّةِ، وَعَنِ الْمَيَاثِرِ، وَعَنِ الْقَسِّيِّ، وَعَنْ لُبْسِ الْحَرِيرِ وَالْإِسْتَبْرَقِ وَالدِّيبَاجِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1239)، ومسلم في اللباس (2066: 3) كلاهما من طريق أشعث بن أبي الشعثاء، حدثني معاوية بن سويد بن مقرن، فذكره. واللفظ لمسلم، ولفظ البخاري نحوه.","grade":"متفق عليه","chapter_ar":"باب المأمورات والمنهيات من الملابس والذهب والفضة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1239) and Muslim (2066:3).","chapter_en":"Commands and Prohibitions Concerning Clothing, Gold, and Silver","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في أنواع اللباس وألوانه","group_en":"Collection of What Has Been Narrated Concerning Types and Colors of Clothing","part_no":63,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Muʿāwiyah ibn Suwayd ibn Muqarrin narrated: I entered upon al-Barāʾ ibn ʿĀzib and heard him say: The Messenger of Allah ﷺ commanded us with seven things and prohibited us from seven things. He commanded us to: Visit the sick, follow funeral processions, invoke mercy for one who sneezes, fulfill an oath—or support the one who adjures another by Allah—help the oppressed, accept invitations, and spread the greeting of peace. And he prohibited us from: Gold rings—or wearing gold rings—drinking from silver vessels, mītharah saddle coverings, qassī garments, and wearing silk, istabraq, and dībāj."]},"buhuth":{"en":["Some narrations add:","“Whoever drinks from silver vessels in this world will not drink from them in the Hereafter.”","Another addition states:","“And dībāj, and that we sit upon it.”","In another narration:","“And riding upon red mītharah coverings.”","The mītharah was a type of furnishing used by non-Arabs, made from silk or brocade and placed over a horse saddle or camel saddle. Women would make them for their husbands from red urjuwān and brocade.","Dībāj is a later Arabic term referring to a type of silk.","Qassī, with fatḥah on the qāf and a doubled sīn, is a type of clothing attributed to a town in Egypt called al-Qass. Al-Nawawī related from the scholars that it was cloth mixed with silk.","Istabraq refers to thick silk or heavy silk fabric. It is an Arabized foreign word, originally istabrah or istafrah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1239)، ومسلم (2066: 3)."},{"num":15403,"demo":false,"sanad":"","matn":["عَنْ أَبِي بُرْدَةَ بْنِ أَبِي مُوسَى، قَالَ: كُنْتُ جَالِسًا مَعَ أَبِي، فَجَاءَ عَلِيٌّ، فَقَامَ عَلَيْنَا، فَسَلَّمَ، ثُمَّ أَمَرَ أَبَا مُوسَى بِأُمُورٍ مِنْ أُمُورِ النَّاسِ، قَالَ: ثُمَّ قَالَ عَلِيٌّ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَلِ اللهَ الْهُدَى، وَأَنْتَ تَعْنِي بِذَلِكَ هِدَايَةَ الطَّرِيقِ، وَاسْأَلِ اللهَ السَّدَادَ، وَأَنْتَ تَعْنِي بِذَلِكَ تَسْدِيدَكَ السَّهْمَ، وَنَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَجْعَلَ خَاتَمِي فِي هَذِهِ أَوْ هَذِهِ: السَّبَّابَةِ وَالْوُسْطَى، قَالَ: فَكَانَ قَائِمًا فَمَا أَدْرِي فِي أَيَّتِهِمَا؟","قَالَ: وَنَهَانِي رَسُولُ اللهِ صلى الله عليه وسلم عَنِ الْمِيثَرَةِ، وَعَنِ الْقَِسِّيَّةِ. قُلْنَا لَهُ: يَا أَمِيرَ الْمُؤْمِنِينَ، وَأَيُّ شَيْءٍ الْمِيثَرَةُ؟ قَالَ: شَيْءٌ يَصْنَعُهُ النِّسَاءُ لِبُعُولَتِهِنَّ عَلَى رِحَالِهِنَّ. قَالَ: قُلْنَا: وَمَا الْقَِسِّيَّةُ؟ قَالَ: ثِيَابٌ تَأْتِينَا مِنْ قِبَلِ الشَّامِ، مُضَلَّعَةٌ فِيهَا أَمْثَالُ الأُتْرُجِّ. قَالَ: قَالَ أَبُو بُرْدَةَ: فَلَمَّا رَأَيْتُ السَّبَنِيَّ، عَرَفْتُ أَنَّهَا هِيَ."],"takhrij":"حسن: رواه أحمد (1124) عن علي بن عاصم، أخبرنا عاصم بن كليب الجرمي، عن أبي بردة بن أبي موسى قال: فذكره.","grade":"حسن","chapter_ar":"باب المأمورات والمنهيات من الملابس والذهب والفضة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (1124).","chapter_en":"Commands and Prohibitions Concerning Clothing, Gold, and Silver","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في أنواع اللباس وألوانه","group_en":"Collection of What Has Been Narrated Concerning Types and Colors of Clothing","part_no":63,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Abū Burdah ibn Abī Mūsā narrated: I was sitting with my father when ʿAlī came. He stood before us, greeted us, and instructed Abū Mūsā concerning several matters relating to the people. Then ʿAlī said: The Messenger of Allah ﷺ said to me: “Ask Allah for guidance, and when you ask for guidance, think of being guided along a road. Ask Allah for correctness, and when you ask for correctness, think of making an arrow hit its mark.” The Messenger of Allah ﷺ also prohibited me from wearing my ring on this finger or this finger—the index finger and the middle finger. The narrator said that ʿAlī was standing, so he could not tell which of the two fingers he indicated first. He continued: The Messenger of Allah ﷺ prohibited me from the mītharah and from qassiyyah garments. We asked: “O Commander of the Believers, what is the mītharah?” He replied: “It is something women make for their husbands to place upon their saddles.” We asked: “And what are the qassiyyah garments?” He replied: “Garments that come to us from the direction of al-Shām, striped with patterns resembling citron fruit.”","Abū Burdah said: “When I later saw the sabaniyyah garment, I recognized that it was what he meant.”"]},"buhuth":{"en":["The word “sabaniyyah” is attributed to Saban, a place in the Maghrib. It refers to an especially coarse type of linen cloth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (1124)."},{"num":15404,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لاَ تَرْكَبُوا الْخَزَّ، وَلاَ النِّمَارَ. قَالَ وَكَانَ مُعَاوِيَةُ لاَ يُتَّهَمُ فِي الْحَدِيثِ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (4129)، وابن ماجه (3656)، وأحمد (16840) كلهم من حديث وكيع، حدثنا أبو المعتمر، عن ابن سيرين، عن معاوية فذكره.","grade":"صحيح","chapter_ar":"باب المأمورات والمنهيات من الملابس والذهب والفضة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4129), Ibn Mājah (3656), and Aḥmad (16840).","chapter_en":"Commands and Prohibitions Concerning Clothing, Gold, and Silver","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في أنواع اللباس وألوانه","group_en":"Collection of What Has Been Narrated Concerning Types and Colors of Clothing","part_no":63,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Muʿāwiyah narrated that the Messenger of Allah ﷺ said: “Do not ride upon khazz, and do not ride upon leopard skins.” Muʿāwiyah was not regarded as suspect in narrating from the Messenger of Allah ﷺ."]},"buhuth":{"en":["The phrase “do not ride upon khazz” is explained here as meaning not to wear a garment made of pure silk.","The phrase “do not ride upon leopard skins” means not to sit upon the skins of leopards and predatory animals or use them as saddle coverings, because they contain an element of pride and ostentation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4129)، وابن ماجه (3656)، وأحمد (16840)."},{"num":15405,"demo":false,"sanad":"","matn":["عَنْ أَبِي شَيْخٍ الْهُنَائِيِّ، قَالَ: كُنْتُ فِي مَلَأٍ مِنْ أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ مُعَاوِيَةَ، فَقَالَ مُعَاوِيَةُ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الْحَرِيرِ؟ قَالُوا: اللهُمَّ نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ، قَالَ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ إِلَّا مُقَطَّعًا؟ قَالُوا: اللهُمَّ نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ، قَالَ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ رُكُوبِ النُّمُورِ؟ قَالُوا: اللهُمَّ نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ، قَالَ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الشُّرْبِ فِي آنِيَةِ الْفِضَّةِ؟ قَالُوا: اللهُمَّ نَعَمْ، قَالَ: وَأَنَا أَشْهَدُ، قَالَ: أَنْشُدُكُمُ اللهَ، أَتَعْلَمُونَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ جَمْعٍ بَيْنَ حَجٍّ وَعُمْرَةٍ؟ قَالُوا: أَمَّا هَذَا، فَلَا، قَالَ: أَمَا إِنَّهَا مَعَهُنَّ."],"takhrij":"حسن: رواه أحمد (16833)، واللفظ له، وأبو داود (1749) كلاهما من حديث قتادة، عن أبي الشيخ الهنائي فذكره.","grade":"حسن","chapter_ar":"باب المأمورات والمنهيات من الملابس والذهب والفضة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (16833), and this is his wording, and Abū Dāwūd (1749).","chapter_en":"Commands and Prohibitions Concerning Clothing, Gold, and Silver","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في أنواع اللباس وألوانه","group_en":"Collection of What Has Been Narrated Concerning Types and Colors of Clothing","part_no":63,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Abū Shaykh al-Hunāʾī narrated: I was among a gathering of the Companions of the Messenger of Allah ﷺ in the presence of Muʿāwiyah. Muʿāwiyah said: “I adjure you by Allah: do you know that the Messenger of Allah ﷺ prohibited wearing silk?” They replied: “By Allah, yes.” He said: “And I testify to that.” Then he said: “I adjure you by Allah, the Exalted: do you know that the Messenger of Allah ﷺ prohibited wearing gold except in small separated pieces?” They replied: “By Allah, yes.” He said: “And I testify to that.” Then he said: “I adjure you by Allah, the Exalted: do you know that the Messenger of Allah ﷺ prohibited riding upon leopard skins?” They replied: “By Allah, yes.” He said: “And I testify to that.” Then he said: “I adjure you by Allah, the Exalted: do you know that the Messenger of Allah ﷺ prohibited drinking from silver vessels?” They replied: “By Allah, yes.” He said: “And I testify to that.” Then he said: “I adjure you by Allah, the Exalted: do you know that the Messenger of Allah ﷺ prohibited combining Ḥajj and ʿUmrah?” They replied: “As for this one, no.” He said: “Indeed, it is among them.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7309],"tks":"حسن: رواه أحمد (16833) واللفظ له، وأبو داود (1749)."},{"num":15406,"demo":false,"sanad":"","matn":["عن أسامة بن عمير الهذلي أن رسول الله صلى الله عليه وسلم نهى عن جلود السباع أن تفترش."],"takhrij":"صحيح: رواه أبو داود (4132)، والترمذي (1770) وأحمد (20706)، والحاكم (1/144) كلهم من حديث سعيد بن أبي عروبة، عن قتادة، عن أبي المليح، عن أبيه أسامة فذكره.","grade":"صحيح","chapter_ar":"باب المأمورات والمنهيات من الملابس والذهب والفضة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4132), al-Tirmidhī (1770), Aḥmad (20706), and al-Ḥākim (1/144).","chapter_en":"Commands and Prohibitions Concerning Clothing, Gold, and Silver","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في أنواع اللباس وألوانه","group_en":"Collection of What Has Been Narrated Concerning Types and Colors of Clothing","part_no":63,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Usāmah ibn ʿUmayr al-Hudhalī narrated: “The Messenger of Allah ﷺ prohibited using the skins of predatory animals as furnishings.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4132)، والترمذي (1770)، وأحمد (20706)، والحاكم (1/144)."},{"num":15407,"demo":false,"sanad":"","matn":["عَنْ خَالِدِ بن مَعْدَانَ قَالَ: وَفَدَ الْمِقْدَامُ بْنِ مَعْدِيكَرِبَ، وَعَمْرُو بن الأَسْوَدِ، وَرَجُلٌ مِنْ بَنِي أَسَدٍ مِنْ أَهْلِ قِنَّسْرِينَ إِلَى مُعَاوِيَةَ بن أَبِي سُفْيَانَ، فَقَالَ: يَا مُعَاوِيَةُ إِنْ أَنَا صَدَقْتُ فَصَدِّقْنِي، وَإِنْ أَنَا كَذَبْتُ فَكَذِّبْنِي. قَالَ: أَفْعَلُ. قَالَ: فَأَنْشُدُكَ بِاللَّهِ هَلْ تَعْلَمُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ؟ قَالَ نَعَمْ. قَالَ: فَأَنْشُدُكَ بِاللَّهِ هَلْ سَمِعْتَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ لُبْسِ الْحَرِيرِ؟ قـال نَعَمْ. قـال: فَأَنْشُدُكَ بِاللَّهِ هَلْ تَعْلَمُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ جُلُودِ السِّبَاعِ وَالرُّكُوبِ عَلَيْهَا؟ قَالَ نَعَمْ."],"takhrij":"حسن: رواه أبو داود (4131)، وأحمد (17189)، والطبراني في الكبير (20/ح 636) كلهم من طرق عن بقية بن الوليد، حدثنا بحير بن سعد، عن خالد بن معدان قال: فذكره في سياق طويل، وهو مذكور في موضعه.","grade":"حسن","chapter_ar":"باب المأمورات والمنهيات من الملابس والذهب والفضة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4131), Aḥmad (17189), and al-Ṭabarānī in al-Muʿjam al-Kabīr (20/269).","chapter_en":"Commands and Prohibitions Concerning Clothing, Gold, and Silver","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في أنواع اللباس وألوانه","group_en":"Collection of What Has Been Narrated Concerning Types and Colors of Clothing","part_no":63,"group_no":1,"chapter_no":35,"content":{"translation":{"en":["Khālid ibn Maʿdān narrated: Al-Miqdām ibn Maʿdīkarib, ʿAmr ibn al-Aswad, and a man from Banū Asad from the people of Qinnasrīn came as a delegation to Muʿāwiyah ibn Abī Sufyān. One of them said: “O Muʿāwiyah, if I speak the truth, affirm me; and if I lie, reject what I say.” Muʿāwiyah replied: “I will.” He said: “I adjure you by Allah: do you know that the Messenger of Allah ﷺ prohibited wearing gold?” He replied: “Yes.” He asked: “I adjure you by Allah: did you hear the Messenger of Allah ﷺ prohibit wearing silk?” He replied: “Yes.” He asked: “I adjure you by Allah: do you know that the Messenger of Allah ﷺ prohibited wearing the skins of predatory animals and riding upon them?” He replied: “Yes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4131)، وأحمد (17189)، والطبراني في الكبير (20/269)."},{"num":15408,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ:  الْفِطْرَةُ خَمْسٌ: الِاخْتِتَانُ، وَالِاسْتِحْدَادُ، وَقَصُّ الشَّارِبِ، وَتَقْلِيمُ الْأَظْفَارِ، وَنَتْفُ الْإِبْطِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5891)، ومسلم في الطهارة (257) كلاهما من طريق الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5891) and Muslim (257).","chapter_en":"The Practices of the Fiṭrah","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Five things are from the fiṭrah: circumcision, shaving the pubic hair, trimming the mustache, clipping the nails, and plucking the armpit hair.”"]},"buhuth":{"en":["The phrase “from the fiṭrah”, with kasrah on the fāʾ, means that Allah, the Exalted, has made these practices part of the natural disposition of the human being.","They are the way of the prophets and messengers and the natural way of human beings, ancient and modern, except those who have departed from the fiṭrah, such as the People of the Book and the Magians."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5891)، ومسلم (257)."},{"num":15409,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ: رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مِنَ الْفِطْرَةِ: حَلْقُ الْعَانَةِ، وَتَقْلِيمُ الأَظْفَارِ، وَقَصُّ الشَّارِبِ."],"takhrij":"صحيح: رواه البخاري في اللباس (5890)، عن أحمد ابن أبي رجاء، حدثنا إسحاق بن سليمان، قال: سمعت حنظلة، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5890).","chapter_en":"The Practices of the Fiṭrah","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “From the fiṭrah are shaving the pubic hair, clipping the nails, and trimming the mustache.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5890)."},{"num":15410,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  عَشْرٌ مِنَ الْفِطْرَةِ: قَصُّ الشَّارِبِ، وَإِعْفَاءُ اللِّحْيَةِ، وَالسِّوَاكُ، وَاسْتِنْشَاقُ الْمَاءِ، وَقَصُّ الْأَظْفَارِ، وَغَسْلُ الْبَرَاجِمِ، وَنَتْفُ الْإِبْطِ، وَحَلْقُ الْعَانَةِ، وَانْتِقَاصُ الْمَاءِ.","قَالَ زَكَرِيَّا: قَالَ مُصْعَبٌ: وَنَسِيتُ الْعَاشِرَةَ إِلاَّ أَنْ تَكُونَ الْمَضْمَضَةَ."],"takhrij":"صحيح: رواه مسلم في الطهارة (261) من طريق وكيع، عن زكريا بن أبي زائدة، عن مصعب بن شيبة، عن طلق بن حبيب، عن عبد الله بن الزبير، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب خصال الفطرة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (261).","chapter_en":"The Practices of the Fiṭrah","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “Ten things are from the fiṭrah: trimming the mustache, leaving the beard, using the siwāk, drawing water into the nose, clipping the nails, washing the finger joints, plucking the armpit hair, shaving the pubic hair, and cleansing oneself with water after relieving oneself.” Zakariyyā said that Muṣʿab said: “I forgot the tenth, unless it was rinsing the mouth.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (261)."},{"num":15411,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: انْهَكُوا الشَّوَارِبَ، وَأَعْفُوا اللِّحَى."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5893) عن محمد، أخبرنا عبدة، عن عبيد الله بن عمر، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب إعفاء اللحية، وقص الشارب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5893) and Muslim (259:52), with Muslim’s wording:","chapter_en":"Leaving the Beard and Trimming the Mustache","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Trim the mustaches closely and leave the beards.”"]},"buhuth":{"en":["“Trim the mustaches closely and leave the beards.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5893)، ومسلم (259: 52) بلفظ: ((أحفوا الشوارب، وأعفوا اللحى))."},{"num":15412,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خَالِفُوا الْمُشْرِكِينَ، وَفِّرُوا اللِّحَى، وَأَحْفُوا الشَّوَارِبَ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5892)، ومسلم في الطهارة (259: 54) كلاهما من حديث يزيد بن زريع، حدثنا عمر بن محمد بن زيد، عن نافع، عن ابن عمر فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب إعفاء اللحية، وقص الشارب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5892) and Muslim (259:54). The wording is that of al-Bukhārī.","chapter_en":"Leaving the Beard and Trimming the Mustache","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Prophet ﷺ said: “Differ from the polytheists: let the beards grow and trim the mustaches closely.”"]},"buhuth":{"en":["Muslim’s wording is:","“Differ from the polytheists: trim the mustaches closely and let the beards grow fully.”","Al-Bukhārī said:","“When Ibn ʿUmar performed Ḥajj or ʿUmrah, he would grasp his beard and cut whatever extended beyond his fist.”","Mālik also narrated in The Book of Ḥajj (200), from Nāfiʿ, that when ʿAbdullāh ibn ʿUmar shaved his head during Ḥajj or ʿUmrah, he would also take something from his beard and mustache."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5892)، ومسلم (259: 54)، واللفظ للبخاري."},{"num":15413,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  أَنَّهُ أَمَرَ بِإِحْفَاءِ الشَّوَارِبِ، وَإِعْفَاءِ اللِّحْيَةِ."],"takhrij":"صحيح: رواه مالك في الشعر (1) عن أبي بكر بن نافع، عن أبيه نافع، عن عبد الله بن عمر فذكره.","grade":"صحيح","chapter_ar":"باب إعفاء اللحية، وقص الشارب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in The Book of Hair (1) and Muslim (259:53).","chapter_en":"Leaving the Beard and Trimming the Mustache","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Prophet ﷺ commanded: “Trimming the mustaches closely and leaving the beard.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (1)، ومسلم (259: 53)."},{"num":15414,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  جُزُّوا الشَّوَارِبَ، وَأَرْخُوا اللِّحَى، خَالِفُوا الْمَجُوسَ."],"takhrij":"صحيح: رواه مسلم في الطهارة (260: 55) عن أبي بكر بن إسحاق، أخبرنا ابن أبي مريم، أخبرنا محمد بن جعفر، أخبرني العلاء بن عبد الرحمن بن يعقوب مولى الحرقة، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إعفاء اللحية، وقص الشارب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (260:55).","chapter_en":"Leaving the Beard and Trimming the Mustache","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Clip the mustaches, let the beards grow, and differ from the Magians.”"]},"buhuth":{"en":["In the narration of most transmitters, the wording is “arkhū”, meaning: leave the beards and allow them to grow long.","In the narration of Ibn Hāmān, it appears as “arjū” with a jīm, which carries the same meaning. Its original form is “arjiʾū” with a hamzah, but the hamzah was omitted for ease of pronunciation, and its meaning is: leave them as they are or delay cutting them."]}},"tuhfa":{},"full":1,"dr":1,"rep":[1328],"tks":"صحيح: رواه مسلم (260: 55)."},{"num":15415,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ أَرْقَمَ، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ لَمْ يَأْخُذْ مِنْ شَارِبِهِ فَلَيْسَ مِنَّا."],"takhrij":"صحيح: رواه الترمذي (2761)، والنسائي (5047)، وأحمد (19263) كلهم من حديث يوسف بن صهيب، عن حبيب بن يسار، عن زيد بن أرقم فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب إعفاء اللحية، وقص الشارب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2761), al-Nasā’ī (5047), and Aḥmad (19263).","chapter_en":"Leaving the Beard and Trimming the Mustache","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Zayd ibn Arqam narrated that the Prophet ﷺ said: “Whoever does not trim his mustache is not from us.”"]},"buhuth":{"en":["The phrase “is not from us” means: he is not following our Sunnah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2761)، والنسائي (5047)، وأحمد (19263)."},{"num":15416,"demo":false,"sanad":"","matn":["عن الْقَاسِمِ قَالَ: سَمِعْتُ أَبَا أُمَامَةَ يَقُولُ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى مَشْيَخَةٍ مِنَ الْأَنْصَارٍ بِيضٌ لِحَاهُمْ، فَقَالَ: يَا مَعْشَرَ الْأَنْصَارِ، حَمِّرُوا، وَصَفِّرُوا، وَخَالِفُوا أَهْلَ الْكِتَابِ. قَالَ: فَقُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّ أَهْلَ الْكِتَابِ يَتَسَرْوَلَونَ، وَلْا يَأْتَزِرُونَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: تَسَرْوَلُوا، وَائْتَزِرُوا، وَخَالِفُوا أَهْلَ الْكِتَابِ. قَالَ: فَقُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّ أَهْلَ الْكِتَابِ يَتَخَفَّفُونَ، وَلَا يَنْتَعِلُونَ. قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَتَخَفَّفُوا، وَانْتَعِلُوا، وَخَالِفُوا أَهْلَ الْكِتَابِ. قَالَ: فَقُلْنَا: يَا رَسُولَ اللَّهِ، إِنَّ أَهْلَ الْكِتَابِ يَقُصُّونَ عَثَانِينَهُمْ، وَيُوَفِّرُونَ سِبَالَهُمْ. قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قُصُّوا سِبَالَكُمْ، وَوَفِّرُوا عَثَانِينَكُمْ، وَخَالِفُوا أَهْلَ الْكِتَابِ."],"takhrij":"حسن: رواه أحمد (22283)، والطبراني في الكبير (7924) كلاهما من حديث زيد بن يحيى، حدثنا عبد الله بن العلاء بن زبر، حدثني القاسم فذكره. والفظ لأحمد.","grade":"حسن","chapter_ar":"باب إعفاء اللحية، وقص الشارب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (22283) and al-Ṭabarānī in al-Muʿjam al-Kabīr (7924).","chapter_en":"Leaving the Beard and Trimming the Mustache","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Al-Qāsim narrated: I heard Abū Umāmah say: The Messenger of Allah ﷺ came out to a group of elderly men from the Anṣār whose beards had turned white. He said: “O assembly of the Anṣār, dye them red and yellow, and differ from the People of the Book.” I said: “O Messenger of Allah, the People of the Book wear trousers and do not wear izārs.” The Messenger of Allah ﷺ replied: “Wear trousers and wear izārs, and differ from the People of the Book.” I said: “O Messenger of Allah, the People of the Book wear leather socks and do not wear sandals.” The Prophet ﷺ replied: “Wear leather socks and wear sandals, and differ from the People of the Book.” We said: “O Messenger of Allah, the People of the Book trim their beards and leave their mustaches long.” The Prophet ﷺ replied: “Trim your mustaches, let your beards grow, and differ from the People of the Book.”"]},"buhuth":{"en":["The word “sibāl” is the plural of sabalah, meaning the mustache.","The word “ʿathānīn” is the plural of ʿuthnūn, meaning the beard."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22283)، والطبراني في الكبير (7924)."},{"num":15417,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ: ضِفْتُ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ، فَأَمَرَ بِجَنْبٍ، فَشُوِيَ، قَالَ: فَأَخَذَ الشَّفْرَةَ، فَجَعَلَ يَحُزُّ لِي بِهَا مِنْهُ، قَالَ: فَجَاءَهُ بِلَالٌ يُؤْذِنُهُ بِالصَّلَاةِ، فَأَلْقَى الشَّفْرَةَ، وَقَالَ: مَا لَهُ تَرِبَتْ يَدَاهُ؟، قَالَ مُغِيرَةُ: وَكَانَ شَارِبِي وَفَى، فَقَصَّهُ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى سِوَاكٍ، أَوْ قَالَ: أَقُصُّهُ لَكَ عَلَى سِوَاكٍ."],"takhrij":"حسن: رواه أبو داود (188)، وأحمد (18212) كلاهما من حديث وكيع، حدثنا مسعر، عن أبي صخرة جامع بن شداد، عن مغيرة بن عبد الله، عن المغيرة بن شعبة قال: فذكره. واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب إعفاء اللحية، وقص الشارب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (188) and Aḥmad (18212).","chapter_en":"Leaving the Beard and Trimming the Mustache","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah narrated: I was the guest of the Prophet ﷺ one night. He ordered that a side of meat be roasted. He took a knife and began cutting pieces from it for me. Then Bilāl came to inform him that it was time for prayer. The Prophet ﷺ put down the knife and said: “What is wrong with him? May his hands be covered in dust.” Al-Mughīrah said: My mustache had grown full, so the Messenger of Allah ﷺ trimmed it for me over a siwāk—or he said: “Shall I trim it for you over a siwāk?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (188)، وأحمد (18212)."},{"num":15418,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: ذُكِرَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَجُوسُ، فَقَالَ: إِنَّهُمْ يُوفُونَ سِبَالَهُمْ، وَيَحْلِقُونَ لِحَاهُمْ، فَخَالِفُوهُمْ، فَكَانَ ابْنُ عُمَرَ يَجُزُّ سِبَالَهُ، كَمَا تُجَزُّ الشَّاةُ أَوِ الْبَعِيرُ."],"takhrij":"حسن: رواه ابنُ حبان (5476) عن الحسين بن محمد بن أبي معشر قال: حدثنا محمد بن معدان الحراني، قال: حدثنا الحسن بن محمد بن أعين قال: حدثنا معقل بن عبيد الله، عن ميمون بن مهران، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب إعفاء اللحية، وقص الشارب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (5476).","chapter_en":"Leaving the Beard and Trimming the Mustache","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Magians were mentioned to the Messenger of Allah ﷺ, and he said: “They let their mustaches grow and shave their beards, so differ from them.” Ibn ʿUmar would therefore clip his mustache as closely as the wool of a sheep or camel is clipped."]},"buhuth":{"en":["A report from Ibn ʿAbbās states that the Messenger of Allah ﷺ used to trim his mustache and that your father Ibrāhīm before him did likewise; however, this report is weak. Narrated by al-Tirmidhī (2760) and Aḥmad (2738).","Also related is the mursal report of ʿAṭāʾ ibn Yasār: a man entered the mosque with disheveled hair and beard, and the Messenger of Allah ﷺ gestured for him to go out and put his hair and beard in order. When he returned, the Prophet ﷺ said: “Is this not better than one of you coming with his hair disheveled as though he were a devil?” Narrated by Mālik in The Book of Hair (7).","Saʿīd ibn al-Musayyib also related that Ibrāhīm ﷺ was the first to host a guest, the first to circumcise, the first to trim his mustache, and the first to see gray hair. He asked, “My Lord, what is this?” Allah, Blessed and Exalted, said, “Dignity, O Ibrāhīm.” He replied, “My Lord, increase me in dignity.” Narrated by Mālik in The Description of the Prophet ﷺ (4).","Fiqh of the Chapter","Five different expressions have been narrated concerning leaving the beard:","“Aʿfū,” “awfū,” “arkhū,” “arjū,” and “waffirū.”","Their apparent meaning is the same: to leave the beard as it is and allow it to grow.","A group among the early Muslims held this view and disliked removing anything from the beard, whether from its length or width.","Some scholars held that there may be a limit to what is meant by leaving the beard, based on what has been narrated from Ibn ʿUmar and others.","Al-Qāḍī ʿIyāḍ said:","“Shaving it, cutting it short, and singeing it are disliked. As for taking from its length and width, that is good. Excessive length that attracts attention is disliked, just as excessive cutting and clipping are disliked.”","Al-Nawawī said:","“The scholars mentioned ten disliked practices concerning the beard, some uglier than others. The ninth is leaving it disheveled and matted as a display of asceticism and being slow to attend to one’s own grooming.”","The early scholars then differed over whether there is a specific limit.","Some did not set any specific measurement, but held that it should not be left to grow to the point of attracting excessive attention; rather, something may be taken from it.","Mālik disliked the beard becoming excessively long.","A group of the early Muslims held that whatever exceeds a fistful may be cut, based on the practice of Ibn ʿUmar and Abū Hurayrah, both of whom narrated the hadith commanding that the beard be left to grow.","ʿUmar also did this to a man, as al-Ḥāfiẓ Ibn Ḥajar mentioned in Fatḥ al-Bārī (10/350).","As for the report from ʿAmr ibn Shuʿayb, from his father, from his grandfather, that the Messenger of Allah ﷺ used to trim from the width and length of his beard, it is weak. Narrated by al-Tirmidhī (2762).","As for the statement of the Prophet ﷺ:","“Differ from the polytheists: trim the mustaches closely and let the beards grow fully,”","it was the custom of the Persians to allow their mustaches to grow long while cutting their beards very short or shaving them.","The Sacred Law prohibited this practice in order to differ from them.","As for closely trimming the mustache, its meaning is to cut it thoroughly, because another narration says:","“Clip the mustaches.”","The word jazz means cutting.","This is also indicated by the wording in the two Ṣaḥīḥ collections:","“Trimming the mustache is from the fiṭrah,”","as well as by the story of al-Mughīrah ibn Shuʿbah.","For this reason, many of the early Muslims held that what extends over the lip should be cut.","Mālik said, as narrated in al-Muwaṭṭaʾ, The Description of the Prophet ﷺ (4):","“The mustache should be trimmed until the edge of the lip becomes visible, which is its border, but it should not be completely clipped away in a way that disfigures one’s appearance.”","When Ibn ʿUmar shaved his head during Ḥajj or ʿUmrah, he would take from both his beard and his mustache.","Mālik mentioned this in al-Muwaṭṭaʾ, The Book of Ḥajj (200).","The scholars of Kūfah held that the mustache may be removed completely and shaved, because the linguistic meaning of iḥfāʾ is complete removal.","It is said:","“So-and-so aḥfā the hair,”","meaning that he removed it entirely.","Both practices are permissible according to the author because the Sunnah contains evidence for both.","The disagreement concerns which is preferable.","The scholars of Madinah preferred clipping and trimming, while the scholars of Kūfah preferred complete removal."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (5476)."},{"num":15419,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ أَنَسٌ:  وُقِّتَ لَنَا فِي قَصِّ الشَّارِبِ، وَتَقْلِيمِ الْأَظْفَارِ، وَنَتْفِ الْإِبْطِ، وَحَلْقِ الْعَانَةِ، أَنْ لَا نَتْرُكَ أَكْثَرَ مِنْ أَرْبَعِينَ لَيْلَةً."],"takhrij":"صحيح: رواه مسلم في الطهارة (258) من طريق جعفر بن سليمان، عن أبي عمران الجوني، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب التوقيت في قص الشارب، وسائر خصال الفطرة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (258).","chapter_en":"The Time Limit for Trimming the Mustache and the Other Practices of the Fiṭrah","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated: “A time limit was set for us regarding trimming the mustache, clipping the nails, plucking the armpit hair, and shaving the pubic hair: we were not to leave them for more than forty nights.”"]},"buhuth":{"en":["Meaning: whenever the need arose, they would trim them; some scholars set the interval from one Friday to the next."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (258)."},{"num":15420,"demo":false,"sanad":"","matn":["عَنْ رويفع بن ثَابِتٍ يَقُولُ: إِنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يَا رُوَيْفِعُ لَعَلَّ الْحَيَاةَ سَتَطُولُ بِكَ بَعْدِي، فَأَخْبِرِ النَّاسَ أَنَّهُ مَنْ عَقَدَ لِحْيَتَهُ، أَوْ تَقَلَّدَ وَتَرًا، أَوِ اسْتَنْجَى بِرَجِيعِ دَابَّةٍ أَوْ عَظْمٍ، فَإِنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهُ بَرِيءٌ."],"takhrij":"صحيح: رواه النسائي (5067) واللفظ له، وأبو داود (36)، وأحمد (16995) كلهم من حديث عياش بن عباس القتباني، أن شييم بن بيتان، حدّثه أنه سمع رويفع بن ثابت يقول: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن عقد اللحية","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (5067), and this is his wording, Abū Dāwūd (36), and Aḥmad (16995).","chapter_en":"Prohibition of Tying the Beard","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":4,"content":{"translation":{"en":["Ruwayfiʿ ibn Thābit narrated that the Messenger of Allah ﷺ said: “O Ruwayfiʿ, perhaps you will live for a long time after me. So inform the people that whoever ties his beard, wears a bowstring around his neck, or cleans himself after relieving himself with animal dung or a bone, then Muḥammad ﷺ is free of him.”"]},"buhuth":{"en":["The phrase “ties his beard” means twisting or tying it in the manner practiced by some non-Arabs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (5067) واللفظ له، وأبو داود (36)، وأحمد (16995)."},{"num":15421,"demo":false,"sanad":"","matn":["عَنِ عَبْدِ اللَّهِ بن عَمْرِو بْنِ الْعَاصِ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لاَ تَنْتِفُوا الشَّيْبَ، مَا مِنْ مُسْلِمٍ يَشِيبُ شَيْبَةً فِي الإِسْلاَمِ إِلاَّ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ.","وَفِي رِوَايَةٍ: إِلَّا كَتَبَ اللَّهُ له بها حسنة، وحط عَنْهُ بِهَا خَطِيئَةً."],"takhrij":"حسن: رواه أبو داود (4202)، والترمذي (2821)، والنسائي (5068)، وابن ماجه (3721)، وأحمد (6672) كلهم من حديث عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب كراهة نتف الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4202), al-Tirmidhī (2821), al-Nasā’ī (5068), Ibn Mājah (3721), and Aḥmad (6672).","chapter_en":"Dislike of Plucking Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “Do not pluck gray hairs. No Muslim grows a gray hair in Islam except that it will be a light for him on the Day of Resurrection.” In another narration: “Except that Allah records a good deed for him because of it and removes a sin from him because of it.”"]},"buhuth":{"en":["There is nothing in this hadith indicating that dyeing gray hair is disliked."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4202)، والترمذي (2821)، والنسائي (5068)، وابن ماجه (3721)، وأحمد (6672)."},{"num":15422,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تَنْتِفُوا الشَّيْبَ؛ فَإِنَّهُ نُورٌ يَوْمَ الْقِيَامَةِ، وَمَنْ شَابَ شَيْبَةً فِي الإِسْلَامِ، كُتِبَ لَهُ بِهَا حَسَنَةٌ، وَحُطَّ عَنْهُ بِهَا خَطِيئَةٌ، وَرُفِعَ لَهُ بِهَا دَرَجَةٌ."],"takhrij":"حسن: رواه ابن حبان (2985) عن أحمد بن علي بن المثنى قال: حدثنا إبراهيم بن الحجاج السامي قال: حدثنا حماد بن سلمة، عن محمد بن عمرو، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب كراهة نتف الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (2985).","chapter_en":"Dislike of Plucking Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not pluck gray hairs, for they are light on the Day of Resurrection. Whoever grows a gray hair in Islam, a good deed is written for him because of it, a sin is removed from him because of it, and he is raised one degree because of it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (2985)."},{"num":15423,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ عَبَسَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ شَابَ شَيْبَةً فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه الترمذي (1635)، وأحمد (19440) كلاهما من حديث حيوة بن شريح الحمصي، عن بقية، عن بحير بن سعد، عن خالد بن معدان، عن كثير بن مرة، عن عمرو بن عبسة فذكره.","grade":"حسن","chapter_ar":"باب كراهة نتف الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (1635) and Aḥmad (19440).","chapter_en":"Dislike of Plucking Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["ʿAmr ibn ʿAbasah narrated that the Messenger of Allah ﷺ said: “Whoever grows a gray hair in the path of Allah, it will be a light for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7781],"tks":"حسن: رواه الترمذي (1635)، وأحمد (19440)."},{"num":15424,"demo":false,"sanad":"","matn":["عن عُمَرَ بن الْخَطَّابِ قَالَ: قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ شَابَ شَيْبَةً فِي الْإِسْلَامِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه ابن حبان (2983) عن أحمد بن الحسن بن عبد الجبار الصوفي ببغداد، حدثنا الهيثم بن خارجة -وكان يسمى شعبة الصغير-، حدثنا محمد بن حمير، عن ثابت بن عجلان، عن سليم بن عامر قال: سمعت عمر بن الخطاب فذكره.","grade":"حسن","chapter_ar":"باب كراهة نتف الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (2983).","chapter_en":"Dislike of Plucking Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb narrated that the Messenger of Allah ﷺ said: “Whoever grows a gray hair in Islam, it will be a light for him on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (2983)."},{"num":15425,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ، أَنَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ شَابَ شيبا فِي سَبِيلِ اللَّهِ كَانَتْ لَهُ نُورًا يَوْمَ الْقِيَامَةِ فَقَالَ رَجُلٌ: إِنَّ رِجَالًا يَنْتِفُونَ الشَّيْبَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ شَاءَ فلينتفْ نُورَهُ.","وفي لفظ: من شاء أن ينتف شيبه –أو قال: نوره."],"takhrij":"حسن: رواه ابن أبي عاصم في الجهاد (168)، والطبراني في الكبير (18/304) كلاهما من طرق عن وهب بن جرير بن حازم، حدثنا أبي، سمعت يحيى بن أيوب، يحدث عن يزيد بن أبي حبيب، عن عبد العزيز بن أبي الصعبة، عن حنش (هو الصغاني)، عن فضالة بن عبيد فذكره.","grade":"حسن","chapter_ar":"باب كراهة نتف الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī ʿĀṣim in al-Jihād (168) and al-Ṭabarānī in al-Muʿjam al-Kabīr (18/304).","chapter_en":"Dislike of Plucking Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":5,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd narrated that the Messenger of Allah ﷺ said: “Whoever grows gray hair in the path of Allah, it will be a light for him on the Day of Resurrection.” A man said: “Some men pluck their gray hairs.” The Messenger of Allah ﷺ replied: “Whoever wishes may pluck out his light.” In another wording: “Whoever wishes to pluck out his gray hair—or he said: his light—may do so.”"]},"buhuth":{"en":["A supporting report from Kaʿb ibn Murrah states that he heard the Messenger of Allah ﷺ say: “Whoever grows a gray hair in Islam, it will be a light for him on the Day of Resurrection.” Narrated by al-Tirmidhī (1634), Aḥmad (18064), and Ibn Ḥibbān (4616)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الجهاد (168)، والطبراني في الكبير (18/304)."},{"num":15426,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الْيَهُودَ وَالنَّصَارَى لاَ يَصْبُغُونَ، فَخَالِفُوهُمْ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5899)، ومسلم في اللباس (2103) كلاهما من حديث سفيان بن عيينة، عن الزهري، عن أبي سلمة وسليمان بن يسار، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5899) and Muslim (2103).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The Jews and Christians do not dye their hair, so differ from them.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5899)، ومسلم (2103)."},{"num":15427,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : غَيِّرُوا الشَّيْبَ، وَلاَ تَشَبَّهُوا بِالْيَهُودِ وَلاَ بالنصارى."],"takhrij":"صحيح: رواه الترمذي (1752)، وأحمد (7545)، وصحّحه ابن حبان (5473) كلهم من طريق عمر بن أبي سلمة، عن أبيه، عن أبي هريرة فذكره. واكتفى البعض بذكر اليهود فقط. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (1752), Aḥmad (7545), and authenticated by Ibn Ḥibbān (5473).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Change the gray hair, and do not imitate the Jews or the Christians.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1752)، وأحمد (7545)، وصححه ابن حبان (5473)."},{"num":15428,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ:  أُتِيَ بِأَبِي قُحَافَةَ، أَوْ جَاءَ عَامَ الْفَتْحِ، أَوْ يَوْمَ الْفَتْحِ، وَرَأْسُهُ وَلِحْيَتُهُ مِثْلُ الثَّغَامِ، أَوِ الثَّغَامَةِ، فَأَمَرَ أَوْ فَأُمِرَ بِهِ إِلَى نِسَائِهِ، قَالَ: غَيِّرُوا هَذَا بِشَيْءٍ.","وفي رواية: غيروا هذا بشيء، واجتنبوا السواد."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2102: 78) عن يحيى بن يحيى، أخبرنا أبو خيثمة (هو زهير بن معاوية)، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2102:78).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Jābir narrated: Abū Quḥāfah was brought—or came—during the year of the Conquest, or on the day of the Conquest, and his head and beard were as white as the thaghāmah plant. The Prophet ﷺ said: “Change this with something.” In another narration: “Change this with something, but avoid black.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2102: 78)."},{"num":15429,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ سِيرِينَ، قَالَ: سُئِلَ أَنَسُ بْنُ مَالِكٍ عَنْ خِضَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ شَابَ إِلَّا يَسِيرًا، وَلَكِنَّ أَبَا بَكْرٍ وَعُمَرَ بَعْدَهُ خَضَبَا بِالْحِنَّاءِ وَالْكَتَمِ. قَالَ: وَجَاءَ أَبُو بَكْرٍ بِأَبِيهِ أَبِي قُحَافَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ فَتْحِ مَكَّةَ، يَحْمِلُهُ حَتَّى وَضَعَهُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ: لَوْ أَقْرَرْتَ الشَّيْخَ فِي بَيْتِهِ، لَأَتَيْنَاهُ تَكْرُمَةً لِأَبِي بَكْرٍ. فَأَسْلَمَ، وَلِحْيَتُهُ وَرَأْسُهُ كَالثَّغَامَةِ بَيَاضًا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: غَيِّرُوهُمَا، وَجَنِّبُوهُ السَّوَادَ."],"takhrij":"صحيح: رواه أحمد 12635)، وصحّحه ابن حبان (5472)، والحاكم (3/244) كلهم من حديث محمد بن سلمة الحراني، عن هشام بن حسان القردوسي، عن محمد بن سيرين فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (12635), authenticated by Ibn Ḥibbān (5472), and al-Ḥākim (3/244).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Muḥammad ibn Sīrīn narrated: Anas ibn Mālik was asked about the use of hair dye by the Prophet ﷺ. He replied: “The Messenger of Allah ﷺ had only a little gray hair, but Abū Bakr and ʿUmar after him dyed their hair with henna and katam.” He continued: Abū Bakr brought his father, Abū Quḥāfah, to the Messenger of Allah ﷺ on the day of the Conquest of Makkah, carrying him until he placed him before the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said to Abū Bakr: “If you had left the old man in his house, we would have gone to him.” This was out of honor for Abū Bakr. Abū Quḥāfah accepted Islam. His beard and hair were white like the thaghāmah plant, so the Messenger of Allah ﷺ said: “Change both of them, but keep them away from black.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (12635)، وصححه ابن حبان (5472)، والحاكم (3/244)."},{"num":15430,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: غَيِّرُوا الشَّيْبَ، وَلَا تُقَرِّبُوهُ السَّوَادَ."],"takhrij":"حسن: رواه أحمد (13588) عن قتيبة، قال: أخبرنا ابن لهيعة، عن خالد بن أبي عمران، عن سعد بن إسحاق بن كعب بن عجرة، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (13588).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Change the gray hair, but do not bring it near black.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (13588)."},{"num":15431,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: دخلتْ يهودُ على رسول الله صلى الله عليه وسلم فسأل عنهم فقالوا: يهود، يا رسول الله، وهم لا يُصْبِغونَ الشعرَ، فقال: غيّرُوا سِيْما اليهودِ، ولا تُغيّروا بسوادٍ."],"takhrij":"حسن: رواه الطبري في تهذيب الآثار (926) –الجزء المطبوع الجديد- فقال: حدثني يونس، أخبرنا عبد الله بن وهب، أخبرني ابنُ لهيعة، عن خالد بن أبي عمران، عن سعد بن إسحاق بن كعب بن عجرة، أنه سمع أنس بن مالك يخبره قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarī in Tahdhīb al-Āthār (926).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik narrated: Some Jews entered upon the Messenger of Allah ﷺ. He asked about them, and they said: “They are Jews, O Messenger of Allah, and they do not dye their hair.” He said: “Change the distinguishing appearance of the Jews, but do not change it with black.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبري في تهذيب الآثار (926)."},{"num":15432,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ قَالَتْ: دَخَلَ بِأَبِي قُحَافَةَ أَبُو بَكْرٍ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَرَأْسُهُ كَأَنَّهُ ثَغَامَةٌ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : غَيِّرُوا هَذَا مِنْ شَعْرِهِ."],"takhrij":"حسن: رواه أحمد (26956)، وابن حبان (7208)، والحاكم (3/46-47)، والبيهقي (9/121-122) كلهم من حديث ابن إسحاق قال: حدثني يحيى بن عباد بن عبد الله بن الزبير، عن أبيه، عن جدته أسماء بنت أبي بكر قالت: فذكرته في سياق طويل، وقد مضى في موضعه.","grade":"حسن","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26956), Ibn Ḥibbān (7208), al-Ḥākim (3/46–47), and al-Bayhaqī (9/121).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr narrated: Abū Bakr brought his father, Abū Quḥāfah, to the Messenger of Allah ﷺ, and his hair was like the thaghāmah plant. The Messenger of Allah ﷺ said: “Change this hair of his.”"]},"buhuth":{"en":["The word “thaghāmah” begins with a fatḥah on the thāʾ followed by a ghayn.","Abū ʿUbayd said:","“It is a plant with white flowers and fruit, and the whiteness of gray hair was likened to it.”","Ibn al-Aʿrābī said:","“It is a tree that becomes white as though it were salt.”","Al-Nawawī mentioned this in Sharḥ Muslim."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26956)، وابن حبان (7208)، والحاكم (3/46-47)، والبيهقي (9/121)."},{"num":15433,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَكُونُ قَوْمٌ يَخْضِبُونَ فِي آخِرِ الزَّمَانِ بِالسَّوَادِ كَحَوَاصِلِ الْحَمَامِ، لاَ يَرِيحُونَ رَائِحَةَ الْجَنَّةِ."],"takhrij":"صحيح: رواه أبو داود (4212)، والنسائي (5075)، وأحمد (2470) كلهم من طريق عبيد الله بن عمرو- وهو الرقي- عن عبد الكريم، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4212), al-Nasā’ī (5075), and Aḥmad (2470).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “There will be people at the end of time who dye their hair black like the crops of pigeons; they will not smell the fragrance of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4212)، والنسائي (5075)، وأحمد (2470)."},{"num":15434,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَحْسَنَ مَا غُيِّرَ بِهِ هَذَا الشَّيْبُ الْحِنَّاءُ وَالْكَتَمُ."],"takhrij":"صحيح: رواه أبو داود (4205)، والترمذي (1753)، والنسائي (5078)، وابن ماجه (3622)، وأحمد (21307)، وصحّحه ابن حبان (5474) كلهم من طرق عن عبد الله بن بريدة الأسلمي، عن أبي الأسود، عن أبي ذر قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4205), al-Tirmidhī (1753), al-Nasā’ī (5078), Ibn Mājah (3622), and Aḥmad (21307).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abū Dharr al-Ghifārī narrated that the Messenger of Allah ﷺ said: “The best things with which to change this gray hair are henna and katam.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4205)، والترمذي (1753)، والنسائي (5078)، وابن ماجه (3622)، وأحمد (21307)."},{"num":15435,"demo":false,"sanad":"","matn":["عن أَبِي مَالِكٍ الأشجعي قَالَ: سَمِعْتُ أَبِي، وَسَأَلْتُهُ فَقَالَ: كَانَ خِضَابُنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْوَرْسَ، وَالزَّعْفَرَانَ."],"takhrij":"صحيح: رواه أحمد (15882)، والطبراني في الكبير (8/377)، والبزار –كشف الأستار (2975) كلهم من حديث بكر بن عيسى أبي بشر البصري الراسبي، قال: حدثنا أبو عوانة قال: حدثنا أبو مالك فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (15882), al-Ṭabarānī in al-Muʿjam al-Kabīr (8/377), and al-Bazzār as cited in Kashf al-Astār (2975).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abū Mālik al-Ashjaʿī narrated: I heard my father, and when I asked him, he said: “Our dyes during the time of the Messenger of Allah ﷺ were wars and saffron.”"]},"buhuth":{"en":["The phrase “our dye” means the dye they used during the lifetime of the Messenger of Allah ﷺ.","According to the author, this contains the tacit approval of the Prophet ﷺ of dyeing with wars and saffron."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15882)، والطبراني في الكبير (8/377)، والبزار في كشف الأستار (2975)."},{"num":15436,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَبْدِ اللَّهِ بْنِ مَوْهَبٍ، قَالَ: أَرْسَلَنِي أَهْلِي إِلَى أُمِّ سَلَمَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَدَحٍ مِنْ مَاءٍ - وَقَبَضَ إِسْرَائِيلُ ثَلاَثَ أَصَابِعَ مِنْ قصة - فِيهِ شَعَرٌ مِنْ شَعَرِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَكَانَ إِذَا أَصَابَ الإِنْسَانَ عَيْنٌ أَوْ شيء بَعَثَ إِلَيْهَا مِخْضَبَهُ، فَاطَّلَعْتُ فِي الْجُلْجُلِ، فَرَأَيْتُ شَعَرَاتٍ حُمْرًا."],"takhrij":"صحيح: رواه البخاري في اللباس (5896) عن مالك بن إسماعيل، حدثنا إسرائيل، عن عثمان بن عبد الله بن موهب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5896).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["ʿUthmān ibn ʿAbdullāh ibn Mawhab narrated: My family sent me to Umm Salamah, the wife of the Prophet ﷺ, with a cup of water. Isrāʾīl gestured with three fingers to indicate the size of the small container. It contained some hair of the Prophet ﷺ. Whenever someone was afflicted by the evil eye or some other illness, a vessel of water would be sent to her for it. I looked into the small container and saw reddish hairs."]},"buhuth":{"en":["Ibn Mājah (3623) narrated it by another route with the wording:","“Dyed with henna and katam.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5896)."},{"num":15437,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ  أَنَّهُ سُئِلَ عَنْ شَيْبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: مَا شَانَهُ اللهُ بِبَيْضَاءَ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2341: 105) من طرق عن أبي داود، حدثنا شعبة، عن خليد بن جعفر، سمع أبا إياس، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2341:105).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas was asked about the gray hair of the Prophet ﷺ. He replied: “Allah did not mar him with extensive whiteness.”"]}},"tuhfa":{},"full":1,"rep":[9460],"tks":"صحيح: رواه مسلم (2341: 105)."},{"num":15438,"demo":false,"sanad":"","matn":["عَنِ ابْنِ سِيرِينَ قَالَ:  سُئِلَ أَنَسُ بْنُ مَالِكٍ هَلْ خَضَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: إِنَّهُ لَمْ يَكُنْ رَأَى مِنَ الشَّيْبِ إِلَّا. (قَالَ ابْنُ إِدْرِيسَ: كَأَنَّهُ يُقَلِّلُهُ)، وَقَدْ خَضَبَ أَبُو بَكْرٍ، وَعُمَرُ بِالْحِنَّاءِ وَالْكَتَمِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2341: 100) من طرق عن عبد الله بن إدريس الأودي، عن هشام، عن ابن سيرين، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2341:100).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ibn Sīrīn narrated: Anas ibn Mālik was asked: “Did the Messenger of Allah ﷺ dye his hair?” He replied: “He had seen only a small amount of gray hair.” Ibn Idrīs said that Anas seemed to be indicating how little gray hair he had. Abū Bakr and ʿUmar, however, dyed their hair with henna and katam."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2341: 100)."},{"num":15439,"demo":false,"sanad":"","matn":["عن ثابت قَالَ:  سُئِلَ أَنَسُ بْنُ مَالِكٍ عَنْ خِضَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَوْ شِئْتُ أَنْ أَعُدَّ شَمَطَاتٍ كُنَّ فِي رَأْسِهِ فَعَلْتُ، وَقَالَ: لَمْ يَخْتَضِبْ. وَقَدِ اخْتَضَبَ أَبُو بَكْرٍ بِالْحِنَّاءِ وَالْكَتَمِ، وَاخْتَضَبَ عُمَرُ بِالْحِنَّاءِ بَحْتًا."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5895)، ومسلم في الفضائل (2341: 103) كلاهما من حديث حماد بن زيد، حدثنا ثابت فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5895) and Muslim (2341:103).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Thābit narrated: Anas ibn Mālik was asked about the use of hair dye by the Prophet ﷺ. He replied: “If I wished, I could count the few white hairs that were on his head.” He also said: “He did not dye his hair.” Abū Bakr dyed his hair with henna and katam, while ʿUmar dyed his hair with pure henna."]},"buhuth":{"en":["Regarding the word “shamaṭāt,” Ibn al-Athīr said:","“Al-shamaṭ means gray hair, and the shamaṭāt are the individual white hairs that were present in the hair of his head. The intention is to emphasize how few they were.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5895)، ومسلم (2341: 103)."},{"num":15440,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ:  يُكْرَهُ أَنْ يَنْتِفَ الرَّجُلُ الشَّعْرَةَ الْبَيْضَاءَ مِنْ رَأْسِهِ وَلِحْيَتِهِ. قَالَ: وَلَمْ يَخْتَضِبْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِنَّمَا كَانَ الْبَيَاضُ فِي عَنْفَقَتِهِ وَفِي الصُّدْغَيْنِ، وَفِي الرَّأْسِ نَبْذٌ."],"takhrij":"متفق عليه: رواه مسلم في الفضائل (2341: 104) عن نصر بن علي الجهضمي، حدثنا أبي، حدثنا المثنى بن سعيد، عن قتادة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2341:104) and al-Bukhārī (3550).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik said: “It is disliked for a man to pluck a white hair from his head or beard.” He continued: “The Messenger of Allah ﷺ did not dye his hair. The whiteness was only in his ʿanfaqah, at his temples, and in a few scattered hairs on his head.”"]},"buhuth":{"en":["Regarding “ʿanfaqah,” Ibn al-Athīr said:","“It is the hair at the lower lip; it has also been said to mean the hair between the lower lip and the chin. The root of the word indicates smallness and scarcity.”","The “ṣudghayn” are the two temple areas between the ear and the eye. The word may also refer to the hair hanging down from the head in that area.","Fatḥ al-Bārī (6/572)."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9458],"tks":"متفق عليه: رواه مسلم (2341: 104)، والبخاري (3550)."},{"num":15441,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ سِيرِينَ، قَالَ:  سَأَلْتُ أَنَسَ بْنَ مَالِكٍ أَخَضَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: إِنَّهُ لَمْ يَرَ مِنَ الشَّيْبِ إِلَّا قَلِيلًا."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5894)، ومسلم في الفضائل (2341: 102) كلاهما من حديث وهيب بن خالد، عن أيوب، عن محمد بن سيرين فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5894) and Muslim (2341:102).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Muḥammad ibn Sīrīn narrated: I asked Anas ibn Mālik: “Did the Prophet ﷺ dye his hair?” He replied: “He had only a small amount of gray hair.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5894)، ومسلم (2341: 102)."},{"num":15442,"demo":false,"sanad":"","matn":["عَنِ ابْنِ سِيرِينَ، قَالَ:  سَأَلْتُ أَنَسَ بْنَ مَالِكٍ هَلْ كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَضَبَ؟ فَقَالَ: لَمْ يَبْلُغِ الْخِضَابَ، كَانَ فِي لِحْيَتِهِ شَعَرَاتٌ بِيضٌ. قَالَ: قُلْتُ لَهُ: أَكَانَ أَبُو بَكْرٍ يَخْضِبُ؟ قَالَ: فَقَالَ: نَعَمْ، بِالْحِنَّاءِ وَالْكَتَمِ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2341: 101) عن محمد بن بكار بن الريان، حدثنا إسماعيل بن زكرياء، عن عاصم الأحول، عن ابن سيرين فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2341:101).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ibn Sīrīn narrated: I asked Anas ibn Mālik: “Did the Messenger of Allah ﷺ dye his hair?” He replied: “His gray hair never became sufficient to require dyeing. There were only a few white hairs in his beard.” I asked: “Did Abū Bakr dye his hair?” He replied: “Yes, with henna and katam.”"]},"buhuth":{"en":["Note: According to the author, the hadith of Anas may indicate denial of frequent dyeing, the small amount involved, or differences between different periods of the life of the Prophet ﷺ. At times he may have dyed his hair, while at other times he left it undyed.","The report of Ibn ʿUmar that he saw the Prophet ﷺ dyeing with yellow coloring, and the report of Umm Salamah saying:","“I saw reddish hairs,”","are given precedence over the general denial reported from Anas.","As for the varying reports concerning the amount of his gray hair, the correct understanding is that it was only a small amount. Those who denied it meant that it was not abundant.","For more, see The Book of Sīrah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2341: 101)."},{"num":15443,"demo":false,"sanad":"","matn":["عن حريز بن عُثْمَانَ أَنَّهُ سَأَلَ عَبْدَ اللَّهِ بْنَ بُسْرٍ صَاحِبَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: أَرَأَيْتَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ شَيْخًا؟ قَالَ: كَانَ فِي عَنْفَقَتِهِ شَعَرَاتٌ بِيضٌ."],"takhrij":"صحيح: رواه البخاري في المناقب (3546) عن عصام بن خالد، حدثنا حريز بن عثمان، أنه سأل عبد الله بن بسر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3546).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Ḥarīz ibn ʿUthmān narrated: He asked ʿAbdullāh ibn Busr, a Companion of the Prophet ﷺ: “Did you see the Prophet ﷺ as an elderly man?” He replied: “There were a few white hairs in his ʿanfaqah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (3546)."},{"num":15444,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُحَيْفَةَ قَالَ:  رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَذِهِ مِنْهُ بَيْضَاءَ - وَوَضَعَ زُهَيْرٌ بَعْضَ أَصَابِعِهِ عَلَى عَنْفَقَتِهِ، قِيلَ لَهُ: مِثْلُ مَنْ أَنْتَ يَوْمَئِذٍ؟ فَقَالَ: أَبْرِي النَّبْلَ وَأَرِيشُهَا."],"takhrij":"متفق عليه: رواه مسلم في الفضائل (2342) من طرق عن زهير أبي خيثمة، عن أبي إسحاق، عن أبي جحيفة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (2342) and al-Bukhārī (3545).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Abū Juḥayfah narrated: “I saw the Messenger of Allah ﷺ, and this part of him was white.” Zuhayr placed some of his fingers on his ʿanfaqah to indicate the location. Abū Juḥayfah was asked: “How old were you at that time?” He replied: “I was old enough to straighten arrows and attach feathers to them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (2342)، والبخاري (3545)."},{"num":15445,"demo":false,"sanad":"","matn":["عَنْ سِمَاكِ بْنِ حَرْبٍ قَالَ:  سَمِعْتُ جَابِرَ بْنَ سَمُرَةَ سُئِلَ عَنْ شَيْبِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: كَانَ إِذَا دَهَنَ رَأْسَهُ لَمْ يُرَ مِنْهُ شَيْءٌ، وَإِذَا لَمْ يَدْهُنْ رُئِيَ مِنْهُ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2344) عن محمد بن المثنى، حدثنا أبو داود سليمان بن داود، حدثنا شعبة، عن سماك بن حرب، فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2344).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Simāk ibn Ḥarb narrated: I heard Jābir ibn Samurah being asked about the gray hair of the Prophet ﷺ. He replied: “When he oiled his hair, none of it could be seen; but when he did not oil it, some gray hairs could be seen.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2344)."},{"num":15446,"demo":false,"sanad":"","matn":["عن جابر بْنِ سَمُرَةَ، يَقُولُ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ شَمِطَ مُقَدَّمُ رَأْسِهِ وَلِحْيَتِهِ، وَكَانَ إِذَا ادَّهَنَ لَمْ يَتَبَيَّنْ، وَإِذَا شَعِثَ رَأْسُهُ تَبَيَّنَ، وَكَانَ كَثِيرَ شَعْرِ اللِّحْيَةِ، فَقَالَ رَجُلٌ: وَجْهُهُ مِثْلُ السَّيْفِ؟ قَالَ: لَا، بَلْ كَانَ مِثْلَ الشَّمْسِ وَالْقَمَرِ، وَكَانَ مُسْتَدِيرًا، وَرَأَيْتُ الْخَاتَِمَ عِنْدَ كَتِفِهِ مِثْلَ بَيْضَةِ الْحَمَامَةِ يُشْبِهُ جَسَدَهُ."],"takhrij":"صحيح: رواه مسلم في الفضئل (2344: 109) عن أبي بكر بن أبي شيبة، حدثنا عبيد الله، عن إسرائيل، عن سماك، أنه سمع جابر بن سمرة، يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2344:109).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Jābir ibn Samurah narrated: The front of the head of the Messenger of Allah ﷺ and his beard had begun to show some gray hair. When he applied oil, it was not noticeable, but when his hair was disheveled, it became visible. His beard was thick. A man asked: “Was his face like a sword?” He replied: “No. Rather, it was like the sun and the moon, and it was rounded.” He continued: “I saw the Seal near his shoulder. It was like a pigeon’s egg and resembled the color of his body.”"]}},"tuhfa":{},"full":1,"rep":[9444],"tks":"صحيح: رواه مسلم (2344: 109)."},{"num":15447,"demo":false,"sanad":"","matn":["عَنْ زَيْدٍ، - يَعْنِي ابْنَ أَسْلَمَ، - أَنَّ ابْنَ عُمَرَ، كَانَ يَصْبُغُ لِحْيَتَهُ بِالصُّفْرَةِ حَتَّى تَمْتَلِئَ ثِيَابُهُ مِنَ الصُّفْرَةِ، فَقِيلَ لَهُ: لِمَ تَصْبُغُ بِالصُّفْرَةِ؟ فَقَالَ: إِنِّي رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَصْبُغُ بِهَا، وَلَمْ يَكُنْ شَىْءٌ أَحَبَّ إِلَيْهِ مِنْهَا، وَقَدْ كَانَ يَصْبُغُ بِهَا ثِيَابَهُ كُلَّهَا حَتَّى عِمَامَتَهُ."],"takhrij":"حسن: رواه أبو داود (4064)، والنسائي (5086) كلاهما من حديث عبدالعزيز يعني ابن محمد، عن زيد بن أسلم فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الخضاب وتغيير الشيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4064) and al-Nasā’ī (5086).","chapter_en":"What Has Been Narrated Concerning Dyeing and Changing Gray Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":6,"content":{"translation":{"en":["Zayd ibn Aslam narrated: Ibn ʿUmar used to dye his beard yellow until his clothes became stained with yellow. He was asked: “Why do you dye with yellow?” He replied: “I saw the Messenger of Allah ﷺ dyeing with it, and nothing was more beloved to him than it. He even used to dye all his clothes with it, including his turban.”"]},"buhuth":{"en":["The wording:","“He used to dye all his clothes with it…”","is anomalous according to the author.","The correct reading, in accordance with the beginning of the hadith, refers to the beard. The statement of ʿUbayd ibn Jurayj is understood in this way as well, since the narration of Aḥmad (4672) explicitly states that he used to dye his beard yellow.","Abū Salamah ibn ʿAbd al-Raḥmān reported that ʿAbd al-Raḥmān ibn al-Aswad ibn ʿAbd Yaghūth, whose beard and hair had become white, came to them one day after dyeing them red. The people told him it looked better. He replied that ʿĀ’ishah, the wife of the Prophet ﷺ, had sent her servant Nukhaylah to him the previous night and insisted that he dye his hair, and told him that Abū Bakr al-Ṣiddīq used to dye his hair.","Narrated by Mālik in The Book of Hair (8). Its chain is authentic, though the report is mawqūf.","Yaḥyā related that Mālik said concerning dyeing the hair black: “I have not heard anything firmly established concerning it; other dyes are preferable to me. Leaving dye altogether is also broad and permissible, Allah willing; there is no hardship upon people in it.”","Mālik also said that this report indicates that the Messenger of Allah ﷺ did not dye his hair; had he done so, ʿĀ’ishah would have conveyed that to ʿAbd al-Raḥmān ibn al-Aswad.","A report from Ibn ʿAbbās states that the Prophet ﷺ praised a man dyed with henna, then preferred another dyed with henna and katam, and then praised most a man dyed yellow. It was narrated by Abū Dāwūd (4211), Ibn Mājah (3627), and al-Bayhaqī (7/310). The author judges its chain weak because of Ḥumayd ibn Wahb al-Qurashī Abū Wahb al-Makkī, who narrated it alone.","As for the report from Ibn Masʿūd listing ten practices that the Prophet ﷺ disliked, including “changing gray hair,” the author judges it munkar. It is narrated by Abū Dāwūd (4222), al-Nasā’ī (5088), Aḥmad (3605), and was authenticated by Ibn Ḥibbān (5682) and al-Ḥākim (4/195), but ʿAbd al-Raḥmān ibn Ḥarmalah did not hear from Ibn Masʿūd, and Qāsim ibn Ḥassān is not accepted without corroboration. The author therefore states that it does not meet the conditions of al-Jāmiʿ al-Kāmil, although some of its individual clauses have authentic supporting evidence.","Fiqh of the Hadiths in This Chapter","The hadiths of this chapter indicate that dyeing gray hair is recommended for men.","The early Muslims differed regarding dyeing with black. Some disliked it because of Jābir’s report, “Avoid black.” Much of the practice of the early Muslims followed this view, and they used yellow dye; among them were Ibn ʿUmar, Abū Hurayrah, Abū Umāmah, Jarīr ibn ʿAbdullāh, al-Mughīrah ibn Shuʿbah, ʿAbdullāh ibn Busr, and others.","Others did not dislike it and permitted black dye, including ʿUthmān, al-Ḥasan and al-Ḥusayn the sons of ʿAlī, ʿUqbah ibn ʿĀmir, Ibn Sīrīn, Abū Burdah, al-Zuhrī, Abū Salamah ibn ʿAbd al-Raḥmān, and others.","Muḥammad ibn ʿAlī was asked about wasmah and said: “It is the dye of us, the People of the Household.” Ayyūb related from Muḥammad ibn Sīrīn: “I know of no harm in black dye except when a man uses it to deceive a woman.”","Al-Zuhrī said: “The Prophet ﷺ commanded the use of dyes, and the darkest of them is most beloved to us,” meaning the blackest. ʿAbd al-Razzāq (20176) narrated it from Maʿmar from al-Zuhrī.","The early Muslims likewise allowed women to blacken their hair. ʿAbd al-Razzāq reported from Qatādah that he permitted black hair dye for women. Umm Shabīb also reported that when they asked ʿĀ’ishah about blackening the hair, she said she wished she had something with which to blacken her own hair.","Other scholars saw no harm in leaving gray hair undyed. Mālik said that leaving dye altogether is broad and permissible for people. Some Mālikīs even disliked changing gray hair because it is described as light in the hadiths; a prohibition of changing gray hair has also been reported, but it is not established.","Among the early Muslims from whom leaving the hair undyed is reported are Abū Bakr, ʿUmar, and ʿAlī, although contrary reports also exist from them. Ubayy ibn Kaʿb, Jābir ibn ʿAbdullāh, Abū Saʿīd al-Khudrī, and others are also reported to have left their hair and beards white.","Saʿīd ibn Jubayr said: “One of you takes a light that Allah has placed in his face and extinguishes it.” Saʿīd ibn al-Musayyib himself had very white hair and beard.","The matter is broad. Accordingly, the Shāfiʿīs held that the choice depends on people’s circumstances, while the Ḥanafīs and Ḥanbalīs regarded dyeing as recommended, and no one made it obligatory. Avoiding black dye is preferable in order to avoid the area of disagreement."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4064)، والنسائي (5086)."},{"num":15448,"demo":false,"sanad":"","matn":["عن عمر بن الخطاب قال: من ضفر رأسه فليحلق، ولا تشبهوا بالتلبيد."],"takhrij":"صحيح: رواه مالك في الحج (204) عن نافع، عن ابن عمر، عن عمر فذكره.","grade":"صحيح","chapter_ar":"باب التلبيد","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in The Book of Ḥajj (204).","chapter_en":"Matting the Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":7,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb said: “Whoever braids his hair should shave it, and do not imitate the practice of matting the hair.”"]},"buhuth":{"en":["However, his son ʿAbdullāh ibn ʿUmar differed with him, as al-Bukhārī narrated in The Book of Clothing (5914) through his chain that ʿAbdullāh ibn ʿUmar said:","“I heard ʿUmar say: ‘Whoever braids his hair should shave it, and do not imitate the practice of matting the hair.’”","Ibn ʿUmar, however, used to say:","“I certainly saw the Messenger of Allah ﷺ with his hair matted.”","The meaning is that ʿUmar ibn al-Khaṭṭāb considered shaving obligatory for one who matted his hair while in iḥrām.","His son ʿAbdullāh differed with him and said:","“I saw the Messenger of Allah ﷺ with his hair matted.”","He therefore did not consider shaving obligatory for one who had matted his hair. Although the Prophet ﷺ himself shaved, he also permitted shortening the hair."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (204)."},{"num":15449,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحِبُّ مُوَافَقَةَ أَهْلِ الْكِتَابِ فِيمَا لَمْ يُؤْمَرْ فِيهِ، وَكَانَ أَهْلُ الْكِتَابِ يَسْدِلُونَ أَشْعَارَهُمْ، وَكَانَ الْمُشْرِكُونَ يَفْرُقُونَ رُءُوسَهُمْ، فَسَدَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَاصِيَتَهُ، ثُمَّ فَرَقَ بَعْدُ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5917)، ومسلم في الفضائل (23361) كلاهما من طريق إبراهيم بن سعد، حدثنا ابن شهاب، عن عبيدالله بن عبدالله، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فرق شعر الرأس","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5917) and Muslim (2336).","chapter_en":"What Has Been Narrated Concerning Parting the Hair of the Head","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ liked to agree with the People of the Book in matters concerning which he had received no command. The People of the Book would let their hair fall straight down, while the polytheists would part their hair. So the Prophet ﷺ initially let his forelock fall straight down, then later parted his hair."]},"buhuth":{"en":["The phrase “they would let their hair fall” means that they allowed it to hang down without parting it.","To part the hair means to divide it from the central parting of the head. The mafariq is the place where the hair divides from the forehead toward the crown of the head."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5917)، ومسلم (23361)."},{"num":15450,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: كُنْتُ إِذَا أَرَدْتُ أَنْ أَفْرِقَ رَأْسَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَدَعْتُ الْفَرْقَ مِنْ يَافُوخِهِ، وَأُرْسِلُ نَاصِيَتَهُ بَيْنَ عَيْنَيْهِ."],"takhrij":"حسن: رواه أبو داود (4189) عن يحيى بن خلف، حدثنا عبد الأعلى، عن محمد بن إسحاق، حدثني محمد بن جعفر بن الزبير، عن عروة، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في فرق شعر الرأس","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4189).","chapter_en":"What Has Been Narrated Concerning Parting the Hair of the Head","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":8,"content":{"translation":{"en":["ʿĀ’ishah narrated: “When I wanted to part the hair of the Messenger of Allah ﷺ, I would make the parting from the crown of his head and let his forelock fall between his eyes.”"]},"buhuth":{"en":["Her statement “I made the parting” means that she divided his hair.","The “yāfūkh” is the crown or middle of the head.","Its chain is good because Muḥammad ibn Isḥāq explicitly stated that he heard the report.","Aḥmad (24594) also narrated it through Ibrāhīm ibn Saʿd from Muḥammad ibn Isḥāq.","Ibn Mājah (3633) narrated another route from ʿĀ’ishah in which she said: “I used to part the hair behind the crown of the Messenger of Allah ﷺ, then let the hair of his forelock fall forward.”","Al-Dāraquṭnī stated in al-ʿIlal (3568) that both routes are preserved."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4189)."},{"num":15451,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: بِتُّ لَيْلَةً عِنْدَ مَيْمُونَةَ بِنْتِ الْحَارِثِ خَالَتِي، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَهَا فِي لَيْلَتِهَا، ـ قَالَ: ـ فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُصَلِّي مِنَ اللَّيْلِ، فَقُمْتُ عَنْ يَسَارِهِ. ـ قَالَ: ـ فَأَخَذَ بِذُؤَابَتِي فَجَعَلَنِي عَنْ يَمِينِهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5919) من طريق هشيم (هو ابن بشير)، عن أبي بشر (هو جعفر بن أبي وحشية)، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب في اتخاذ ذؤابة من شعر الرأس","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5919) and Muslim (763).","chapter_en":"Keeping a Lock of Hair on the Head","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās narrated: I spent a night at the home of my maternal aunt Maymūnah bint al-Ḥārith, and the Messenger of Allah ﷺ was with her that night. The Messenger of Allah ﷺ stood to pray during the night, so I stood on his left. He took hold of my lock of hair and moved me to his right."]},"buhuth":{"en":["Regarding the words “he took hold of my lock of hair,” al-Ḥāfiẓ said:","“This contains the tacit approval of the Prophet ﷺ of keeping a lock of hair.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5919)، ومسلم (763)."},{"num":15452,"demo":false,"sanad":"","matn":["عَنْ وَائِلِ بْنِ حُجْرٍ، قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِي شَعْرٌ طَوِيلٌ، فَلَمَّا رَآنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ذُبَابٌ ذُبَابٌ. قَالَ: فَرَجَعْتُ فَجَزَزْتُهُ، ثُمَّ أَتَيْتُهُ مِنَ الْغَدِ. فَقَالَ: إِنِّي لَمْ أَعْنِكَ، وَهَذَا أَحْسَنُ."],"takhrij":"حسن: رواه أبو داود (4190)، والنسائي (5052، 5066)، وابن ماجه (3636) كلهم من حديث سفيان، عن عاصم بن كليب، عن أبيه، عن وائل بن حجر فذكره.","grade":"حسن","chapter_ar":"باب كراهية تطويل الشعر بدون تهذيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4190), al-Nasā’ī (5052, 5066), and Ibn Mājah (3636).","chapter_en":"Dislike of Growing the Hair Long Without Grooming It","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Wā’il ibn Ḥujr narrated: I came to the Prophet ﷺ while I had long hair. When the Messenger of Allah ﷺ saw me, he said: “An ill-looking thing, an ill-looking thing.” I returned and cut my hair. Then I came to him the following day, and he said: “I did not mean you specifically, but this is better.”"]},"buhuth":{"en":["The word “dhubāb” may mean ill omen or something unpleasant.","It has also been said to mean persistent evil. One may say:","“A dhubāb from this matter has afflicted you.”","This is mentioned in al-Nihāyah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4190)، والنسائي (5052، 5066)، وابن ماجه (3636)."},{"num":15453,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ فَاتِكٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نِعْمَ الْفَتَى سَمُرَةُ، لَوْ أَخَذَ مِنْ لِمَّتِهِ، وَشَمَّرَ مِنْ مِئْزَرِهِ. فَفَعَلَ ذَلِكَ سَمُرَةُ، أَخَذَ مِنْ لِمَّتِهِ، وَشَمَّرَ، مِنْ مِئْزَرِهِ."],"takhrij":"حسن: رواه أحمد (17788) عن يعمر بن بشر قال: حدثنا عبد الله قال: حدثنا هشيم، عن داود بن عمرو، عن بسر بن عبيد الله، عن سمرة بن فاتك فذكره.","grade":"حسن","chapter_ar":"باب كراهية تطويل الشعر بدون تهذيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17788).","chapter_en":"Dislike of Growing the Hair Long Without Grooming It","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Samurah ibn Fātik narrated that the Prophet ﷺ said: “What an excellent young man Samurah is, if only he would shorten his hair and raise his izār.” So Samurah did that: he shortened his hair and raised his izār."]},"buhuth":{"en":["The “limmah” is hair that extends beyond the earlobes.","The word “shammara” means to shorten or raise.","Samurah ibn Fātik and his brother Khuraym ibn Fātik accepted Islam after the Conquest. Scholars differed regarding their lineage, and it has been said that they were from Banū Asad, which the author considers the stronger view."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17788)."},{"num":15454,"demo":false,"sanad":"","matn":["عَنْ قَيْسِ بْنِ بِشْرٍ التَّغْلِبِيِّ قَالَ: أَخْبَرَنِي أَبِي -وَكَانَ جَلِيسًا لأَبِي الدَّرْدَاءِ- قَالَ: كَانَ بِدِمَشْقَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ: ابْنُ الْحَنْظَلِيَّةِ، وَكَانَ رَجُلاً مُتَوَحِّدًا، قَلَّمَا يُجَالِسُ النَّاسَ، إِنَّمَا هُوَ فِي صَلاَةٌ فَإِذَا فَرَغَ فَإِنَّمَا يسبح ويكبر حَتَّى يَأْتِيَ أَهْلَهُ، فَمَرَّ بِنَا يَوْمًا وَنَحْنُ عِنْدَ أَبِي الدَّرْدَاءِ، فَقَالَ لَهُ أَبُو الدَّرْدَاءِ: كَلِمَةً تَنْفَعُنَا وَلاَ تَضُرُّكَ. قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَرِيَّةً فَقَدِمَتْ، فَجَاءَ رَجُلٌ مِنْهُمْ، فَجَلَسَ فِي الْمَجْلِسِ الَّذِي فِيهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ لِرَجُلٍ إِلَى جَنْبِهِ: لَوْ رَأَيْتَنَا حِينَ الْتَقَيْنَا نَحْنُ وَالْعَدُوُّ، فَحَمَلَ فُلاَنٌ فَطَعَنَ، فَقَالَ: خُذْهَا وَأَنَا الْغُلاَمُ الْغِفَارِيُّ. كَيْفَ تَرَى فِي قَوْلِهِ؟ قَالَ: مَا أُرَاهُ إِلاَّ قَدْ أبطل أَجْرُهُ. فَسَمِعَ ذَلِكَ آخَرُ، فَقَالَ: مَا أَرَى بِذَلِكَ بَأْسًا. فَتَنَازَعَا حَتَّى سَمِعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: سُبْحَانَ اللَّهِ لاَ بَأْسَ أَنْ يحمد ويؤجر. قَالَ: فَرَأَيْتُ أَبَا الدَّرْدَاءِ سُرَّ بِذَلِكَ، وَجَعَلَ يَرْفَعُ رَأْسَهُ إِلَيْهِ، وَيَقُولُ: آنت سَمِعْتَ ذَلِكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ ؟ فَيَقُولُ: نَعَمْ. فَمَا زَالَ يُعِيدُ عَلَيْهِ حَتَّى إِنِّي لأَقُولُ: لَيَبْرُكَنَّ عَلَى رُكْبَتَيْهِ.","قَالَ: ثُمَّ مَرَّ بِنَا يَوْمًا آخَرَ، فَقَالَ لَهُ أَبُو الدَّرْدَاءِ: كَلِمَةٌ تَنْفَعُنَا وَلاَ تَضُرُّكَ قَالَ: قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيهِ وسلم: إِنَّ الْمُنْفِقَ عَلَى الْخَيْلِ فِى سَبِيلِ اللَّهِ كَبَاسِطِ يَدَيْهِ بِالصَّدَقَةِ لاَ يَقْبِضُهَا.","قَالَ: ثُمَّ مَرَّ بِنَا يَوْمًا آخَرَ، فَقَالَ لَهُ أَبُو الدَّرْدَاءِ: كَلِمَةً تَنْفَعُنَا وَلَا تَضُرُّكَ. فَقَالَ: قَالَ رَسُولُ اللهِ صلى الله عليه وسلم: نِعْمَ الرَّجُلُ خُرَيْمٌ الْأَسَدِيُّ لَوْلَا طُولُ جُمَّتِهِ وَإِسْبَالُ إِزَارِهِ، فَبَلَغَ ذَلِكَ خُرَيْمًا، فَجَعَلَ يَأْخُذُ شَفْرَةً يقطع بِهَا شَعَرَهُ إِلَى أَنْصَافِ أُذُنَيْهِ، وَرَفَعَ إِزَارَهُ إِلَى أَنْصَافِ سَاقَيْهِ.","قَالَ: فَأَخْبَرَنِي أَبِي قَالَ: دَخَلْتُ بَعْدَ ذَلِكَ عَلَى مُعَاوِيَةَ، فَإِذَا عِنْدَهُ شَيْخٌ جُمَّتُهُ فَوْقَ أُذُنَيْهِ، وَرِدَاؤُهُ إِلَى سَاقَيْهِ، فَسَأَلْتُ عَنْهُ، فَقَالُوا: هَذَا خُرَيْمٌ الْأَسَدِيُّ.","قَالَ: ثُمَّ مَرَّ بِنَا يَوْمًا آخَرَ، وَنَحْنُ عِنْدَ أَبِي الدَّرْدَاءِ، فَقَالَ لَهُ أَبُو الدَّرْدَاءِ: كَلِمَةً تَنْفَعُنَا وَلَا تَضُرُّكَ، فَقَالَ سَمِعْتُ رَسُولَ اللهِ صلى الله عليه وسلم يَقُولُ: إِنَّكُمْ قَادِمُونَ عَلَى إِخْوَانِكُمْ، فَأَصْلِحُوا رِحَالَكُمْ، وَأَصْلِحُوا لِبَاسَكُمْ؛ فَإِنَّ اللهَ عز وجل لَا يُحِبُّ الْفُحْشَ، وَلَا التَّفَحُّشَ."],"takhrij":"حسن: رواه أبو داود (4089)، وأحمد (17622)، والحاكم (4/183)، والبيهقي في الشعب (5793) كلهم من حديث هشام بن سعد، قال: حدثنا قيس بن بشر التغلبي قال: أخبرني أبي –وكان جليسا لأبي الدرداء- قال: فذكره.","grade":"حسن","chapter_ar":"باب كراهية تطويل الشعر بدون تهذيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4089), Aḥmad (17622), al-Ḥākim (4/183), and al-Bayhaqī in Shuʿab al-Īmān (5793).","chapter_en":"Dislike of Growing the Hair Long Without Grooming It","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":10,"content":{"translation":{"en":["Qays ibn Bishr al-Taghlibī narrated: My father, who used to sit with Abū al-Dardāʾ, told me: There was a man in Damascus from the Companions of the Prophet ﷺ named Ibn al-Ḥanẓaliyyah. He was a solitary man who rarely sat with people. He was usually occupied with prayer, and when he finished, he would continue glorifying Allah and saying Allāhu akbar until he returned to his family. One day he passed by us while we were with Abū al-Dardāʾ. Abū al-Dardāʾ said to him: “Tell us something that will benefit us and not harm you.” He said: The Messenger of Allah ﷺ sent out a military detachment. When they returned, one of the men came and sat in the gathering where the Messenger of Allah ﷺ was sitting. He said to the man beside him: “If only you had seen us when we met the enemy! So-and-so charged and stabbed a man, saying: ‘Take this from me, and I am the Ghifārī youth!’ What do you think about what he said?” The man replied: “I think his reward has been nullified.” Another man heard this and said: “I see nothing wrong with it.” They disputed until the Prophet ﷺ heard them and said: “Glory be to Allah! There is no harm in a person being praised while still receiving reward.” My father said: I saw Abū al-Dardāʾ become pleased by this. He kept raising his head toward him and asking: “Did you hear this from the Messenger of Allah ﷺ?” He would reply: “Yes.” Abū al-Dardāʾ kept repeating the question so often that I thought he might fall to his knees before him. Then Ibn al-Ḥanẓaliyyah passed us another day. Abū al-Dardāʾ said: “Tell us something that will benefit us and not harm you.” He said: The Messenger of Allah ﷺ said to us: “The one who spends upon horses in the path of Allah is like one who keeps his hands stretched out continuously in charity and never closes them.” Then he passed us another day.","Abū al-Dardāʾ again said: “Tell us something that will benefit us and not harm you.” He said: The Messenger of Allah ﷺ said: “Khuraym al-Asadī is an excellent man, were it not for the length of his hair and the lowering of his izār.” When this reached Khuraym, he took a blade and cut his hair until it reached halfway down his ears, and he raised his izār to the middle of his shins. My father said: Later, I entered upon Muʿāwiyah and saw an elderly man with his hair extending above his ears and his cloak reaching his shins.","I asked who he was, and they said: “This is Khuraym al-Asadī.” Then Ibn al-Ḥanẓaliyyah passed by us another day while we were with Abū al-Dardāʾ. Abū al-Dardāʾ said: “Tell us something that will benefit us and not harm you.” He said: The Messenger of Allah ﷺ said: “You are going to meet your brothers, so put your riding equipment in good order and improve your clothing, for Allah, Mighty and Majestic, does not love obscenity or deliberately behaving obscenely.”"]},"buhuth":{"en":["Al-Ḥākim said: “Its chain is authentic.” The author judges the chain good because of Bishr al-Taghlibī, the father of Qays, whom al-Ḥāfiẓ described as truthful, and because his son Qays is a narrator of the Ṣaḥīḥ collections; Abū Ḥātim said there was no problem with his hadith.","As for Aḥmad’s report (18899), through Abū Isḥāq from Shamir from Khuraym, with the wording concerning letting the izār hang and leaving the hair long, the author judges it weak because Shamir ibn ʿAṭiyyah al-Asadī did not meet Khuraym. Its other routes are likewise not free of defects."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4089)، وأحمد (17622)، والحاكم (4/183)، والبيهقي في الشعب (5793)."},{"num":15455,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ جَعْفَرٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمْهَلَ آلَ جَعْفَرٍ ثَلاَثًا أَنْ يَأْتِيَهُمْ، ثُمَّ أَتَاهُمْ، فَقَالَ: لاَ تَبْكُوا عَلَى أَخِي بَعْدَ الْيَوْمِ. ثُمَّ قَالَ: ادْعُوا لِي بَنِي أَخِي. فَجِيءَ بِنَا كَأَنَّا أَفْرُخٌ، فَقَالَ: ادْعُوا لِي الْحَلاَّقَ. فَأَمَرَهُ فَحَلَقَ رُءُوسَنَا."],"takhrij":"صحيح: رواه أبو داود (4192)، والنسائي (5227) كلاهما من حديث وهب بن جرير، حدثنا أبي، قال: سمعت محمد بن أبي يعقوب، يحدث عن الحسن بن سعد، عن عبد الله بن جعفر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب حلق الشعر كله، والنهي عن القزع","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4192) and al-Nasā’ī (5227).","chapter_en":"Shaving All the Hair and the Prohibition of Qazaʿ","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn Jaʿfar narrated: The Prophet ﷺ gave the family of Jaʿfar three days before visiting them. Then he came to them and said: “Do not weep for my brother after today.” Then he said: “Bring me the sons of my brother.” We were brought to him looking like little chicks. He then said: “Call the barber for me.” He ordered the barber to shave our heads."]},"buhuth":{"en":["Aḥmad (1750) narrated the report of ʿAbdullāh ibn Jaʿfar by the same route in a longer form, which is cited in its appropriate place."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4192)، والنسائي (5227)."},{"num":15456,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى صَبِيًّا قَدْ حُلِقَ بَعْضُ شَعْرِهِ وَتُرِكَ بَعْضُهُ، فَنَهَاهُمْ عَنْ ذَلِكَ، وَقَالَ: احْلِقُوهُ كُلَّهُ، أَوِ اتْرُكُوهُ كُلَّهُ."],"takhrij":"صحيح: رواه أبو داود (4195)، والنسائي (5048)، وأحمد (5615) كلهم عن عبد الرزاق –وهو في مصنفه (19564)- حدثنا معمر، عن أيوب، عن نافع، عن ابن عمر، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب حلق الشعر كله، والنهي عن القزع","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4195), al-Nasā’ī (5048), and Aḥmad (5615).","chapter_en":"Shaving All the Hair and the Prohibition of Qazaʿ","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Prophet ﷺ saw a boy whose head had been partially shaved while part of his hair had been left. He prohibited them from doing that and said: “Shave all of it, or leave all of it.”"]},"buhuth":{"en":["Muslim (2120) transmitted this chain without repeating the wording, referring instead to the wording immediately before it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4195)، والنسائي (5048)، وأحمد (5615)."},{"num":15457,"demo":false,"sanad":"","matn":["عُبَيْدُ اللَّهِ بْنُ حَفْصٍ، أَنَّ عُمَرَ بْنَ نَافِعٍ، أَخْبَرَهُ، عَنْ نَافِعٍ، مَوْلَى عَبْدِ اللَّهِ: أَنَّهُ سَمِعَ ابْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنِ الْقَزَعِ.","قَالَ عُبَيْدُ اللَّهِ: قُلْتُ: وَمَا الْقَزَعُ؟ فَأَشَارَ لَنَا عُبَيْدُ اللَّهِ قَالَ: إِذَا حَلَقَ الصَّبِيَّ، وَتَرَكَ هَا هُنَا شَعَرَةً وَهَا هُنَا وَهَا هُنَا، فَأَشَارَ لَنَا عُبَيْدُ اللَّهِ إِلَى نَاصِيَتِهِ وَجَانِبَىْ رَأْسِهِ.","قِيلَ لِعُبَيْدِ اللَّهِ: فَالْجَارِيَةُ وَالْغُلاَمُ؟ قَالَ: لاَ أَدْرِي، هَكَذَا قَالَ: الصَّبِيِّ. قَالَ عُبَيْدُ اللَّهِ: وَعَاوَدْتُهُ، فَقَالَ: أَمَّا الْقُصَّةُ وَالْقَفَا لِلْغُلاَمِ فَلاَ بَأْسَ بِهِمَا، وَلَكِنَّ الْقَزَعَ أَنْ يُتْرَكَ بِنَاصِيَتِهِ شَعَرٌ، وَلَيْسَ فِي رَأْسِهِ غَيْرُهُ، وَكَذَلِكَ شَقُّ رَأْسِهِ هَذَا وَهَذَا."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5920) من طريق ابن جريج قال: أخبرني عبيدالله بن حفص به فذكره. هذا لفظ البخاري.","grade":"متفق عليه","chapter_ar":"باب حلق الشعر كله، والنهي عن القزع","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5920) and Muslim (2120).","chapter_en":"Shaving All the Hair and the Prohibition of Qazaʿ","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":11,"content":{"translation":{"en":["ʿUbaydullāh ibn Ḥafṣ narrated that ʿUmar ibn Nāfiʿ informed him, from Nāfiʿ, the freedman of ʿAbdullāh ibn ʿUmar, that he heard Ibn ʿUmar say: “I heard the Messenger of Allah ﷺ prohibit qazaʿ.” ʿUbaydullāh said: I asked: “What is qazaʿ?” ʿUbaydullāh gestured for us and said: “It is when a boy’s head is shaved, but hair is left here, here, and here.” He pointed to the forelock and both sides of the head. ʿUbaydullāh was asked: “Does this apply to girls as well as boys?”","He replied: “I do not know. He specifically said ‘the boy.’” ʿUbaydullāh said: I asked him again, and he replied: “As for the hair at the temples and the nape of the neck for a boy, there is no harm in that. Rather, qazaʿ is for hair to be left on his forelock while there is no hair elsewhere on his head, or for hair to be left on one side of the head and the other.”"]},"buhuth":{"en":["The questioner may have been ʿUmar ibn Nāfiʿ, his son, or it may have been ʿUbaydullāh asking on another occasion, with the narrator combining the hadith and its explanation into a single context.","The explanation is also narrated directly from ʿUbaydullāh himself. Aḥmad (4973) narrated from Muḥammad ibn Bishr, from ʿUbaydullāh, from ʿUmar ibn Nāfiʿ, from Nāfiʿ, from ʿAbdullāh ibn ʿUmar:","“The Messenger of Allah ﷺ prohibited qazaʿ.”","ʿUbaydullāh said:","“Qazaʿ is patchy shaving of the head.”","Thus, ʿUbaydullāh ibn ʿUmar sometimes attributed the explanation to Nāfiʿ and sometimes stated it himself.","Al-Nawawī said:","“Qazaʿ,” with fatḥah on the qāf and zāy, is most correctly understood according to the explanation of Nāfiʿ or ʿUbaydullāh: it means shaving part of the head in any manner while leaving another part.","Some said it specifically means shaving scattered patches of the head, but the first view is correct because it is the explanation of the narrator and does not contradict the apparent meaning, so it must be acted upon.”","Al-Ḥāfiẓ said:","“The specification of a boy is not restrictive.”","Meaning that the ruling is general and also includes men and women.","Regarding the statement:","“As for the quṣṣah and the nape of the neck for a boy, there is no harm in them,”","al-Ḥāfiẓ said:","“Al-quṣṣah, with ḍammah on the qāf, refers here to the hair at the temples, while the nape refers to the hair at the back of the neck. The conclusion is that qazaʿ specifically concerns the hair of the head, while the temple and nape hair are treated separately.”","Regarding the words “ʿUbaydullāh gestured to us,” there is an omitted expression. The meaning is that ʿUbaydullāh was transmitting ʿUmar ibn Nāfiʿ’s explanation that qazaʿ is when a boy’s head is shaved while patches of hair are left here and there.","Regarding the second gesture—“ʿUbaydullāh pointed to his forelock and the two sides of his head”—this is from ʿUbaydullāh himself, as al-ʿAynī explained (22/58)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5920)، ومسلم (2120)."},{"num":15458,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كُنْتُ أُطَيِّبُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَطْيَبِ مَا يَجِدُ، حَتَّى أَجِدَ وَبِيصَ الطِّيبِ فِي رَأْسِهِ وَلِحْيَتِهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5923)، ومسلم في الحج (1190: 44) كلاهما من طريق أبي إسحاق السبيعي، عن عبد الرحمن بن الأسود، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الطيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5923) and Muslim (1190:44).","chapter_en":"What Has Been Narrated Concerning Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah narrated: “I used to perfume the Prophet ﷺ with the finest perfume available, until I could see the glistening trace of perfume on his head and beard.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5923)، ومسلم (1190: 44)."},{"num":15459,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: طَيَّبْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِي بِذَرِيرَةٍ فِي حَجَّةِ الْوَدَاعِ لِلْحِلِّ وَالإِحْرَامِ. وَفِي رِوَايَةِ: بطيب فِيهِ مسك."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5930)، ومسلم في الحج (1189: 35) كلاهما من طريق ابن جريج، أخبرني عمر بن عبد الله بن عروة أنه سمع عروة والقاسم يخبران عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الطيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5930) and Muslim (1189:35).","chapter_en":"What Has Been Narrated Concerning Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah narrated: “I perfumed the Messenger of Allah ﷺ with my own hands using dharīrah during the Farewell Ḥajj, both when he was entering iḥrām and when he came out of it.” In another narration: “With perfume containing musk.”"]},"buhuth":{"en":["Dharīrah is a type of perfume made from a mixture of fragrant substances.","It has also been said to consist of fragments of a fragrant reed brought from India.","Fatḥ al-Bārī (10/371)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5930)، ومسلم (1189: 35)."},{"num":15460,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: كَانَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سُكَّةٌ يَتَطَيَّبُ مِنْهَا."],"takhrij":"صحيح: رواه أبو داود (4162)، والترمذي في الشمائل (217)، وأبو الشيخ في أخلاق النبي صلى الله عليه وسلم (ص 88) كلهم من حديث عبد الله بن المختار، عن موسى بن أنس، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الطيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4162), al-Tirmidhī in al-Shamā’il (217), and Abū al-Shaykh in Akhlāq al-Nabī ﷺ (p. 88).","chapter_en":"What Has Been Narrated Concerning Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik narrated: “The Prophet ﷺ had a perfume container from which he would apply fragrance.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4162)، والترمذي في الشمائل (217)، وأبو الشيخ في أخلاق النبي ﷺ (ص 88)."},{"num":15461,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  كَانَتِ امْرَأَةٌ مِنْ بَنِي إِسْرَائِيلَ، قَصِيرَةٌ تَمْشِي مَعَ امْرَأَتَيْنِ طَوِيلَتَيْنِ، فَاتَّخَذَتْ رِجْلَيْنِ مِنْ خَشَبٍ، وَخَاتَمًا مِنْ ذَهَبٍ مُغْلَقٌٍ مُطْبَقٌٍ، ثُمَّ حَشَتْهُ مِسْكًا، وَهُوَ أَطْيَبُ الطِّيبِ، فَمَرَّتْ بَيْنَ الْمَرْأَتَيْنِ، فَلَمْ يَعْرِفُوهَا، فَقَالَتْ: بِيَدِهَا هَكَذَا - وَنَفَضَ شُعْبَةُ يَدَهُ."],"takhrij":"صحيح: رواه مسلم في الألفاظ من الأدب (2252: 18) عن أبي بكر بن أبي شيبة، حدثنا أبو أسامة، عن شعبة، حدثني خليد بن جعفر، عن أبي نضرة، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الطيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2252:18).","chapter_en":"What Has Been Narrated Concerning Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Prophet ﷺ said: “There was a short woman among the Children of Israel who used to walk with two tall women. So she made for herself two wooden extensions for her feet and took a gold ring that was sealed and enclosed. She filled it with musk, which is the finest perfume. She then walked between the two women, and the people did not recognize her. She moved her hand like this.” Shuʿbah then shook his hand to demonstrate."]}},"tuhfa":{},"full":1,"rep":[8320],"tks":"صحيح: رواه مسلم (2252: 18)."},{"num":15462,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ قَالَ:  كَانَ ابْنُ عُمَرَ إِذَا اسْتَجْمَرَ اسْتَجْمَرَ بِالْأَلُوَّةِ غَيْرَ مُطَرَّاةٍ، وَبِكَافُورٍ يَطْرَحُهُ مَعَ الْأَلُوَّةِ، ثُمَّ قَالَ: هَكَذَا كَانَ يَسْتَجْمِرُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في الألفاظ من الأدب (2254) من طرق عن ابن وهب، أخبرني مخرمة، عن أبيه، عن نافع فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الطيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2254).","chapter_en":"What Has Been Narrated Concerning Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Nāfiʿ narrated: When Ibn ʿUmar burned incense, he would use unblended aloeswood together with camphor, placing the camphor with the aloeswood. Then he would say: “This is how the Messenger of Allah ﷺ used incense.”"]},"buhuth":{"en":["The word “yastajmir” here means to use fragrance by burning incense. It is derived from mijmar, an incense burner.","Al-aluwah, with either fatḥah or ḍammah on the initial hamzah and ḍammah on the lām, refers to aloeswood used as incense.","The phrase “ghayr muṭarrāh” means that it was not blended with other perfumes."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2254)."},{"num":15463,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَتْ تُعْجِبُهُ الْفَاغِيَةُ، وَكَانَ أَعْجَبُ الطَّعَامِ إِلَيْهِ الدُّبَّاءَ."],"takhrij":"حسن: رواه أحمد (12546) عن عبد الصمد، حدثنا سليمان –يعني ابن كثير-، حدثنا عبد الحميد، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الطيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12546).","chapter_en":"What Has Been Narrated Concerning Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":12,"content":{"translation":{"en":["Anas narrated: “The Messenger of Allah ﷺ liked the fragrance of fāghiyah, and the food he liked most was gourd.”"]},"buhuth":{"en":["The word “fāghiyah” comes from faghā–yafghū, referring to a flower opening.","It is also said:","“The thing faghā,”","when its fragrance becomes apparent.","Fāghiyah specifically refers to henna blossoms, and it can also refer to the blossom of any fragrant plant.","Henna blossoms are among the most pleasantly scented flowers.","It is also established that the Prophet ﷺ used henna medicinally, and this is cited in The Book of Medicine."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12546)."},{"num":15464,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ كَانَ لاَ يَرُدُّ الطِّيبَ، وَزَعَمَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ لاَ يَرُدُّ الطِّيبَ."],"takhrij":"صحيح: رواه البخاري في اللباس (5929) عن أبي نعيم (هو الفضل بن دُكين)، ثنا عزرة بن ثابت الأنصاري، ثني ثمامة بن عبد الله، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب كراهية رد الطيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5929).","chapter_en":"Dislike of Refusing Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Anas ibn Mālik would not refuse perfume, and he stated that: “The Prophet ﷺ would not refuse perfume.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5929)."},{"num":15465,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ عُرِضَ عَلَيْهِ رَيْحَانٌ فَلَا يَرُدُّهُ؛ فَإِنَّهُ خَفِيفُ الْمَحْمِلِ، طَيِّبُ الرِّيحِ."],"takhrij":"صحيح: رواه مسلم في الألفاظ من الأدب (2253) من طريق أبي عبدالرحمن المقرئ، عن سعيد بن أبي أيوب، حدثني عبيدالله بن أبي جعفر، عن عبدالرحمن الأعرج، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب كراهية رد الطيب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2253).","chapter_en":"Dislike of Refusing Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever is offered a fragrant plant or perfume should not refuse it, for it is light to carry and pleasant in fragrance.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2253)."},{"num":15466,"demo":false,"sanad":"","matn":["عن أنس، قَالَ: أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْمٌ يُبَايِعُونَهُ، وَفِيهِمْ رَجُلٌ فِي يَدِهِ أَثَرُ خَلُوقٍ، فَلَمْ يَزَلْ يُبَايِعُهُمْ، وَيُؤَخِّرُهُ، ثُمَّ قَالَ: إِنَّ طِيبَ الرِّجَالِ مَا ظَهَرَ رِيحُهُ وَخَفِيَ لَوْنُهُ، وَطِيبَ النِّسَاءِ مَا ظَهَرَ لَوْنُهُ وَخَفِيَ رِيحُهُ."],"takhrij":"حسن: رواه البزار –كشف الأستار (2989)، والبيهقي في الشعب (7424) كلاهما من حديث سعيد بن سليمان الواسطي، حدثنا إسماعيل بن زكريا، عن عاصم، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب الفصل بين طيب الرجال وطيب النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār as cited in Kashf al-Astār (2989), and al-Bayhaqī in Shuʿab al-Īmān (7424).","chapter_en":"Distinguishing between Men’s Perfume and Women’s Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":14,"content":{"translation":{"en":["Anas narrated: A group came to the Prophet ﷺ to pledge allegiance to him. Among them was a man who had traces of khalūq on his hand. The Prophet ﷺ continued accepting the pledges of the others while delaying this man. Then he said: “Men’s perfume is that whose fragrance is apparent while its color is hidden, and women’s perfume is that whose color is apparent while its fragrance is hidden.”"]},"buhuth":{"en":["A report with the same meaning is narrated from Abū Hurayrah: the Messenger of Allah ﷺ said, “Men’s perfume is that whose fragrance is apparent and color hidden, while women’s perfume is that whose color is apparent and fragrance hidden.” It was narrated by al-Tirmidhī (2787), Abū Dāwūd (2174) within a longer hadith, and al-Nasā’ī (5118). Its chain contains al-Ṭafāwī, who is unknown, as al-Tirmidhī stated.","A similar report is narrated from ʿImrān ibn Ḥuṣayn: the Prophet ﷺ said, “The best perfume for a man is that whose fragrance is apparent and color hidden, and the best perfume for women is that whose color is apparent and fragrance hidden.” It was narrated by al-Tirmidhī (2788), Abū Dāwūd (4048), Aḥmad (19975), and al-Ḥākim (4/191). Its chain contains al-Ḥasan al-Baṣrī, a mudallis who did not hear from ʿImrān ibn Ḥuṣayn according to the stronger view.","Abū Dāwūd related from Saʿīd ibn Abī ʿArūbah that the restriction concerning women’s perfume was understood to apply when a woman goes out; when she is with her husband, she may use whatever perfume she wishes."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (2989)، والبيهقي في الشعب (7424)."},{"num":15467,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: نَهَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَتَزَعْفَرَ الرَّجُلُ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5846)، ومسلم في اللباس (2101) كلاهما من حديث عبد العزيز بن صهيب، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الخلوق للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5846) and Muslim (2101).","chapter_en":"Prohibition of Khalūq for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Anas ibn Mālik narrated: “The Messenger of Allah ﷺ prohibited a man from applying saffron to himself.”"]},"buhuth":{"en":["Khalūq is a perfume compounded from saffron and other substances, generally producing a reddish-yellow color.","It was regarded as a perfume used by women rather than men. Women would apply it as a dye to their hands and feet.","According to the author, it was prohibited for men because doing so involves imitation of women."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5846)، ومسلم (2101)."},{"num":15468,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَبِيبَةَ، عَنْ ذَلِكَ الرَّجُلِ، قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِي حَاجَةٌ، فَرَأَى عَلَيَّ خَلُوقًا، فَقَالَ: اذْهَبْ، فَاغْسِلْهُ، فَغَسَلْتُهُ، ثُمَّ عُدْتُ إِلَيْهِ، فَقَالَ: اذْهَبْ، فَاغْسِلْهُ، فَذَهَبْتُ، فَوَقَعْتُ فِي بِئْرٍ، فَأَخَذْتُ مُسْتَقَةً، فَجَعَلْتُ أَتَتَبَّعُهُ، ثُمَّ عُدْتُ إِلَيْهِ، فَقَالَ: حَاجَتُكَ."],"takhrij":"حسن: رواه أحمد (17013) عن محمد هو ابن جعفر، حدثنا شعبة، عن إسحاق هو ابن سويد، عن أبي حبيبة فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الخلوق للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17013).","chapter_en":"Prohibition of Khalūq for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Abū Ḥabībah narrated from that man: I came to the Prophet ﷺ because I had a need. He saw khalūq on me and said: “Go and wash it off.” So I washed it off and returned to him. He said again: “Go and wash it off.” I went away and fell into a well, took a fur garment, and kept rubbing away its traces. Then I returned to him, and he said: “Now tell me your need.”"]},"buhuth":{"en":["The chain of Abū Ḥabībah’s report is good because Abū Ḥabībah, the freedman of al-Zubayr ibn al-ʿAwwām, was declared trustworthy by Ibn Ḥibbān and al-ʿIjlī. Isḥāq ibn Suwayd, Mūsā ibn ʿUqbah, and Abū al-Aswad Muḥammad ibn ʿAbd al-Raḥmān narrated from him. Abū Aḥmad al-Ḥākim said in al-Kunā that his hadith belongs to the people of Madinah and that no personal name is recorded for him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17013)."},{"num":15469,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: ثَلَاثَةٌ لَا تَقْرَبُهُمُ الْمَلَائِكَةُ: الْجُنُبُ، وَالسَّكْرَانُ، وَالْمُتَضَمِّخُ بِالْخَلُوقِ."],"takhrij":"حسن: رواه البزار – كشف الأستار (2930) عن العباس بن أبي طالب، ثنا أبو سلمة، ثنا أبان –يعني ابن يزيد-، عن قتادة، عن ابن بريدة، عن يحيى بن يعمر، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الخلوق للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār as cited in Kashf al-Astār (2930).","chapter_en":"Prohibition of Khalūq for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في تزيين الشعر، واتخاذ الطيب","group_en":"Collection of What Has Been Narrated Concerning Grooming the Hair and Using Perfume","part_no":63,"group_no":2,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “There are three whom the angels do not approach: a person in a state of major ritual impurity, an intoxicated person, and a man heavily smeared with khalūq.”"]},"buhuth":{"en":["Al-Bazzār said concerning the report of Ibn ʿAbbās that others narrated it in mursal form, that he knew it from Ibn ʿAbbās only through this route, and that a similar report was narrated from ʿAmmār.","The author judges its chain good because al-ʿAbbās ibn Abī Ṭālib—al-ʿAbbās ibn Jaʿfar ibn ʿAbdullāh ibn al-Zabraqān al-Baghdādī—was a good hadith narrator; Abū Ḥātim called him truthful and Ibn Ḥibbān included him among the trustworthy. Al-Bukhārī also mentioned another route with similar wording from Ibn ʿAbbās.","The report from Buraydah with the wording “Three are not approached by the angels: an intoxicated person, one using khalūq, and one in major ritual impurity—or a menstruating woman” is not authentic. It was narrated by al-Bazzār in Kashf al-Astār (2929), al-ʿUqaylī in al-Ḍuʿafāʾ, and Ibn ʿAdī in al-Kāmil through Abū Bakr al-Dāhirī. Al-Bukhārī said, “It is not authentic”; al-ʿUqaylī said he narrated reports with no basis, and Ibn ʿAdī called him munkar al-ḥadīth.","Likewise, the report from ʿAmmār about saffron—where the Prophet ﷺ did not return his greeting until he washed it off, and which states that the angels do not attend the funeral of a disbeliever, a person smeared with saffron, or one in major ritual impurity—is not authentic. Aḥmad (18886), Abū Dāwūd (4176), and al-Tirmidhī (613) narrated it through ʿAṭāʾ al-Khurāsānī from Yaḥyā ibn Yaʿmar from ʿAmmār, but the chain is disconnected because Yaḥyā ibn Yaʿmar did not meet ʿAmmār ibn Yāsir. Other routes contain an unnamed narrator or another disconnection and are likewise unsound.","Nor is the report attributed to Abū Mūsā authentic: “Allah, the Exalted, does not accept the prayer of a man who has any khalūq on his body.” It was narrated by Abū Dāwūd (4178) and Aḥmad (19613); its chain contains the two grandfathers of al-Rabīʿ ibn Anas, both of whom are unknown."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في كشف الأستار (2930)."},{"num":15470,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ: أُهْدِيَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرُّوجُ حَرِيرٍ، فَلَبِسَهُ، ثُمَّ صَلَّى فِيهِ، ثُمَّ انْصَرَفَ، فَنَزَعَهُ نَزْعًا شَدِيدًا، كَالْكَارِهِ لَهُ، ثُمَّ قَالَ: لاَ يَنْبَغِي هَذَا لِلْمُتَّقِينَ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5801)، ومسلم في اللباس (2075) كلاهما عن قتيبة بن سعيد، حدثنا الليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عقبة بن عامر فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5801) and Muslim (2075).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: A silk furūj garment was gifted to the Messenger of Allah ﷺ. He wore it and prayed in it. Then, after finishing the prayer, he removed it forcefully, as though disliking it, and said: “This is not appropriate for the people of taqwā.”"]},"buhuth":{"en":["The hadith indicates that wearing silk for men had initially been permitted, which is why the Prophet ﷺ wore it and prayed in it, and that its prohibition came afterward. This is what the hadiths of this chapter indicate."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5801)، ومسلم (2075)."},{"num":15471,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ وَأَنَا أَسْمَعُ، فَقَالَ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ كَذِبَ عَلَيَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ، وَأَشْهَدُ أَنِّي سَمِعْتُهُ يَقُولُ: مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا، حُرِمَهُ أَنْ يَلْبَسَهُ فِي الْآخِرَةِ."],"takhrij":"حسن: رواه أحمد (17431)، وأبو يعلى (1751)، والطبراني في الكبير (17/ح 904) وصحّحه ابن حبان (5436) كلهم من طرق عن ابن وهب قال: أخبرني عمرو بن الحارث، أن هشام بن أبي رقية حدثه قال: سمعت مسلمة بن مخلد -وهو قاعد على المنبر يخطب الناس- وهو يقول: يا أيها الناس، أما لكم في العصب والكتان ما يكفيكم عن الحرير، وهذا رجل فيكم يخبركم عن رسول الله صلى الله عليه وسلم، قم يا عقبة، فقام عقبة بن عامر وأنا أسمع فقال: فذكر الحديث.وإسناده حسن من أجل هشام بن أبي رقية وهو من رجال \"التعجيل\" روى عنه جمع، وذكره ابن حبان في الثقات (5436)، وقال العجلي: \"مصري تابعي ثقة\". قوله: حرمه أن يلبسه في الآخرة كناية عن عدم دخول الجنة، وقد قال الله تعالى في أهل الجنة وَلِبَاسُهُمْ فِيهَا حَرِيرٌ (الحج: ٢٣).هكذا فسر بعض أهل السلف.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17431), Abū Yaʿlā (1751), and al-Ṭabarānī in al-Muʿjam al-Kabīr (17/327), and authenticated by Ibn Ḥibbān (5436).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: I heard the Messenger of Allah ﷺ say: “Whoever deliberately lies about me, let him take his seat in the Fire.” And I testify that I heard him say: “Whoever wears silk in this world will be forbidden from wearing it in the Hereafter.”"]},"buhuth":{"ar":["قوله: حرم أن يلبسه في الآخرة كناية عن عدم دخول الجنة، وقد قال اللّٰه تعالى في أهل الجنة: ﴿وَلِبَاسُهُمْ فِيهَا حَرِيرٌ﴾ [الحج: ٢٣]. هكذا فسر بعض أهل السلف."],"en":["The statement:","“He will be forbidden from wearing it in the Hereafter”","was interpreted by some of the early scholars as an indirect reference to not entering Paradise, because Allah says regarding the people of Paradise:","“And their clothing therein will be silk.”","[Sūrat al-Ḥajj 22:23]"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه أحمد (17431)، وأبو يعلى (1751)، والطبراني في الكبير (17/ح 904)، وصححه ابن حبان (5436)."},{"num":15472,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْحَرِيرُ وَالذَّهَبُ حَرَامٌ عَلَى ذُكُورِ أُمَّتِي، حَلَّ لإِنَاثِهِمْ."],"takhrij":"حسن: رواه الطحاوي في شرح المشكل (416) عن إبراهيم بن أبي داود، وفهد، قالا: حدثنا سعيد بن أبي مريم، أخبرنا يحيى بن أيوب، حدثني الحسن بن ثوبان، وعمرو بن الحارث، عن هشام بن أبي رقية اللخمي، قال: سمعت مسلمة بن مخلد يقول لعقبة بن عامر: قم فحدث الناس بما سمعت من رسول الله صلى الله عليه وسلم فقام عقبة فذكر هذا الحديث، وحديثا آخر وهو: من كذب علي فليتبوأ بيته من جهنم.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭaḥāwī in Sharḥ Mushkil al-Āthār (416).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: I heard the Messenger of Allah ﷺ say: “Silk and gold are forbidden for the males of my Ummah and lawful for its females.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطحاوي في شرح المشكل (416)."},{"num":15473,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أَبِي لَيْلَى قَالَ: كَانَ حُذَيْفَةُ بِالْمَدَائِنِ، فَاسْتَسْقَى، فَأَتَاهُ دِهْقَانٌ بِمَاءٍ فِي إِنَاءٍ مِنْ فِضَّةٍ، فَرَمَاهُ بِهِ، وَقَالَ: إِنِّي لَمْ أَرْمِهِ إِلاَّ أَنِّي نَهَيْتُهُ فَلَمْ يَنْتَهِ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : الذَّهَبُ وَالْفِضَّةُ، وَالْحَرِيرُ، وَالدِّيبَاجُ، هِيَ لَهُمْ فِي الدُّنْيَا، وَلَكُمْ فِي الآخِرَةِ وَزَادَ فِي رِوَايَةِ: وأن نجلس عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5831)، ومسلم في اللباس (2067) كلاهما من طريق شعبة، عن الحكم أنه سمع عبد الرحمن بن أبي ليلى فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5831) and Muslim (2067).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ibn Abī Laylā narrated: Ḥudhayfah was in al-Madāʾin and asked for water. A local landowner brought him water in a silver vessel, so Ḥudhayfah threw it at him and said: “I only threw it because I had already prohibited him from doing this, but he did not stop.” The Messenger of Allah ﷺ said: “Gold, silver, silk, and brocade are for them in this world and for you in the Hereafter.” Another narration adds: “And he prohibited us from sitting upon it.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5831)، ومسلم (2067)."},{"num":15474,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2074) عن إبراهيم بن موسى الرازي، أخبرنا شعيب بن إسحاق الدمشقي، عن الأوزاعي، حدثني شداد أبو عمار، حدثني أبو أمامة فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2074).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abū Umāmah narrated that the Messenger of Allah ﷺ said: “Whoever wears silk in this world will not wear it in the Hereafter.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2074)."},{"num":15475,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ كَانَ يُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ فَلَا يَلْبَسْ حَرِيرًا وَلَا ذَهَبًا."],"takhrij":"حسن: رواه أحمد (22248، 22249) من وجهين عن سليمان بن عبدالرحمن، عن القاسم مولى عبد الرحمن، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (22248, 22249).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abū Umāmah narrated that he heard the Messenger of Allah ﷺ say: “Whoever believes in Allah and the Last Day should not wear silk or gold.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (22248، 22249)."},{"num":15476,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ لَبِسَ الذَّهَبَ مِنْ أُمَّتِي فَمَاتَ وَهُوَ يَلْبَسُهُ لَمْ يَلْبَسْ مِنْ ذَهَبِ الْجَنَّةِ وَقَالَ هَوْذَةُ: حَرَّمَ اللَّهُ عَلَيْهِ ذَهَبَ الْجَنَّةِ، وَمَنْ لَبِسَ الْحَرِيرَ مِنْ أُمَّتِي فَمَاتَ وَهُوَ يَلْبَسُهُ حَرَّمَ اللَّهُ عَلَيْهِ حَرِيرَ الْجَنَّةِ."],"takhrij":"حسن: رواه أحمد (6947) عن إسحاق بن يوسف الأزرق وهوذة بن خليفة قالا: حدثنا عوف، عن ميمون بن أستاذ قال: قال عبد الله بن عمرو فذكره.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6947).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Messenger of Allah ﷺ said: “Whoever among my Ummah wears gold and dies while wearing it will not wear the gold of Paradise.” Hawdhah narrated the wording: “Allah will forbid him the gold of Paradise. And whoever among my Ummah wears silk and dies while wearing it, Allah will forbid him the silk of Paradise.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6947)."},{"num":15477,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حِطَّانَ، قَالَ: سَأَلْتُ عَائِشَةَ عَنِ الْحَرِيرِ، فَقَالَتِ: ائْتِ ابْنَ عَبَّاسٍ فَسَلْهُ. قَالَ: فَسَأَلْتُهُ فَقَالَ: سَلِ ابْنَ عُمَرَ. قَالَ: فَسَأَلْتُ ابْنَ عُمَرَ، فَقَالَ: أَخْبَرَنِي أَبُو حَفْصٍ ـ يَعْنِي عُمَرَ بْنَ الْخَطَّابِ ـ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّمَا يَلْبَسُ الْحَرِيرَ فِي الدُّنْيَا مَنْ لاَ خَلاَقَ لَهُ فِي الآخِرَةِ. فَقُلْتُ: صَدَقَ، وَمَا كَذَبَ أَبُو حَفْصٍ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في اللباس (5835) عن محمد بن بشار، حدثنا عثمان بن عمر، حدثنا علي بن المبارك، عن يحيى بن أبي كثير، عن عمران بن حطان فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5835).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿImrān ibn Ḥiṭṭān narrated: I asked ʿĀ’ishah about silk. She said: “Go to Ibn ʿAbbās and ask him.” So I asked him, and he said: “Ask Ibn ʿUmar.” I asked Ibn ʿUmar, and he said: Abū Ḥafṣ—meaning ʿUmar ibn al-Khaṭṭāb—informed me that the Messenger of Allah ﷺ said: “Silk in this world is worn only by one who has no share in the Hereafter.” I said: “He spoke the truth. Abū Ḥafṣ did not lie about the Messenger of Allah ﷺ.”"]},"buhuth":{"en":["The word “khalāq” means a share or portion."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5835)."},{"num":15478,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بن الْخَطَّابِ أن النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5834)، ومسلم في اللباس (2069: 11) كلاهما من حديث شعبة، عن أبي ذبيان خليفة بن كعب قال: سمعت ابن الزبير يقول: سمعت عمر يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5834) and Muslim (2069:11).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb narrated that the Prophet ﷺ said: “Whoever wears silk in this world will not wear it in the Hereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5834)، ومسلم (2069: 11)."},{"num":15479,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن الزُّبَيْرِ قَالَ: قَالَ مُحَمَّدٌ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الآخِرَةِ."],"takhrij":"صحيح: رواه البخاري (5833) عن سليمان بن حرب، جدثنا حماد بن زيد، عن ثابت قال: سمعت ابن الزبير يخطب يقول: فذكره. والظاهر أنه سمعه من عمر بن الخطاب.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5833).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn al-Zubayr narrated that Muḥammad ﷺ said: “Whoever wears silk in this world will not wear it in the Hereafter.”"]},"buhuth":{"en":["The statement:","“He will not wear it in the Hereafter”","is understood here as an indirect reference to not entering Paradise initially, because Allah says:","“And their clothing therein will be silk.”","[Sūrat al-Ḥajj 22:23]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5833)."},{"num":15480,"demo":false,"sanad":"","matn":["أَنَّ أَبَا هُرَيْرَةَ، حَدَّثَ، أَنَّ عُمَرَ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ عُطَارِدًا التَّمِيمِيَّ كَانَ يُقِيمُ حُلَّةَ حَرِيرٍ، فَلَوِ اشْتَرَيْتَهَا فَلَبِسْتَهَا، إِذَا جَاءَكَ وُفُودُ النَّاسِ، فَقَالَ: إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا خَلَاقَ لَهُ."],"takhrij":"حسن: رواه أحمد (8444)، والبزار –كشف الأستار (2997) كلاهما من حديث سالم بن دينار أبي جميع، حدثنا محمد بن سيرين، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8444) and al-Bazzār as cited in Kashf al-Astār (2997).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated that ʿUmar said: “O Messenger of Allah, ʿUṭārid al-Tamīmī has a silk suit for sale. Why not buy it and wear it when delegations come to you?” The Prophet ﷺ replied: “Silk is worn only by one who has no share in the Hereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8444)، والبزار في كشف الأستار (2997)."},{"num":15481,"demo":false,"sanad":"","matn":["عَنْ حَفْصَةَ، أَنَّ عُطَارِدَ بْنَ حَاجِبٍ، قَدِمَ مَعَهُ بِثَوْبِ دِيبَاجٍ كَسَاهُ إِيَّاهُ كِسْرَى فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ لَوْ اشْتَرَيْتَهُ؟ فَقَالَ: إِنَّمَا يَلْبَسُهُ مَنْ لَا خَلَاقَ لَهُ."],"takhrij":"صحيح: رواه أحمد (26469)، والطبراني في الكبير (23/ح 395) كلاهما من حديث حماد بن سلمة، عن أنس بن سيرين، عن أبي مجلز –وهو لا حق بن حميد-، عن حفصة فذكرته. وإسناده صحيح. قوله: لا خلاق له أي لا حظ له في الآخرة.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (26469) and al-Ṭabarānī in al-Muʿjam al-Kabīr (23/206).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ḥafṣah narrated: ʿUṭārid ibn Ḥājib arrived with a brocade garment that Kisrā had given him. ʿUmar said: “O Messenger of Allah, why not buy it?” He replied: “It is worn only by one who has no share in the Hereafter.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (26469)، والطبراني في الكبير (23/206)."},{"num":15482,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  لَبِسَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا قَبَاءً مِنْ دِيبَاجٍ أُهْدِيَ لَهُ، ثُمَّ أَوْشَكَ أَنْ نَزَعَهُ، فَأَرْسَلَ بِهِ إِلَى عُمَرَ بْنِ الْخَطَّابِ، فَقِيلَ لَهُ: قَدْ أَوْشَكَ مَا نَزَعْتَهُ يَا رَسُولَ اللَّهِ. فَقَالَ: نَهَانِي عَنْهُ جِبْرِيلُ. فَجَاءَهُ عُمَرُ يَبْكِي، فَقَالَ: يَا رَسُولَ اللَّهِ، كَرِهْتَ أَمْرًا، وَأَعْطَيْتَنِيهِ، فَمَا لِي؟ قَالَ: إِنِّي لَمْ أُعْطِكَهُ لِتَلْبَسَهُ، إِنَّمَا أَعْطَيْتُكَهُ تَبِيعُهُ. فَبَاعَهُ بِأَلْفَيْ دِرْهَمٍ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2070) من طريق روح بن عبادة، ثنا ابن جريج، أخبرني أبو الزبير أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2070).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: One day the Prophet ﷺ wore a brocade cloak that had been gifted to him. Soon afterward he removed it and sent it to ʿUmar ibn al-Khaṭṭāb. Someone said: “You removed it very quickly, O Messenger of Allah.” He replied: “Jibrīl prohibited me from wearing it.” ʿUmar then came to him crying and said: “O Messenger of Allah, you disliked something, yet you gave it to me. What am I to do with it?” He replied: “I did not give it to you so that you would wear it. I only gave it to you so that you could sell it.” So ʿUmar sold it for two thousand dirhams."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2070)."},{"num":15483,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، أَنَّ عُمَرَ بْنَ الْخَطَّابِ، رَأَى حُلَّةَ سِيَرَاءَ عِنْدَ بَابِ الْمَسْجِدِ، فَقَالَ: يَا رَسُولَ اللَّهِ، لَوِ اشْتَرَيْتَ هَذِهِ فَلَبِسْتَهَا يَوْمَ الْجُمُعَةِ، وَلِلْوَفْدِ إِذَا قَدِمُوا عَلَيْكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّمَا يَلْبَسُ هَذِهِ مَنْ لاَ خَلاَقَ لَهُ فِي الآخِرَةِ. ثُمَّ جَاءَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْهَا حُلَلٌ، فَأَعْطَى عُمَرَ بْنَ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ مِنْهَا حُلَّةً، فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ، كَسَوْتَنِيهَا وَقَدْ قُلْتَ فِي حُلَّةِ عُطَارِدٍ مَا قُلْتَ؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي لَمْ أَكْسُكَهَا لِتَلْبَسَهَا. فَكَسَاهَا عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ أَخًا لَهُ بِمَكَّةَ. مُشْرِكًا."],"takhrij":"متفق عليه: رواه مالك في اللباس (18) عن نافع، عن عبد الله بن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in The Book of Clothing (18), al-Bukhārī (886), and Muslim (2068).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated: ʿUmar ibn al-Khaṭṭāb saw a siyarāʾ suit being sold at the door of the mosque. He said: “O Messenger of Allah, why not buy this suit and wear it on Friday and when delegations arrive?” The Messenger of Allah ﷺ replied: “This is worn only by one who has no share in the Hereafter.” Later, the Messenger of Allah ﷺ received some similar suits and gave one of them to ʿUmar. ʿUmar said: “O Messenger of Allah, you have clothed me in this after saying what you said regarding ʿUṭārid’s suit?” The Messenger of Allah ﷺ replied: “I did not give it to you so that you would wear it.” So ʿUmar gave it to a polytheist brother of his in Makkah."]},"buhuth":{"en":["Al-Bukhārī (5841) also narrated through another route:","“The Prophet ﷺ later sent ʿUmar a silk siyarāʾ suit.”","The word “siyarāʾ”, with kasrah on the sīn and fatḥah on the yāʾ followed by a long vowel, refers to a type of striped cloak mixed with silk, resembling strips or bands.","The phrase ḥullat siyarāʾ is transmitted as an adjective construction, while some considered it an iḍāfah construction.","They cited Sībawayh’s statement that the pattern fiʿlāʾ does not occur as an adjective but as a noun.","Siyarāʾ has also been explained as pure silk, in which case the meaning is simply “a silk suit.”","See al-Nihāyah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (18)، والبخاري (886)، ومسلم (2068)."},{"num":15484,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ:  بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عُمَرَ بِجُبَّةِ سُنْدُسٍ، فَقَالَ عُمَرُ: بَعَثْتَ بِهَا إِلَيَّ وَقَدْ قُلْتَ فِيهَا مَا قُلْتَ؟ قَالَ: إِنِّي لَمْ أَبْعَثْ بِهَا إِلَيْكَ لِتَلْبَسَهَا، وَإِنَّمَا بَعَثْتُ بِهَا إِلَيْكَ لِتَنْتَفِعَ بِثَمَنِهَا."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2072) من طريق أبي عوانة، عن عبدالرحمن بن الأصم، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2072).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Messenger of Allah ﷺ sent ʿUmar a cloak made of sundus silk. ʿUmar said: “You sent this to me even though you said what you said concerning it?” He replied: “I did not send it to you so that you would wear it. I only sent it to you so that you could benefit from its price.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2072)."},{"num":15485,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا لَمْ يَلْبَسْهُ فِي الْآخِرَةِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5832)، ومسلم في اللباس والزينة (2073) كلاهما من طريق عبد العزيز بن صهيب قال: سمعت أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5832) and Muslim (2073).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Whoever wears silk in this world will not wear it in the Hereafter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5832)، ومسلم (2073)."},{"num":15486,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ قَالَ:  نَهَانِي، يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنْ أَجْعَلَ خَاتَمِي فِي هَذِهِ، أَوِ الَّتِي تَلِيهَا لَمْ يَدْرِ عَاصِمٌ فِي أَيِّ الثِّنْتَيْنِ وَنَهَانِي عَنْ لُبْسِ الْقَسِّيِّ، وَعَنْ جُلُوسٍ عَلَى الْمَيَاثِرِ.","قَالَ: فَأَمَّا الْقَسِّيُّ: فَثِيَابٌ مُضَلَّعَةٌ يُؤْتَى بِهَا مِنْ مِصْرَ وَالشَّامِ فِيهَا شِبْهُ كَذَا، وَأَمَّا الْمَيَاثِرُ: فَشَيْءٌ كَانَتْ تَجْعَلُهُ النِّسَاءُ لِبُعُولَتِهِنَّ عَلَى الرَّحْلِ كَالْقَطَائِفِ الْأُرْجُوَانِ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2078: 64) من طريق ابن إدريس، قال: سمعت عاصم بن كليب، عن أبي بردة، عن علي فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2078:64).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: The Prophet ﷺ prohibited me from wearing my ring on this finger or the one next to it—ʿĀṣim could not remember which of the two—and he prohibited me from wearing qassī garments and from sitting upon mītharah coverings. He explained: “As for qassī, they are striped garments brought from Egypt and al-Shām containing patterns of this sort. As for mītharah, it is something women used to make for their husbands and place upon their saddles, resembling purple-red rugs.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2078: 64)."},{"num":15487,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ قَالَ: نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ خَاتَمِ الذَّهَبِ، وَعَنْ لُبْسِ الْقَسِّيِّ، وَالْمِيثَرَةِ الْحَمْرَاءِ."],"takhrij":"حسن: رواه أبو داود (4051)، والترمذي (2808)، وابن ماجه (3654)، وأحمد (722)، وصحّحه ابن حبان (5438) كلهم من طريق أبي إسحاق، عن هبيرة، عن علي فذكره.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4051), al-Tirmidhī (2808), Ibn Mājah (3654), and Aḥmad (722).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: “The Messenger of Allah ﷺ prohibited me from wearing a gold ring, from wearing qassī garments, and from using red mītharah coverings.”"]},"buhuth":{"en":["The statement:","“The Messenger of Allah ﷺ prohibited me”","does not mean that the prohibition applied only to ʿAlī, as some jurists held. Rather, according to the author, it is general for all legally accountable people, because an address directed to one person applies generally unless there is evidence restricting it to that individual.","Mītharah were furnishings used by non-Arabs, made from silk or brocade.","Urjuwān is a red dye. Such coverings were made like small cushions, stuffed with cotton or wool, and placed beneath a rider on camel saddles."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4051)، والترمذي (2808)، وابن ماجه (3654)، وأحمد (722)."},{"num":15488,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ قَالَ:  كَسَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حُلَّةَ سِيَرَاءَ، فَخَرَجْتُ فِيهَا، فَرَأَيْتُ الْغَضَبَ فِي وَجْهِهِ، قَالَ: فَشَقَقْتُهَا بَيْنَ نِسَائِي.","وفي لفظ: إني لم أبعث بها إليك لتلبسها، إنما بعثت بها إليك لتشققها خمرا بين النساء.","وفي رواية عند البخاري (2614) أهدى إليَّ النَّبيُّ صلى الله عليه وسلم حلة سيراء."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5840)، ومسلم في اللباس (2071: 19) من طريق غندر، ثنا شعبة، عن عبد الملك بن ميسرة، عن زيد بن وهب، عن علي فذكره.","grade":"متفق عليه","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5840) and Muslim (2071:19).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: The Prophet ﷺ gave me a siyarāʾ suit. I went out wearing it and saw anger on his face, so I tore it up and distributed it among my womenfolk. In another wording, the Prophet ﷺ said: “I did not send it to you so that you would wear it. I only sent it to you so that you could tear it into head coverings for the women.”","In another narration recorded by al-Bukhārī (2614): “The Prophet ﷺ gifted me a siyarāʾ suit.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5840)، ومسلم (2071: 19)."},{"num":15489,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ:  أَنَّ أُكَيْدِرَ دُومَةَ أَهْدَى إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَوْبَ حَرِيرٍ، فَأَعْطَاهُ عَلِيًّا فَقَالَ: شَقِّقْهُ خُمُرًا بَيْنَ الْفَوَاطِمِ.","وفي رواية بين النساء."],"takhrij":"صحيح: رواه مسلم في اللباس (18:2071) من طرق عن وكيع ، عن مسعر، عن أبي عون الثقفي، عن أبي صالح الحنفي، عن علي فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2071:18).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAlī narrated: Ukaydir of Dūmah gifted the Prophet ﷺ a silk garment. The Prophet ﷺ gave it to ʿAlī and said: “Cut it into head coverings and distribute them among the Fāṭimahs.” In another wording: “Among the women.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (18:2071)."},{"num":15490,"demo":false,"sanad":"","matn":["عن علي بن أَبِي طالبرَضِيَ اللَّهُ عَنْهُ يَقُولُ: إِنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ حَرِيرًا فَجَعَلَهُ فِي يَمِينِهِ، وَأَخَذَ ذَهَبًا فَجَعَلَهُ فِي شِمَالِهِ، ثُمَّ قَالَ: إِنَّ هَذَيْنِ حَرَامٌ عَلَى ذُكُورِ أُمَّتِي."],"takhrij":"حسن: رواه أبو داود في سننه (4057)، والنسائي في المجتبى (5144)، وفي السنن الكبرى (9382) كلاهما عن قتيبة بن سعيد، حدثنا الليث بن سعد، عن يزيد بن أبي حبيب، عن أبي أفلح الهمداني، عن عبد الله بن زُرير أنه سمع علي بن أبي طالب يقول: فذكره.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd in his Sunan (4057), al-Nasā’ī in al-Mujtabā (5144), and in al-Sunan al-Kubrā (9382).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: The Prophet of Allah ﷺ took silk and placed it in his right hand, and took gold and placed it in his left hand. Then he said: “These two are forbidden for the males of my Ummah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود في سننه (4057)، والنسائي في المجتبى (5144)، وفي السنن الكبرى (9382)."},{"num":15491,"demo":false,"sanad":"","matn":["عن أَبِي عَامِرٍ – أَوْ أَبِي مَالِكٍ- أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لَيَكُونَنَّ مِنْ أُمَّتِي أَقْوَامٌ يَسْتَحِلُّونَ الْحِرَ وَالْحَرِيرَ وَالْخَمْرَ وَالْمَعَازِفَ، وَلَيَنْزِلَنَّ أَقْوَامٌ إِلَى جَنْبِ عَلَمٍ يَرُوحُ عَلَيْهِمْ بِسَارِحَةٍ لَهُمْ، يَأْتِيهِمْ ـ يَعْنِي الْفَقِيرَ ـ لِحَاجَةٍ فَيَقُولُوا: ارْجِعْ إِلَيْنَا غَدًا. فَيُبَيِّتُهُمُ اللَّهُ، وَيَضَعُ الْعَلَمَ، وَيَمْسَخُ آخَرِينَ قِرَدَةً وَخَنَازِيرَ إِلَى يَوْمِ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5590) قال: وقال هشام بن عمار، حدثنا صدقة بن خالد، حدثنا عبد الرحمن بن يزيد بن جابر، حدثنا عطية بن قيس الكلابي، حدثنا عبد الرحمن بن غنم الأشعري قال: حدثني أبو عامر-أو أبو مالك- الأشعري -والله ما كذبني- سمع النبي صلى الله عليه وسلم يقول: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5590).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abū ʿĀmir—or Abū Mālik—narrated that he heard the Prophet ﷺ say: “There will certainly be people from my Ummah who will regard illicit sexual relations, silk, wine, and musical instruments as lawful. Some people will settle beside a mountain, and their livestock will be brought back to them in the evening. A poor person will come to them for some need, and they will say, ‘Come back to us tomorrow.’ Then Allah will destroy them during the night, bring the mountain down upon them, and transform others into apes and pigs until the Day of Resurrection.”"]},"buhuth":{"en":["The word “al-ḥirr”, with the letter ḥāʾ, refers to the private part and thus to illicit sexual relations.","Scholars differed concerning this word and whether the narration should read al-ḥirr or al-khazz.","Ibn al-Athīr said in al-Nihāyah:","“In the various routes of this hadith, the wording is: ‘They will regard khazz as lawful,’ with khāʾ and zāy, and it is a known type of silk garment.”","The author adds that this is also how it appears in Sunan Abī Dāwūd (4039) and elsewhere, and that it is a type of silk.","The term khazz may also refer to material made from the fur of male rabbits, and this type of khazz is not included in the threat or punishment."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7465,15918],"tks":"صحيح: رواه البخاري (5590)."},{"num":15492,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتْبَعُ الْحَرِيرَ مِنَ الثِّيَابِ فَيَنْزِعُهُ."],"takhrij":"حسن: رواه أحمد (8261) عن أبي عبد الرحمن (المقرئ)، حدثنا حيوة، أخبرني أبو هانئ، أن أبا سعيد الغفاري أخبره أنه سمع أبا هريرة يقول: فذكره.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8261).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated: “The Messenger of Allah ﷺ would seek out silk portions in garments and remove them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8261)."},{"num":15493,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّمَا يَلْبَسُ الْحَرِيرَ فِي الدُّنْيَا مَنْ لَا يَرْجُو أَنْ يَلْبَسَهُ فِي الْآخِرَةِ، إِنَّمَا يَلْبَسُ الْحَرِيرَ مَنْ لَا خَلَاقَ لَهُ."],"takhrij":"حسن: رواه أحمد (8355) عن أبي النضر، حدثنا المبارك، عن الحسن، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8355).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Prophet ﷺ say: “Silk in this world is worn only by one who does not hope to wear it in the Hereafter. Silk is worn only by one who has no share.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8355)."},{"num":15494,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: إِنَّمَا نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الثَّوْبِ الْمُصْمَتِ حَرِيرًا."],"takhrij":"صحيح: رواه أحمد (2856)، -ومن طريقه الحاكم (7405)- عن محمد بن بكير، حدثنا ابن جريج، أخبرني عكرمة بن خالد (يعني ابن العاص بن هشام المخزومي)، عن سعيد بن جبير، عن ابن عباس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (2856), and through him by al-Ḥākim (4/192).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbās said: “The Messenger of Allah ﷺ only prohibited a garment made entirely of silk.”"]},"buhuth":{"en":["The word “muṣmat” refers to a garment made entirely of silk, with no cotton, wool, or other material mixed into it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (2856)، ومن طريقه الحاكم (7405)."},{"num":15495,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ أَنَّهُ رَأَى عَلَى أُمِّ كُلْثُومٍ بِنْتِ رَسُولِ لله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بُرْدَ حَرِيرٍ سِيَرَاءَ."],"takhrij":"صحيح: رواه البخاري في اللباس (5842) عن أبي اليمان، أخبرنا شعيب، عن الزهري، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5842).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik narrated: “He saw Umm Kulthūm, the daughter of the Messenger of Allah ﷺ, wearing a siyarāʾ silk cloak.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5842)."},{"num":15496,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أُحِلَّ لُبْسُ الْحَرِيرِ وَالذَّهَبِ لِنِسَاءِ أُمَّتِي، وَحُرِّمَ عَلَى ذُكُورِهَا."],"takhrij":"صحيح: رواه الترمذي (1720)، والنسائي (5265)، وأحمد (19645)، والبيهقي (4/425) كلهم من حديث عبيد الله، أخبرني نافع، عن سعيد بن أبي هند، عن أبي موسى فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (1720), al-Nasā’ī (5265), Aḥmad (19645), and al-Bayhaqī (4/425).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["Abū Mūsā narrated that the Prophet ﷺ said: “Wearing silk and gold has been made lawful for the women of my Ummah and forbidden for its men.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1720)، والنسائي (5265)، وأحمد (19645)، والبيهقي (4/425)."},{"num":15497,"demo":false,"sanad":"","matn":["عن عُقْبَةَ بن عَامِرٍ الْجُهَنِيَّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَمْنَعُ أَهْلَهُ الْحِلْيَةَ وَالْحَرِيرَ، وَيَقُولُ: إِنْ كُنْتُمْ تُحِبُّونَ حِلْيَةَ الْجَنَّةِ وَحَرِيرَهَا فَلَا تَلْبَسُوهَا فِي الدُّنْيَا."],"takhrij":"صحيح: رواه النسائي (5136)، وابن حبان (5486)، والحاكم (7403) كلهم من طريق ابن وهب، أخبرني عمرو بن الحارث أن أبا عُشّانة المعافري حدّثه أنه سمع عقبة بن عامر يخبر قال: فذكره.","grade":"صحيح","chapter_ar":"باب تحريم الحرير على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (5136), Ibn Ḥibbān (5486), and al-Ḥākim (7403).","chapter_en":"Silk Is Forbidden for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":1,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: The Messenger of Allah ﷺ used to discourage his family from jewelry and silk, saying: “If you love the jewelry and silk of Paradise, then do not wear them in this world.”"]},"buhuth":{"en":["According to the author, this hadith was intended to encourage the family of the Prophet ﷺ to live simply and avoid excessive luxury in clothing. Otherwise, jewelry and silk are lawful for women generally."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (5136)، وابن حبان (5486)، والحاكم (7403)."},{"num":15498,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُثْمَانَ قَالَ:  كَتَبَ إِلَيْنَا عُمَرُ، وَنَحْنُ بِأَذْرَبِيجَانَ: يَا عُتْبَةُ بْنَ فَرْقَدٍ، إِنَّهُ لَيْسَ مِنْ كَدِّكَ، وَلَا مِنْ كَدِّ أَبِيكَ، وَلَا مِنْ كَدِّ أُمِّكَ، فَأَشْبِعِ الْمُسْلِمِينَ فِي رِحَالِهِمْ مِمَّا تَشْبَعُ مِنْهُ فِي رَحْلِكَ، وَإِيَّاكُمْ وَالتَّنَعُّمَ، وَزِيَّ أَهْلِ الشِّرْكِ، وَلَبُوسَ الْحَرِيرِ، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لَبُوسِ الْحَرِيرِ، قَالَ: إِلَّا هَكَذَا، وَرَفَعَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِصْبَعَيْهِ: الْوُسْطَى وَالسَّبَّابَةَ وَضَمَّهُمَا.","قَالَ زُهَيْرٌ: قَالَ عَاصِمٌ: هَذَا فِي الْكِتَابِ، قَالَ: وَرَفَعَ زُهَيْرٌ إِصْبَعَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5829)، ومسلم في اللباس (2069: 12) كلاهما عن أحمد بن عبد الله بن يونس، حدثنا زهير، حدثنا عاصم الأحول، عن أبي عثمان فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب القدر الذي يجوز فيه استعمال الحرير للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5829) and Muslim (2069:12). The wording is Muslim’s.","chapter_en":"The Amount of Silk Permitted for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Abū ʿUthmān narrated: ʿUmar wrote to us while we were in Azerbaijan: “O ʿUtbah ibn Farqad, this wealth is not the result of your own labor, nor the labor of your father or mother. So feed the Muslims in their dwellings from the same food with which you satisfy yourself in your own dwelling. Beware of luxury, the dress of the polytheists, and wearing silk, for the Messenger of Allah ﷺ prohibited wearing silk except this much.” The Messenger of Allah ﷺ raised two fingers for us—the middle finger and the index finger—and held them together. Zuhayr said: ʿĀṣim said: “This was written in the letter.” Zuhayr then raised his two fingers."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5829)، ومسلم (2069: 12)، واللفظ لمسلم."},{"num":15499,"demo":false,"sanad":"","matn":["عَنْ سُوَيْدِ بْنِ غَفَلَةَ:  أَنَّ عُمَرَ بْنَ الْخَطَّابِ خَطَبَ بِالْجَابِيَةِ، فَقَالَ: نَهَى نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ لُبْسِ الْحَرِيرِ، إِلَّا مَوْضِعَ إِصْبَعَيْنِ، أَوْ ثَلَاثٍ، أَوْ أَرْبَعٍ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2069: 15) من طريق معاذ بن هشام، حدثني أبي، عن قتادة، عن عامر الشعبي، عن سويد بن غفلة فذكره.","grade":"صحيح","chapter_ar":"باب القدر الذي يجوز فيه استعمال الحرير للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2069:15).","chapter_en":"The Amount of Silk Permitted for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":2,"content":{"translation":{"en":["Suwayd ibn Ghafalah narrated: ʿUmar ibn al-Khaṭṭāb delivered a sermon at al-Jābiyah and said: “The Prophet of Allah ﷺ prohibited wearing silk except an amount equal to two, three, or four fingers.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2069: 15)."},{"num":15500,"demo":false,"sanad":"","matn":["عن الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثَوْبٍ مِنْ حَرِيرٍ، فَجَعَلُوا يَعْجَبُونَ مِنْ حُسْنِهِ وَلِينِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَمَنَادِيلُ سَعْدِ بْنِ مُعَاذٍ فِي الْجَنَّةِ أَفْضَلُ مِنْ هَذَا."],"takhrij":"متفق عليه: رواه البخاري في مناقب الأنصار (3802)، ومسلم في فضائل الصحابة (2468) كلاهما من حديث محمد بن جعفر غندر، حدثنا شعبة، عن أبي إسحاق قال: سمعت البراء يقول: فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب قبول هدية الحرير دون لبسه بعد التحريم للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3802) and Muslim (2468).","chapter_en":"Accepting a Gift of Silk Without Wearing It After It Became Forbidden for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated: A silk garment was brought to the Messenger of Allah ﷺ. The people began marveling at its beauty and softness. The Messenger of Allah ﷺ said: “The handkerchiefs of Saʿd ibn Muʿādh in Paradise are better than this.”"]},"buhuth":{"en":["Muslim’s wording states:","“A silk suit was gifted to the Messenger of Allah ﷺ, and his Companions began touching it and marveling at its softness.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3802)، ومسلم (2468)."},{"num":15501,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ، حَدَّثَنَا أَنَسٌ رَضِيَ اللَّهُ عَنْهُ قَالَ: أُهْدِيَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جُبَّةُ سُنْدُسٍ، وَكَانَ يَنْهَى عَنِ الْحَرِيرِ، فَعَجِبَ النَّاسُ مِنْهَا، فَقَالَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَمَنَادِيلُ سَعْدِ بْنِ مُعَاذٍ فِي الْجَنَّةِ أَحْسَنُ مِنْ هَذَا."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2615)، ومسلم في الفضائل (2469) كلاهما من حديث يونس بن محمد، حدثنا شيبان، عن قتادة، حدثنا أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب قبول هدية الحرير دون لبسه بعد التحريم للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2615) and Muslim (2469).","chapter_en":"Accepting a Gift of Silk Without Wearing It After It Became Forbidden for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Anas narrated: A cloak of sundus silk was gifted to the Prophet ﷺ, although he prohibited silk. The people marveled at it, so he said: “By the One in whose hand is the soul of Muḥammad, the handkerchiefs of Saʿd ibn Muʿādh in Paradise are more beautiful than this.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10208,16310],"tks":"متفق عليه: رواه البخاري (2615)، ومسلم (2469)."},{"num":15502,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ أُكَيْدِرَ دُومَةَ أَهْدَى إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جُبَّةَ حَرِيرٍ، وَذَلِكَ قَبْلَ أَنْ يَنْهَى نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ الْحَرِيرِ، فَلَبِسَهَا، فَعَجِبَ النَّاسُ مِنْهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَمَنَادِيلُ سَعْدٍ فِي الْجَنَّةِ أَحْسَنُ مِنْ هَذِهِ."],"takhrij":"صحيح: رواه أحمد (13455) عن عبد الوهاب، عن سعيد، عن قتادة، عن أنس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب قبول هدية الحرير دون لبسه بعد التحريم للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (13455).","chapter_en":"Accepting a Gift of Silk Without Wearing It After It Became Forbidden for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated: Ukaydir of Dūmah gifted the Messenger of Allah ﷺ a silk cloak. This was before the Prophet of Allah ﷺ prohibited silk. He wore it, and the people marveled at it. The Prophet ﷺ said: “By the One in whose hand is the soul of Muḥammad, the handkerchiefs of Saʿd in Paradise are more beautiful than this.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (13455)."},{"num":15503,"demo":false,"sanad":"","matn":["عَنْ وَاقِدٍ بن عمرو قَالَ: دَخَلْتُ عَلَى أَنَسِ بْنِ مَالِكٍ فَقَالَ لِي: مَنْ أَنْتَ؟ قُلْتُ: أَنَا وَاقِدُ بْنُ عَمْرِو بْنِ سَعْدِ بْنِ مُعَاذٍ. قَالَ: إِنَّكَ بِسَعْدٍ أَشْبَهُ، ثُمَّ بَكَى وَأَكْثَرَ الْبُكَاءَ، فَقَالَ: رَحْمَةُ اللَّهِ عَلَى سَعْدٍ، كَانَ مِنْ أَعْظَمِ النَّاسِ وَأَطْوَلِهِمْ، ثُمَّ قَالَ: بَعَثَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَيْشًا إِلَى أُكَيْدِرَ دُومَةَ، فَأَرْسَلَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِجُبَّةٍ مِنْ دِيبَاجٍ مَنْسُوجٍ فِيهِ الذَّهَبُ، فَلَبِسَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَامَ عَلَى الْمِنْبَرِ، أَوْ جَلَسَ، فَلَمْ يَتَكَلَّمْ، ثُمَّ نَزَلَ فَجَعَلَ النَّاسُ يَلْمِسُونَ الْجُبَّةَ، وَيَنْظُرُونَ إِلَيْهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَتَعْجَبُونَ مِنْهَا؟. قَالُوا: مَا رَأَيْنَا ثَوْبًا قَطُّ أَحْسَنَ مِنْهُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لَمَنَادِيلُ سَعْدِ بْنِ مُعَاذٍ فِي الْجَنَّةِ أَحْسَنُ مِمَّا تَرَوْنَ."],"takhrij":"حسن: رواه أحمد (12223)، والترمذي (1723)، وابن حبان (7037) كلهم من حديث محمد بن عمرو، قال: أخبرني واقد بن عمرو بن سعد بن معاذ، قال محمد: وكان واقد من أحسن الناس، وأعظمهم، وأطولهم قال: دخلت على أنس بن مالك فذكره. واللفظ لأحمد.","grade":"حسن","chapter_ar":"باب قبول هدية الحرير دون لبسه بعد التحريم للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (12223), al-Tirmidhī (1723), and Ibn Ḥibbān (7037).","chapter_en":"Accepting a Gift of Silk Without Wearing It After It Became Forbidden for Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":3,"content":{"translation":{"en":["Wāqid ibn ʿAmr narrated: I entered upon Anas ibn Mālik. He asked me: “Who are you?” I replied: “I am Wāqid ibn ʿAmr ibn Saʿd ibn Muʿādh.” He said: “You resemble Saʿd.” Then he wept greatly and said: “May Allah have mercy on Saʿd. He was among the largest and tallest of people.” Then he said: The Messenger of Allah ﷺ sent an army toward Ukaydir of Dūmah. Ukaydir sent the Messenger of Allah ﷺ a brocade cloak woven with gold. The Messenger of Allah ﷺ wore it and stood—or sat—upon the pulpit without speaking. Then he came down. The people began touching the cloak and looking at it. The Messenger of Allah ﷺ said: “Are you amazed by it?” They replied: “We have never seen any garment more beautiful than it.” The Prophet ﷺ said: “The handkerchiefs of Saʿd ibn Muʿādh in Paradise are more beautiful than what you see.”"]},"buhuth":{"en":["Ukaydir is the diminutive of Akdar. He was Ukaydir ibn ʿAbd al-Malik ibn ʿAbd al-Jinn, with jīm and nūn.","He was a Christian and the ruler of Dūmah—Dūmat al-Jandal—a town between the Ḥijāz and al-Shām, near Tabūk.","The Prophet ﷺ sent Khālid ibn al-Walīd against him with a military detachment. Khālid captured him and brought him to Madinah.","The Prophet ﷺ reached an agreement with him concerning the jizyah and released him. He returned to his land as a Christian.","According to the author, those who said that he accepted Islam were mistaken."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (12223)، والترمذي (1723)، وابن حبان (7037)."},{"num":15504,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: رَخَّصَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلزُّبَيْرِ وَعَبْدِ الرَّحْمَنِ فِي لُبْسِ الْحَرِيرِ لِحِكَّةٍ بِهِمَا.","وفي لفظ: مِنْ حكة كانت بهما أو وجعٍ كان بهما."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5839)، ومسلم في اللباس (2076: 25) كلاهما من طريق وكيع، عن شعبة، عن قتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب الرخصة في لبس الحرير عند الضرورة للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5839) and Muslim (2076:25).","chapter_en":"Permission for Men to Wear Silk When Necessary","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik narrated: “The Prophet ﷺ permitted al-Zubayr and ʿAbd al-Raḥmān to wear silk because of an itch they suffered from.” In another wording: “Because of an itch or pain that afflicted them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5839)، ومسلم (2076: 25)."},{"num":15505,"demo":false,"sanad":"","matn":["عن أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ تَقُولُ: عِنْدِي لِلزُّبَيْرِ سَاعِدَانِ مِنْ دِيبَاجٍ، كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَاهُمَا إِيَّاهُ، يُقَاتِلُ فِيهِمَا."],"takhrij":"حسن: رواه أحمد (26975) عن يعمر، حدثنا عبد الله –يعني ابن المبارك- قال: أخبرنا ابن لهيعة، عن خالد بن يزيد، قال: سمعت عبد الله مولى أسماء أنه سمع أسماء بنت أبي بكر فذكرته.","grade":"حسن","chapter_ar":"باب الرخصة في لبس الحرير عند الضرورة للرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26975).","chapter_en":"Permission for Men to Wear Silk When Necessary","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":4,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr said: “I have two silk arm coverings belonging to al-Zubayr which the Prophet ﷺ gave him, and he used to fight while wearing them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26975)."},{"num":15506,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ أَحَبَّ أَنْ يُحَلِّقَ حَبِيبَهُ حَلْقَةً مِنْ نَارٍ، فَلْيُحَلِّقْهُ حَلْقَةً مِنْ ذَهَبٍ، وَمَنْ أَحَبَّ أَنْ يُطَوِّقَ حَبِيبَهُ طَوْقًا مِنْ نَارٍ، فَلْيُطَوِّقْهُ طَوْقًا مِنْ ذَهَبٍ، وَمَنْ أَحَبَّ أَنْ يُسَوِّرَ حَبِيبَهُ سِوَارًا مِنْ نَارٍ، فَلْيُسَوِّرْهُ سِوَارًا مِنْ ذَهَبٍ، وَلَكِنْ عَلَيْكُمْ بِالْفِضَّةِ، فَالْعَبُوا بِهَا."],"takhrij":"حسن: رواه أبو داود (4236)، وأحمد (8910) كلاهما من حديث عبدالعزيز، عن أسيد بن أبي أسيد البراد، عن نافع بن عياش، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم استعمال الذهب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4236) and Aḥmad (8910).","chapter_en":"Prohibition of Using Gold","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever wishes to place a ring of fire upon his beloved should place a ring of gold upon him. Whoever wishes to place a collar of fire upon his beloved should place a gold collar upon him. Whoever wishes to place a bracelet of fire upon his beloved should place a gold bracelet upon him. Rather, use silver, and make use of it as you wish.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4236)، وأحمد (8910)."},{"num":15507,"demo":false,"sanad":"","matn":["عن ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَهُ: أَنَّ: ابْنَةَ هُبَيْرَةَ دَخَلَتْ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفِي يَدِهَا خَوَاتِيمُ مِنْ ذَهَبٍ، يُقَالُ لَهَا: الْفَتَخُ، فَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْرَعُ يَدَهَا بِعُصَيَّةٍ مَعَهُ، يَقُولُ لَهَا: أَيَسُرُّكِ أَنْ يَجْعَلَ اللَّهُ فِي يَدِكِ خَوَاتِيمَ مِنْ نَارٍ؟ فَأَتَتْ فَاطِمَةَ فَشَكَتْ إِلَيْهَا مَا صَنَعَ بِهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: وَانْطَلَقْتُ أَنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ خَلْفَ الْبَابِ، وَكَانَ إِذَا اسْتَأْذَنَ قَامَ خَلْفَ الْبَابِ قَالَ: فَقَالَتْ لَهَا فَاطِمَةُ: انْظُرِي إِلَى هَذِهِ السِّلْسِلَةِ الَّتِي أَهْدَاهَا إِلَيَّ أَبُو حَسَنٍ. قَالَ: وَفِي يَدِهَا سِلْسِلَةٌ مِنْ ذَهَبٍ، فَدَخَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا فَاطِمَةُ بِالْعَدْلِ أَنْ يَقُولَ النَّاسُ فَاطِمَةُ بِنْتُ مُحَمَّدٍ، وَفِي يَدِكِ سِلْسِلَةٌ مِنْ نَارٍ؟ ثُمَّ عَذَمَهَا عَذْمًا شَدِيدًا، ثُمَّ خَرَجَ وَلَمْ يَقْعُدْ، فَأَمَرَتْ بِالسِّلْسِلَةِ فَبِيعَتْ فَاشْتَرَتْ بِثَمَنِهَا عَبْدًا فَأَعْتَقَتْهُ، فَلَمَّا سَمِعَ بِذَلِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَبَّرَ وَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي نَجَّى فَاطِمَةَ مِنَ النَّارِ."],"takhrij":"صحيح: رواه النسائي (5140)، وأحمد (22398)، والحاكم (3/153) كلهم من حديث يحيى بن أبي كثير قال: حدثني زيد بن سلام، أن جده حدثه أن أبا أسماء حدثه، أن ثوبان مولى رسول الله صلى الله عليه وسلم حدثه فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب تحريم استعمال الذهب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (5140), Aḥmad (22398), and al-Ḥākim (3/153).","chapter_en":"Prohibition of Using Gold","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Thawbān, the freedman of the Messenger of Allah ﷺ, narrated: The daughter of Hubayrah entered upon the Messenger of Allah ﷺ wearing gold rings on her hands known as fatakh. The Messenger of Allah ﷺ began tapping her hand with a small stick he had and saying: “Would you like Allah to place rings of fire upon your hand?” She went to Fāṭimah and complained to her about what the Messenger of Allah ﷺ had done. Thawbān continued: I went with the Messenger of Allah ﷺ, and he stood behind the door. Whenever he sought permission to enter, he would stand behind the door. Fāṭimah said to the woman: “Look at this chain that Abū al-Ḥasan gave me.” She had a gold chain in her hand. The Prophet ﷺ entered and said: “O Fāṭimah, is it proper that people should say, ‘Fāṭimah, the daughter of Muḥammad, has a chain of fire in her hand’?” Then he strongly admonished her and left without sitting down. She ordered that the chain be sold, and with its price she purchased a slave and freed him. When the Prophet ﷺ heard about this, he said Allāhu akbar and said: “Praise be to Allah who saved Fāṭimah from the Fire.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه النسائي (5140)، وأحمد (22398)، والحاكم (3/153)."},{"num":15508,"demo":false,"sanad":"","matn":["عن أَسْمَاءَ بِنْتِ يَزِيدَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَمَعَ نِسَاءَ الْمُسْلِمِينَ لِلْبَيْعَةِ، فَقَالَتْ لَهُ: أَسْمَاءُ: أَلَا تَحْسُرُ لَنَا عَنْ يَدِكَ يَا رَسُولَ اللَّهِ؟ فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي لَسْتُ أُصَافِحُ النِّسَاءَ، وَلَكِنْ آخُذُ عَلَيْهِنَّ، وَفِي النِّسَاءِ خَالَةٌ لَهَا عَلَيْهَا قُلْبَانِ مِنْ ذَهَبٍ، وَخَوَاتِيمُ مِنْ ذَهَبٍ. فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا هَذِهِ، هَلْ يَسُرُّكِ أَنْ يُحَلِّيَكِ اللهُ يَوْمَ الْقِيَامَةِ مِنْ جَمْرِ جَهَنَّمَ سِوَارَيْنِ وَخَوَاتِيمَ؟ فَقَالَتْ: أَعُوذُ بِاللهِ يَا نَبِيَّ اللَّهِ، قَالَتْ: قُلْتُ: يَا خَالَةُ اطْرَحِي مَا عَلَيْكِ، فَطَرَحَتْهُ فَحَدَّثَتْنِي أَسْمَاءُ، وَاللهِ يَا بُنَيَّ لَقَدْ طَرَحَتْهُ، فَمَا أَدْرِي مَنْ لَقَطَهُ مِنْ مَكَانِهِ، وَلَا الْتَفَتَ مِنَّا أَحَدٌ إِلَيْهِ، قَالَتْ أَسْمَاءُ: فَقُلْتُ: يَا نَبِيَّ اللَّهِ إِنَّ إِحْدَاهُنَّ تَصْلَفُ عِنْدَ زَوْجِهَا، إِذَا لَمْ تُمَلَّحْ لَهُ، أَوْ تَحَلَّى لَهُ، قَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا عَلَى إِحْدَاكُنَّ أَنْ تَتَّخِذَ قُرْطَيْنِ مِنْ فِضَّةٍ، وَتَتَّخِذَ لَهَا جُمَانَتَيْنِ مِنْ فِضَّةٍ، فَتُدْرِجَهُ بَيْنَ أَنَامِلِهَا بِشَيْءٍ مِنْ زَعْفَرَانٍ، فَإِذَا هُوَ كَالذَّهَبِ يَبْرُقُ."],"takhrij":"حسن: رواه أحمد (27572) عن هاشم هو ابن القاسم، حدثنا عبد الحميد، قال: حدثنا شهر بن حوشب، قال: حدثتني أسماء بنت يزيد فذكرته.","grade":"حسن","chapter_ar":"باب تحريم استعمال الذهب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27572).","chapter_en":"Prohibition of Using Gold","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Asmāʾ bint Yazīd narrated: The Messenger of Allah ﷺ gathered the Muslim women to take their pledge of allegiance. Asmāʾ said to him: “O Messenger of Allah, will you not uncover your hand for us?” The Messenger of Allah ﷺ replied: “I do not shake hands with women. I only take their pledge verbally.” Among the women was a maternal aunt of Asmāʾ who was wearing two gold bracelets and gold rings. The Messenger of Allah ﷺ said to her: “O woman, would you like Allah to adorn you on the Day of Resurrection with two bracelets and rings made from the embers of Hell?” She replied: “I seek refuge in Allah, O Messenger of Allah.” Asmāʾ said: “O my aunt, throw off what you are wearing.” So she removed it. Asmāʾ later said: “By Allah, my son, she threw them down, and I do not know who picked them up from that place. None of us even turned to look at them.” Asmāʾ said: I asked: “O Prophet of Allah, a woman needs to beautify herself for her husband. What should she do if she has no adornment or jewelry?” The Prophet of Allah ﷺ replied: “There is no harm in one of you taking two silver earrings and two silver beads and rubbing them between her fingers with some saffron until they shine like gold.”"]},"buhuth":{"en":["In the following hadith, it is Asmāʾ herself who removes two gold bracelets. The author therefore understands that both incidents may have occurred to the two women in the same gathering."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27572)."},{"num":15509,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ، قَالَتْ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأُبَايِعَهُ، فَدَنَوْتُ، وَعَلَيَّ سِوَارَانِ مِنْ ذَهَبٍ، فَبَصُرَ بِبَصِيصِهِمَا، فَقَالَ: أَلْقِي السِّوَارَيْنِ يَا أَسْمَاءُ، أَمَا تَخَافِينَ أَنْ يُسَوِّرَكِ اللهُ بِأَسَاوِرَ مِنْ نَارٍ.","قَالَتْ: فَأَلْقَيْتُهُمَا، فَمَا أَدْرِي مَنْ أَخَذَهُمَا."],"takhrij":"حسن: رواه أحمد (27563) واللفظ له، والطبراني (24/182) كلاهما من طريق شهر بن حوشب أنه لقي أسماء بنت يزيد قال: فحدثتني فذكرت الحديث.","grade":"حسن","chapter_ar":"باب تحريم استعمال الذهب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27563), and this is his wording, and al-Ṭabarānī (24/182).","chapter_en":"Prohibition of Using Gold","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Asmāʾ bint Yazīd narrated: I came to the Messenger of Allah ﷺ to pledge allegiance to him. I approached while wearing two gold bracelets. He noticed their gleam and said: “Take off the two bracelets, O Asmāʾ. Do you not fear that Allah may put a bracelet of fire upon you?” She said: “So I threw them off, and I do not know who took them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (27563) واللفظ له، والطبراني (24/182)."},{"num":15510,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَآلِهِ وَسَلَّمَ قَالَ: وَيْلٌ لِلنِّسَاءِ مِنَ الأَحْمَرِينَ: الذَّهَبِ وَالْمُعَصْفَرِ."],"takhrij":"حسن: رواه ابن حبان (5968)، والبيهقي في الشعب (5780) كلاهما من حديث سريج بن يونس، قال: حدثنا عباد بن عباد، عن محمد بن عمرو بن علقمة، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب تحريم استعمال الذهب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (5968) and al-Bayhaqī in Shuʿab al-Īmān (5780).","chapter_en":"Prohibition of Using Gold","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Woe to women because of the two red things: gold and garments dyed with safflower.”"]},"buhuth":{"en":["Fiqh of the Hadiths","The hadiths prohibiting women from using gold and silver have been interpreted as applying when the zakāh due on them is not paid, or when they are worn for the purpose of displaying pride.","It is also possible that the prohibition initially applied to everyone in the early period of Islam, after which it was made lawful for women while remaining forbidden for men, as is clearly shown in the following chapter."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (5968)، والبيهقي في الشعب (5780)."},{"num":15511,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنْ خَاتَمِ الذَّهَبِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5864)، ومسلم في اللباس والزينة (2089) كلاهما من طريق شعبة، عن قتادة، عن النضر بن أنس، عن بشير بن نهيك، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5864) and Muslim (2089).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ prohibited wearing a gold ring."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5864)، ومسلم (2089)."},{"num":15512,"demo":false,"sanad":"","matn":["عن الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا يَقُولُ: نَهَانَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ سَبْعٍ: نَهَى عَنْ خَاتَمِ الذَّهَبِ ـ أَوْ قَالَ: حَلْقَةِ الذَّهَبِ، ـ وَعَنِ الْحَرِيرِ، وَالإِسْتَبْرَقِ، وَالدِّيبَاجِ، وَالْمِيثَرَةِ الْحَمْرَاءِ، وَالْقَسِّيِّ، وَآنِيَةِ الْفِضَّةِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5863)، ومسلم في اللباس والزينة (2066) كلاهما من طريق شعبة، حدثنا أشعث بن سليم، قال: سمعت معاوية بن سويد بن مقرن، قال: سمعت البراء بن عازب يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5863) and Muslim (2066).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated: The Prophet ﷺ prohibited us from seven things: The gold ring—or he said, a ring of gold—silk, istabraq, brocade, red mītharah coverings, qassī garments, and silver vessels."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5863)، ومسلم (2066)."},{"num":15513,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اصْطَنَعَ خَاتَمًا مِنْ ذَهَبٍ، فَكَانَ يَجْعَلُ فَصَّهُ فِي بَاطِنِ كَفِّهِ إِذَا لَبِسَهُ، فَصَنَعَ النَّاسُ، ثُمَّ إِنَّهُ جَلَسَ عَلَى الْمِنْبَرِ فَنَزَعَهُ، فَقَالَ: إِنِّي كُنْتُ أَلْبَسُ هَذَا الْخَاتَِمَ، وَأَجْعَلُ فَصَّهُ مِنْ دَاخِلٍ، فَرَمَى بِهِ، ثُمَّ قَالَ: وَاللهِ، لَا أَلْبَسُهُ أَبَدًا، فَنَبَذَ النَّاسُ خَوَاتِيمَهُمْ.","وفي رواية: واتخذ خاتما من ورق."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5876)، ومسلم في اللباس والزينة (2091) كلاهما من حديث نافع، عن عبد الله فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5876) and Muslim (2091). The wording is Muslim’s.","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Messenger of Allah ﷺ had a gold ring made. Whenever he wore it, he would place its stone toward the inside of his palm. The people then had similar rings made. Later, he sat upon the pulpit, removed the ring, and said: “I used to wear this ring and place its stone toward the inside.” Then he threw it away and said: “By Allah, I will never wear it again.” So the people threw away their rings as well. In another narration: “He then took a silver ring.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5876)، ومسلم (2091)، والسياق لمسلم."},{"num":15514,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عَبَّاسٍ، أنّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى خَاتَمًا مِنْ ذهبٍ فِي يدِ رجلٍ، فنـزعَه فَطَرَحَهُ، وَقَالَ: يَعْمِدُ أَحَدُكُمْ إِلَى جَمْرَةٍ مِنْ نارٍ، فَيَجْعَلُهَا فِي يَدِهِ، فَقِيلَ لِلرَّجُلِ بعد مَا ذَهَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : خُذْ خَاتَِمَكَ، انتفِعْ بِهِ، قَالَ: لَا وَاللهِ، لَا آخُذُهُ أَبَدًا، وَقَدْ طَرَحَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2090) عن محمد بن سهل التميمي، حدثنا ابن أبي مريم (هو سعيد)، أخبرني محمد بن جعفر، أخبرني إبراهيم بن عقبة، عن كريب، مولى ابن عباس، عن عبد الله بن عباس فذكره.","grade":"صحيح","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2090).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: The Messenger of Allah ﷺ saw a gold ring on a man’s hand. He removed it and threw it away, saying: “One of you deliberately takes an ember from the Fire and places it in his hand.” After the Messenger of Allah ﷺ left, someone said to the man: “Take your ring and benefit from it.” He replied: “No, by Allah. I will never take it after the Messenger of Allah ﷺ threw it away.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2090)."},{"num":15515,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ رَأَى فِي يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ وَرِقٍ يَوْمًا وَاحِدًا، ثُمَّ إِنَّ النَّاسَ اصْطَنَعُوا الْخَوَاتِيمَ مِنْ وَرِقٍ وَلَبِسُوهَا، فَطَرَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمَهُ، فَطَرَحَ النَّاسُ خَوَاتِيمَهُمْ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5868) من طريق يونس (هو ابن يزيد الأيلي)، ومسلم في اللباس (2093: 59) من طريق إبراهيم بن سعد، وmuslim(60) من طريق زياد (هو ابن سعد) ثلاثتُهم عن الزهري قال: حدثني أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5868) and Muslim (2093:59).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik narrated: He saw a silver ring on the hand of the Messenger of Allah ﷺ for one day. The people then had silver rings made and began wearing them. The Messenger of Allah ﷺ threw away his ring, so the people threw away their rings."]},"buhuth":{"en":["The wording “a silver ring” is problematic, because the well-known report is that the ring the Prophet ﷺ discarded after the people imitated him was a gold ring, as previously stated in the hadith of Ibn ʿUmar.","For this reason, the majority of scholars regarded al-Zuhrī’s mention of silver in this report as an error.","Al-Nawawī, following al-Qāḍī ʿIyāḍ, attributed this position to all the scholars of hadith.","It is also possible that the error came from someone below al-Zuhrī in the chain, because al-Zuhrī himself narrated from Anas the report concerning the ring of the Prophet ﷺ engraved with:","“Muḥammad, the Messenger of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9606],"tks":"متفق عليه: رواه البخاري (5868)، ومسلم (2093: 59)."},{"num":15516,"demo":false,"sanad":"","matn":["عَنْ عَلْقَمَةَ، قَالَ: كُنَّا جُلُوسًا مَعَ ابْنِ مَسْعُودٍ، فَجَاءَ خَبَّابٌ، فَقَالَ: يَا أَبَا عَبْدِ الرَّحْمَنِ، أَيَسْتَطِيعُ هَؤُلاَءِ الشَّبَابُ أَنْ يَقْرَءُوا كَمَا تَقْرَأُ؟ قَالَ: أَمَا إِنَّكَ لَوْ شِئْتَ أَمَرْتُ بَعْضَهُمْ يَقْرَأُ عَلَيْكَ؟ قَالَ: أَجَلْ. قَالَ: اقْرَأْ يَا عَلْقَمَةُ. فَقَالَ زَيْدُ بْنُ حُدَيْرٍ، أَخُو زِيَادِ بْنِ حُدَيْرٍ: أَتَأْمُرُ عَلْقَمَةَ أَنْ يَقْرَأَ وَلَيْسَ بِأَقْرَئِنَا؟ قَالَ: أَمَا إِنَّكَ إِنْ شِئْتَ أَخْبَرْتُكَ بِمَا قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي قَوْمِكَ وَقَوْمِهِ. فَقَرَأْتُ خَمْسِينَ آيَةً مِنْ سُورَةِ مَرْيَمَ، فَقَالَ عَبْدُ اللَّهِ: كَيْفَ تَرَى؟ قَالَ: قَدْ أَحْسَنَ. قَالَ عَبْدُ اللَّهِ: مَا أَقْرَأُ شَيْئًا إِلاَّ وَهُوَ يَقْرَؤُهُ، ثُمَّ الْتَفَتَ إِلَى خَبَّابٍ وَعَلَيْهِ خَاتَمٌ مِنْ ذَهَبٍ، فَقَالَ: أَلَمْ يَأْنِ لِهَذَا الْخَاتَمِ أَنْ يُلْقَى، قَالَ: أَمَا إِنَّكَ لَنْ تَرَاهُ عَلَىَّ بَعْدَ الْيَوْمِ، فَأَلْقَاهُ."],"takhrij":"صحيح: رواه البخاري في المغازي (4391) عن عبدان، عن أبي حمزة، عن الأعمش، عن إبراهيم، عن علقمة فذكره.","grade":"صحيح","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4391).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿAlqamah narrated: We were sitting with Ibn Masʿūd when Khabbāb came. He said: “O Abū ʿAbd al-Raḥmān, can these young men recite as you recite?” Ibn Masʿūd replied: “If you wish, I can instruct one of them to recite to you.” He said: “Yes.” Ibn Masʿūd said: “Recite, O ʿAlqamah.” Zayd ibn Ḥudayr, the brother of Ziyād ibn Ḥudayr, said: “You order ʿAlqamah to recite when he is not the best reciter among us?” Ibn Masʿūd said: “If you wish, I can tell you what the Prophet ﷺ said concerning your people and his people.” I then recited fifty verses from Sūrat Maryam. ʿAbdullāh asked: “What do you think?” Khabbāb replied: “He has recited well.” ʿAbdullāh said: “Whatever I can recite, he can recite.” Then he turned toward Khabbāb, who was wearing a gold ring, and said: “Is it not time for this ring to be thrown away?” Khabbāb replied: “You will not see it on me after today.” Then he threw it away."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4391)."},{"num":15517,"demo":false,"sanad":"","matn":["عن علي بن أَبِي طَالِبٍ نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ خَاتِمِ الذَّهَبِ، وَعَنِ الْقَسِّيِّ، وَعَنِ الْمِيثَرَةِ، وَعَنِ الْجَعَةِ."],"takhrij":"حسن: رواه الترمذي (2808)، وأبو داود (4051)، والنسائي (5165)، وابن ماجه (3654)، وابن أبي شيبة (8/110)، وأحمد (1102) كلهم من حديث أبي الأحوص، عن أبي إسحاق، عن هبيرة بن يريم، عن علي فذكره.","grade":"حسن","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (2808), Abū Dāwūd (4051), al-Nasā’ī (5165), and Ibn Mājah (3654).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: “The Messenger of Allah ﷺ prohibited the gold ring, qassī garments, mītharah coverings, and beer made from barley.”"]},"buhuth":{"en":["Its original version is in Ṣaḥīḥ Muslim (2078) with differences in wording, and it has been cited in its proper place."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7476],"tks":"حسن: رواه الترمذي (2808)، وأبو داود (4051)، والنسائي (5165)، وابن ماجه (3654)."},{"num":15518,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَدِمَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِلْيَةٌ مِنْ عِنْدِ النَّجَاشِيِّ أَهْدَاهَا لَهُ، فِيهَا خَاتَمٌ مِنْ ذَهَبٍ فِيهِ فَصٌّ حَبَشِيٌّ، - قَالَتْ: - فَأَخَذَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعُودٍ مُعْرِضًا عَنْهُ أَوْ بِبَعْضِ أَصَابِعِهِ ثُمَّ دَعَى أُمَامَةَ ابْنَةَ أَبِي الْعَاصِ، ابْنَةَ ابْنَتِهِ زَيْنَبَ، فَقَالَ: تَحَلَّىْ بِهَذَا يَا بُنَيَّةُ."],"takhrij":"حسن: رواه أبو داود (4235)، وابن ماجه (3644)، وأحمد (24880) كلهم من حديث محمد بن إسحاق قال: حدثني يحيى بن عباد، عن أبيه عباد بن عبدالله، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4235), Ibn Mājah (3644), and Aḥmad (24880).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿĀ’ishah narrated: Some jewelry gifted by the Negus was brought to the Prophet ﷺ. Among it was a gold ring with an Abyssinian stone. She said: The Messenger of Allah ﷺ picked it up with a stick while turning away from it—or with some of his fingers—then called Umāmah, daughter of Abū al-ʿĀṣ and granddaughter of his daughter Zaynab, and said: “Adorn yourself with this, my little daughter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4235)، وابن ماجه (3644)، وأحمد (24880)."},{"num":15519,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ بِنْتِ نُبَيْطِ بْنِ جَابِرٍ، قَالَ: حَدَّثَتْنِي أُمِّي، وَخَالَتِي، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَلَّاهُنَّ رِعَاثًا مِنَ الذَّهَبِ."],"takhrij":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (3397) عن هشام بن عمار، ثنا سعيد بن يحيى اللخمي، ثنا محمد بن عمرو بن علقمة، حدثني محمد بن عمارة بن حزم، عن زينب بنت نبيط بن جابر فذكرته.","grade":"حسن","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī ʿĀṣim in al-Āḥād wa-l-Mathānī (6/168).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Zaynab bint Nubayṭ ibn Jābir narrated: My mother and my maternal aunt told me that: “The Prophet ﷺ adorned them with gold earrings.”"]},"buhuth":{"en":["The word “ruʿāth” refers to earrings, which are ornaments worn on the ears. Its singular is raʿthah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (3397)."},{"num":15520,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ أنه قَالَ: نَهَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ التختم بِالذَّهَبِ."],"takhrij":"حسن: رواه الترمذي (1738)، والنسائي (5187)، وأحمد (19980)، وابن حبان (5406) كلهم من حديث أبي التياح، قال: حدثني حفص الليثي، قال: أشهد على عمران بن حصين أنه قال: فذكر الحديث.","grade":"حسن","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (1738), al-Nasā’ī (5187), Aḥmad (19980), and Ibn Ḥibbān (5406).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated: “The Messenger of Allah ﷺ prohibited wearing gold rings.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1738)، والنسائي (5187)، وأحمد (19980)، وابن حبان (5406)."},{"num":15521,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنَّا مِنْ أَشْجَعَ، قَالَ: رَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيَّ خَاتَمًا مِنْ ذَهَبٍ، فَأَمَرَنِي أَنْ أَطْرَحَهُ، فَطَرَحْتُهُ إِلَى يَوْمِي هَذَا."],"takhrij":"صحيح: رواه أحمد (18290) عن محمد بن جعفر، حدثنا شعبة، عن حصين، عن سالم بن أبي الجعد، عن رجل منا من أشجع فذكره.","grade":"صحيح","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (18290).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["A man from Ashjaʿ narrated: The Messenger of Allah ﷺ saw a gold ring on me and ordered me to throw it away. “So I threw it away, and I have not worn it to this very day.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (18290)."},{"num":15522,"demo":false,"sanad":"","matn":["عَنْ أَبِي شَيْخٍ، أَنَّهُ سَمِعَ مُعَاوِيَةَ، وَعِنْدَهُ، جَمْعٌ مِنْ أَصْحَابِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَتَعْلَمُونَ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ لُبْسِ الذَّهَبِ إِلاَّ مُقَطَّعًا؟ قَالُوا: اللَّهُمَّ نَعَمْ."],"takhrij":"حسن: رواه النسائي (5151) عن محمد بن المثنى قال: حدثنا ابن أبي عدي، عن سعيد، عن قتادة، عن أبي الشيخ، أنه سمع معاوية فذكره.","grade":"حسن","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (5151).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["Abū al-Shaykh narrated that he heard Muʿāwiyah, while a group of the Companions of the Prophet ﷺ were with him, say: “Do you know that the Prophet of Allah ﷺ prohibited wearing gold except in small separate pieces?” They replied: “Yes.”"]},"buhuth":{"en":["The word “muqaṭṭaʿan” means in small separated amounts, such as a button, a tooth, or a piece used for the nose.","According to the author, a large amount is forbidden because of extravagance and pride. Moreover, this was an age of jihād, so spending wealth in the path of Allah was more appropriate than storing gold."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5151)."},{"num":15523,"demo":false,"sanad":"","matn":["عن عمرو بن أبي عمرو قال: سألت القاسم بن محمد قلت: إن ناسا يزعمون أن رسول الله صلى الله عليه وسلم نهى عن الأحمرين العصفر والذهب، فقال: كذبوا، والله لقد رأيتُ عائشة تلبس المعصفرات وتلبس خواتم الذهب."],"takhrij":"حسن: رواه ابن سعد (6946) عن عبد الله بن مسلمة بن قعنب، حدثنا عبدالعزيز بن محمد، عن عمرو بن أبي عمرو فذكره.","grade":"حسن","chapter_ar":"باب بقي الحظر على الرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Saʿd (8/70).","chapter_en":"The Prohibition Remained for Men but Not for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn Abī ʿAmr narrated: I asked al-Qāsim ibn Muḥammad: “Some people claim that the Messenger of Allah ﷺ prohibited the two red things: safflower-dyed clothing and gold.” He replied: “They have spoken falsely. By Allah, I saw ʿĀ’ishah wearing safflower-dyed garments and wearing gold rings.”"]},"buhuth":{"en":["Fiqh of This Chapter","At the beginning of Islam, gold and silver were permissible for both men and women under the original presumption of permissibility. The prohibition was then imposed upon everyone, after which it was made lawful for women while remaining forbidden for men.","It is authentically established from ʿĀ’ishah that she used to adorn her sister’s daughters with gold, while Umm Salamah disliked and objected to that.","Al-Ṭaḥāwī narrated this in Sharḥ al-Mushkil (12/299) with an authentic chain.","Ibn Shāhīn said in Nāsikh al-Ḥadīth wa-Mansūkhuhu (p. 446):","“At the beginning of Islam, men used to wear gold rings and other such things. The prohibition then applied to all people. Afterward, the Messenger of Allah ﷺ permitted it for women but not for men. Thus, what had previously been prohibited to women became permissible for them, and the later permission abrogated the prohibition.”","Shaykh al-Islām Ibn Taymiyyah said in Majmūʿ al-Fatāwā (25/64):","“The chapter of clothing is broader than the chapter of vessels. Gold and silver vessels are forbidden to both men and women.","As for clothing, wearing gold and silver is permissible for women by scholarly agreement, and a man may use what he genuinely needs of them.","A small amount of silver is permissible for adornment. Likewise, a small amount of gold that is secondary to something else, such as embroidery and the like, is permissible according to the stronger of the two views in the madhhab of Aḥmad and others, for the Prophet ﷺ prohibited gold except in small separated portions.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن سعد (6946)."},{"num":15524,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ طَرَفَةَ، أَنَّ جَدَّهُ عَرْفَجَةَ بْنَ أَسْعَدَ أُصِيبَ أَنْفُهُ فِي الْجَاهِلِيَّةِ يَوْمَ الْكُلَابِ، فَاتَّخَذَ أَنْفًا مِنْ وَرِقٍ، فَأَنْتَنَ عَلَيْهِ، فَأَمَرَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَتَّخِذَ أَنْفًا، يَعْنِي، مِنْ ذَهَبٍ."],"takhrij":"حسن: رواه أبو داود (4232)، والترمذي (1770)، والنسائي (5161)، وأحمد (20269)، وصحّحه ابن حبان (5462) كلهم من حديث أبي الأشهب، عن عبد الرحمن بن طرفة فذكره.","grade":"حسن","chapter_ar":"باب جواز ربط الأنف والأسنان بالذهب","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4232), al-Tirmidhī (1770), al-Nasā’ī (5161), and Aḥmad (20269).","chapter_en":"Permissibility of Using Gold for the Nose and Teeth","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":7,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Ṭarafah narrated that his grandfather, ʿArfajah ibn Asʿad, had his nose injured during the pre-Islamic period on the Day of al-Kulāb. He made himself a nose of silver, but it developed an unpleasant odor. The Prophet ﷺ then instructed him to make a nose—meaning, of gold."]},"buhuth":{"en":["The Day of al-Kulāb was a well-known battle from the days of Jāhiliyyah, one of their recorded battles. This was stated by al-Khaṭṭābī.","Al-Khaṭṭābī said:","“This contains evidence for the permissibility of men using a small amount of gold when there is a necessity, such as fastening teeth with it, and similar cases where another material does not serve the same purpose.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4232)، والترمذي (1770)، والنسائي (5161)، وأحمد (20269)."},{"num":15525,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُتَشَبِّهِينَ مِنَ الرِّجَالِ بِالنِّسَاءِ، وَالْمُتَشَبِّهَاتِ مِنَ النِّسَاءِ بِالرِّجَالِ."],"takhrij":"صحيح: رواه البخاري في اللباس (5885) عن محمد بن بشار، حدثنا غندر، حدثنا شعبة، عن قتادة، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ذم المتشبهين بالنساء والمتشبهات بالرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5885).","chapter_en":"Condemnation of Men Who Imitate Women and Women Who Imitate Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbās narrated: “The Messenger of Allah ﷺ cursed men who imitate women and women who imitate men.”"]},"buhuth":{"en":["According to the author, this imitation refers to imitation in clothing, adornment, and mannerisms.","As for matters of social and family life beyond that—such as seeking and spreading knowledge or assuming appropriate administrative responsibilities—these are not included in the prohibited imitation."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5885)."},{"num":15526,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: لَعَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمُخَنَّثِينَ مِنَ الرِّجَالِ، وَالْمُتَرَجِّلاَتِ مِنَ النِّسَاءِ وَقَالَ: أَخْرِجُوهُمْ مِنْ بُيُوتِكُمْ.","قَالَ: وأخرج النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فُلَانًا، وَأَخْرَجَ عُمَرُ فُلَانًا."],"takhrij":"صحيح: رواه البخاري في اللباس (5886) عن معاذ بن فضالة، حدثنا هشام، عن يحيى، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ذم المتشبهين بالنساء والمتشبهات بالرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5886).","chapter_en":"Condemnation of Men Who Imitate Women and Women Who Imitate Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ cursed effeminate men and women who deliberately adopted masculine behavior, and said: “Expel them from your houses.” Ibn ʿAbbās said: “The Prophet ﷺ expelled one such person, and ʿUmar expelled another.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5886)."},{"num":15527,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الرَّجُلَ يَلْبَسُ لِبْسَةَ الْمَرْأَةِ، وَالْمَرْأَةَ تَلْبَسُ لِبْسَةَ الرَّجُلِ."],"takhrij":"صحيح: رواه أبو داود (4098)، وابن ماجه (1903)، وأحمد (8309)، وصحّحه ابن حبان (5751)، والحاكم (4/194) كلهم من طريق سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ذم المتشبهين بالنساء والمتشبهات بالرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4098), Ibn Mājah (1903), Aḥmad (8309), and authenticated by Ibn Ḥibbān (5751).","chapter_en":"Condemnation of Men Who Imitate Women and Women Who Imitate Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated: “The Messenger of Allah ﷺ cursed the man who wears the clothing of a woman and the woman who wears the clothing of a man.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6438],"tks":"صحيح: رواه أبو داود (4098)، وابن ماجه (1903)، وأحمد (8309)، وصححه ابن حبان (5751)."},{"num":15528,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : ثَلَاثٌ لايدخلون الْجَنَّةَ، وَلَا يَنْظُرُ اللَّهُ إِلَيْهِمْ يَوْمَ الْقِيَامَةِ: الْعَاقُّ بِوَالِدَيْهِ، وَالْمَرْأَةُ الْمُتَرَجِّلَةُ الْمُتَشَبِّهَةُ بِالرِّجَالِ، وَالدَّيُّوثُ."],"takhrij":"حسن: رواه أحمد (6180)، والبزار –كشف الأستار (1876)، وأبو يعلى (5551)، وصحّحه ابن حبان (7340)، والحاكم (1/72) كلهم من حديث عبد الله بن يسار مولى ابن عمر قال: أشهد لقد سمعت سالما يقول: قال عبد الله فذكره. وإسناده حسن من أجل عبد الله بن يسار فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب ذم المتشبهين بالنساء والمتشبهات بالرجال","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6180), al-Bazzār as cited in Kashf al-Astār (1876), Abū Yaʿlā (5551), and authenticated by Ibn Ḥibbān (7340).","chapter_en":"Condemnation of Men Who Imitate Women and Women Who Imitate Men","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “There are three who will not enter Paradise, and Allah will not look at them on the Day of Resurrection: one who is disobedient to his parents, a woman who deliberately adopts the appearance and manner of men, and a dayyūth.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه أحمد (6180)، والبزار في كشف الأستار (1876)، وأبو يعلى (5551)، وصححه ابن حبان (7340)."},{"num":15529,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: لَعَنَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  الْوَاصِلَةَ وَالْمُسْتَوْصِلَةَ، وَالْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5947)، ومسلم في اللباس والزينة (2124) كلاهما من طريق يحيى بن سعيد (هو القطان)، عن عبيد الله، أخبرني نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5947) and Muslim (2124).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar narrated: “The Prophet ﷺ cursed the woman who attaches hair extensions, the woman who has them attached, the woman who tattoos, and the woman who has herself tattooed.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5947)، ومسلم (2124)."},{"num":15530,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْعَيْنُ حَقٌّ. وَنَهَى عَنِ الْوَشْمِ."],"takhrij":"صحيح: رواه البخاري في اللباس (5944) عن يحيى، ثنا عبد الرزاق، عن معمر، عن همام، عن أبي هريرة فذكره. ورواه مسلم في السلام (2187) من طريق عبد الرزاق به، وليس عنده ذكر النهي عن الوشم.","grade":"صحيح","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5944) and Muslim (2187).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The evil eye is real.” And he prohibited tattooing."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5944)، ومسلم (2187)."},{"num":15531,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: أُتِيَ عُمَرُ بِامْرَأَةٍ تَشِمُ، فَقَامَ فَقَالَ: أَنْشُدُكُمْ بِاللَّهِ، مَنْ سَمِعَ مِنَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْوَشْمِ؟ فَقَالَ أَبُو هُرَيْرَةَ: فَقُمْتُ فَقُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ أَنَا سَمِعْتُ. قَالَ: مَا سَمِعْتَ؟ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: لاَ تَشِمْنَ وَلاَ تَسْتَوْشِمْنَ."],"takhrij":"صحيح: رواه البخاري في اللباس (5946) عن زهير بن حرب، ثنا جرير، عن أبي زرعة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5946).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated: A woman who performed tattooing was brought before ʿUmar. He stood and said: “I adjure you by Allah: who among you heard anything from the Prophet ﷺ concerning tattooing?” Abū Hurayrah said: I stood and said: “O Commander of the Believers, I heard him.” ʿUmar asked: “What did you hear?” I replied: I heard the Prophet ﷺ say: “Do not tattoo others, and do not have yourselves tattooed.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5946)."},{"num":15532,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَعَنَ اللَّهُ الْوَاصِلَةَ وَالْمُسْتَوْصِلَةَ، وَالْوَاشِمَةَ وَالْمُسْتَوْشِمَةَ."],"takhrij":"صحيح: رواه البخاري في اللباس (5933) فقال: وقال ابن أبي شيبة، حدثنا يونس بن محمد، حدثنا فُليح، عن زيد بن أسلم، عن عطاء بن يسار، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5933) and Ibn Abī Shaybah in al-Muṣannaf (25740).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Allah has cursed the woman who attaches hair extensions and the one who has them attached, the woman who tattoos and the one who has herself tattooed.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5933)، وابن أبي شيبة في المصنف (25740)."},{"num":15533,"demo":false,"sanad":"","matn":["عَنْ عَوْنِ بْنِ أَبِي جُحَيْفَةَ، قَالَ: رَأَيْتُ أَبِي، فَقَالَ: إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ ثَمَنِ الدَّمِ، وَثَمَنِ الْكَلْبِ، وَآكِلِ الرِّبَا وَمُوكِلِهِ، وَالْوَاشِمَةِ وَالْمُسْتَوْشِمَةِ."],"takhrij":"صحيح: رواه البخاري في اللباس (5945) عن سليمان بن حرب، ثنا شعبة، عن عون بن أبي جحيفة فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5945).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["ʿAwn ibn Abī Juḥayfah narrated from his father: “The Prophet ﷺ prohibited taking payment for blood, the price of a dog, consuming usury and giving it, and he prohibited the woman who tattoos and the woman who has herself tattooed.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5945)."},{"num":15534,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن مَسْعُودٍ قَالَ: لَعَنَ اللَّهُ الْوَاشِمَاتِ وَالْمُسْتَوْشِمَاتِ، وَالنَّامِصَاتِ وَالْمُتَنَمِّصَاتِ، وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللهِ. قَالَ: فَبَلَغَ ذَلِكَ امْرَأَةً مِنْ بَنِي أَسَدٍ يُقَالُ لَهَا: أُمُّ يَعْقُوبَ وَكَانَتْ تَقْرَأُ الْقُرْآنَ، فَأَتَتْهُ فَقَالَتْ: مَا حَدِيثٌ بَلَغَنِي عَنْكَ أَنَّكَ لَعَنْتَ الْوَاشِمَاتِ وَالْمُسْتَوْشِمَاتِ، وَالْمُتَنَمِّصَاتِ وَالْمُتَفَلِّجَاتِ لِلْحُسْنِ الْمُغَيِّرَاتِ خَلْقَ اللهِ، فَقَالَ عَبْدُ اللَّهِ: وَمَا لِي لَا أَلْعَنُ مَنْ لَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ ؟ وَهُوَ فِي كِتَابِ اللَّهِ، فَقَالَتِ الْمَرْأَةُ: لَقَدْ قَرَأْتُ مَا بَيْنَ لَوْحَيِ الْمُصْحَفِ فَمَا وَجَدْتُهُ. فَقَالَ: لَئِنْ كُنْتِ قَرَأْتِيهِ لَقَدْ وَجَدْتِيهِ، قَالَ اللَّهُ عزوجل: ﴿وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا﴾ [سورة الْحَشْرِ: 7] فَقَالَتِ الْمَرْأَةُ: فَإِنِّي أَرَى شَيْئًا مِنْ هَذَا عَلَى امْرَأَتِكَ الْآنَ، قَالَ: اذْهَبِي فَانْظُرِي، قَالَ: فَدَخَلَتْ عَلَى امْرَأَةِ عَبْدِ اللَّهِ فَلَمْ تَرَ شَيْئًا، فَجَاءَتْ إِلَيْهِ فَقَالَتْ: مَا رَأَيْتُ شَيْئًا، فَقَالَ: أَمَا لَوْ كَانَ ذَلِكِ لَمْ نُجَامِعْهَا."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5939)، ومسلم في اللباس والزينة (2125: 120) كلاهما من طريق جرير، عن منصور، عن إبراهيم، عن علقمة، عن عبد الله فذكره. والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5939) and Muslim (2125:120). The wording is Muslim’s.","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: “Allah has cursed the women who tattoo and those who have themselves tattooed, those who pluck facial hair and those who have it plucked, and those who create gaps between their teeth for beauty, altering the creation of Allah.” This reached a woman from Banū Asad named Umm Yaʿqūb, who used to recite the Qurʾān. She came to him and said: “What is this report that has reached me about you, that you curse women who tattoo and have themselves tattooed, women who pluck hair and have it plucked, and women who create gaps between their teeth for beauty and alter Allah’s creation?” ʿAbdullāh replied: “Why should I not curse those whom the Messenger of Allah ﷺ cursed, when it is also in the Book of Allah?” The woman said: “I have read everything between the two covers of the muṣḥaf and did not find it.” He replied: “If you truly read it, then you found it. Allah, Mighty and Majestic, says: ‘Whatever the Messenger gives you, take it; and whatever he forbids you from, abstain from it.’” [Sūrat al-Ḥashr 59:7] The woman said: “I see something of this on your wife right now.” He replied: “Go and look.” She entered upon the wife of ʿAbdullāh but found nothing. She came back and said: “I did not see anything.” He said: “Had she been doing that, we would not have remained together.”"]},"buhuth":{"en":["The word “mutanammaṣāt” is the plural of mutanammaṣah, meaning women who seek namṣ. Here, the author explains namṣ as removing eyebrow hair for beautification, and states that this is impermissible.","However, if the hair joins the two eyebrows, or if it grows unusually thick to the extent that it disfigures or harms the face, the author states that there is no harm in correcting it.","Likewise, if facial hair grows in the form of a beard or mustache, there is no harm in removing it because that is contrary to the natural appearance upon which Allah created women.","The word “mutafallijāt” refers to women who seek falaj, meaning a gap between the front teeth. Tafalluj is to create a gap between adjoining teeth by filing or a similar method, usually involving the incisors and lateral incisors."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5939)، ومسلم (2125: 120)، والسياق لمسلم."},{"num":15535,"demo":false,"sanad":"","matn":["عَنْ مَسْرُوقٍ، أَنَّ امْرَأَةً جَاءَتْ إِلَى ابْنِ مَسْعُودٍ، فَقَالَتْ: أُنْبِئْتُ أَنَّكَ تَنْهَى عَنِ الْوَاصِلَةِ؟ قَالَ: نَعَمْ، فَقَالَتْ: أَشَيْءٌ تَجِدُهُ فِي كِتَابِ اللَّهِ، أَمْ سَمِعْتَهُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ: أَجِدُهُ فِي كِتَابِ اللَّهِ، وَعَنْ رَسُولِ اللَّهِ، فَقَالَتْ: وَاللهِ لَقَدْ تَصَفَّحْتُ مَا بَيْنَ دَفَّتَيِ الْمُصْحَفِ، فَمَا وَجَدْتُ فِيهِ الَّذِي تَقُولُ. قَالَ: فَهَلْ وَجَدْتِ فِيهِ: ﴿مَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا﴾ [الحشر: ٧]، قَالَتْ: نَعَمْ، قَالَ: فَإِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنْ النَّامِصَةِ، وَالْوَاشِرَةِ، وَالْوَاصِلَةِ، وَالْوَاشِمَةِ إِلَّا مِنْ دَاءٍ، قَالَتِ الْمَرْأَةُ: فَلَعَلَّهُ فِي بَعْضِ نِسَائِكَ؟ قَالَ لَهَا: ادْخُلِي، فَدَخَلَتْ، ثُمَّ خَرَجَتْ، فَقَالَتْ: مَا رَأَيْتُ بَأْسًا، قَالَ: مَا حَفِظْتُ إِذًا وَصِيَّةَ الْعَبْدِ الصَّالِحِ: ﴿وَمَا أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَى مَا أَنْهَاكُمْ عَنْهُ﴾ [هود:"],"takhrij":"صحيح: رواه أحمد (3945)، والنسائي (5098) كلاهما من حديث قتادة، عن عزرة، عن الحسن العرني، عن يحيى الجزار، عن مسروق فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (3945) and al-Nasā’ī (5098).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Masrūq narrated: A woman came to Ibn Masʿūd and said: “I have been informed that you prohibit the woman who attaches hair extensions.” He replied: “Yes.” She asked: “Is this something you find in the Book of Allah, or did you hear it from the Messenger of Allah ﷺ?” He replied: “I find it in the Book of Allah and from the Messenger of Allah ﷺ.” She said: “By Allah, I have examined everything between the two covers of the muṣḥaf and have not found what you say.” He replied: “Did you find in it: ‘Whatever the Messenger gives you, take it; and whatever he forbids you from, abstain from it’?” She replied: “Yes.” He said: “I heard the Messenger of Allah ﷺ prohibit the woman who plucks facial hair, the woman who files the teeth, the woman who attaches hair extensions, and the woman who tattoos, except when there is a medical condition.” The woman said: “Perhaps some of your wives do this.” He said: “Go in and see.” She entered, then came out and said: “I saw nothing objectionable.” He replied: “Otherwise, I would not have preserved the advice of the righteous servant: ‘I do not wish to contradict you by doing what I forbid you from.’” [Sūrat Hūd 11:88]"]},"buhuth":{"en":["The word “wāshirah” comes from washr, with fatḥah on the wāw and sukūn on the shīn. It means treating the teeth by filing and thinning their edges, something an older woman might do in order to resemble younger women."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (3945)، والنسائي (5098)."},{"num":15536,"demo":false,"sanad":"","matn":["عَنْ حُمَيْدِ بْنِ عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ:  أَنَّهُ سَمِعَ مُعَاوِيَةَ بْنَ أَبِي سُفْيَانَ عَامَ حَجَّ وَهُوَ عَلَى الْمِنْبَرِ، وَتَنَاوَلَ قُصَّةً مِنْ شَعَرٍ كَانَتْ فِي يَدِ حَرَسِيٍّ يَقُولُ: يَا أَهْلَ الْمَدِينَةِ، أَيْنَ عُلَمَاؤُكُمْ؟ سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَنْهَى عَنْ مِثْلِ هَذِهِ، وَيَقُولُ: إِنَّمَا هَلَكَتْ بَنُو إِسْرَائِيلَ حِينَ اتَّخَذَ هَذِهِ نِسَاؤُهُمْ."],"takhrij":"متفق عليه: رواه مالك في كتاب الشعر (2) عن ابن شهاب، عن حميد بن عبد الرحمن بن عوف فذكره. ورواه البخاري في اللباس (5932)، ومسلم في اللباس والزينة (2127: 122) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in The Book of Hair (2), al-Bukhārī (5932), and Muslim (2127:122).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Ḥumayd ibn ʿAbd al-Raḥmān ibn ʿAwf narrated: During the year in which Muʿāwiyah ibn Abī Sufyān performed Ḥajj, he stood on the pulpit and took a lock of artificial hair that was in the hand of one of his guards. He said: “O people of Madinah, where are your scholars? I heard the Messenger of Allah ﷺ prohibit things like this and say: ‘The Children of Israel were only destroyed when their women began using such things.’”"]},"buhuth":{"en":["The “quṣṣah” here refers to attaching artificial hair to natural hair."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (2)، والبخاري (5932)، ومسلم (2127: 122)."},{"num":15537,"demo":false,"sanad":"","matn":["عن سَعِيدِ بْنِ المسيب، قَالَ: قَدِمَ مُعَاوِيَةُ بْنُ أَبِي سُفْيَانَ الْمَدِينَةَ آخِرَ قَدْمَةٍ قَدِمَهَا، فَخَطَبَنَا، فَأَخْرَجَ كُبَّةً مِنْ شَعَرٍ، فَقَالَ: مَا كُنْتُ أُرَى أَنَّ أَحَدًا يَفْعَلُ هَذَا غَيْرَ الْيَهُودِ، وَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمَّاهُ الزُّورَ ـ يَعْنِي الْوِصَالَ فِي الشَّعَرِ."],"takhrij":"متفق عليه: رواه البخاري في الأنبياء (3488)، ومسلم في اللباس (2127: 123) كلاهما من حديث شعبة، عن عمرو بن مرة، عن سعيد بن المسيب فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3488) and Muslim (2127:123).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Saʿīd ibn al-Musayyib narrated: Muʿāwiyah ibn Abī Sufyān came to Madinah on his final visit and delivered a sermon to us. He brought out a bundled piece of hair and said: “I did not think anyone did this except the Jews. The Prophet ﷺ called it falsehood.” He meant attaching additional hair to one’s hair."]},"buhuth":{"en":["The word “kubbah” refers to hair gathered and bundled together."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3488)، ومسلم (2127: 123)."},{"num":15538,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَيُّمَا امْرَأَةٍ أَدْخَلَتْ فِي شَعَرِهَا مِنْ شَعَرِ غَيْرِهَا، فَإِنَّمَا تُدْخِلُهُ زُورًا."],"takhrij":"صحيح: رواه أحمد (16929)، والطبراني في الكبير (19/342) كلاهما من طريق أبي نعيم (هو الفضل بن دكين)، حدثنا عبد الله بن مبشر مولى أم حبيبة، عن زيد بن أبي عتاب، عن معاوية فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (16927) and al-Ṭabarānī in al-Muʿjam al-Kabīr (19/342).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Muʿāwiyah narrated: I heard the Messenger of Allah ﷺ say: “Any woman who inserts into her hair hair belonging to someone else is only inserting falsehood into it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (16929)، والطبراني في الكبير (19/342)."},{"num":15539,"demo":false,"sanad":"","matn":["عن أَسْمَاءَ قَالَتْ: سَأَلَتِ امْرَأَةٌ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ ابْنَتِي أَصَابَتْهَا الْحَصْبَةُ، فَامَّرَقَ شَعَرُهَا، وَإِنِّي زَوَّجْتُهَا، أَفَأَصِلُ فِيهِ؟ فَقَالَ: لَعَنَ اللَّهُ الْوَاصِلَةَ وَالْمَوْصُولَةَ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5941)، ومسلم في اللباس (2122: 115) كلاهما من طريق هشام بن عروة، عن فاطمة بنت المنذر، عن أسماء بنت أبي بكر فذكرته.","grade":"متفق عليه","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5941) and Muslim (2122:115).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Asmāʾ narrated: A woman asked the Prophet ﷺ: “O Messenger of Allah, my daughter was afflicted with measles and her hair fell out. I have married her off. May I attach hair to it?” He replied: “Allah has cursed the woman who attaches hair and the woman to whom it is attached.”"]},"buhuth":{"en":["Regarding the word “mariqa”, Ṣaḥīḥ Muslim has “tamraqa” with an un-dotted rāʾ.","Al-Nawawī said:","“It means that the hair fell out and was shed, as stated in the other narrations.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5941)، ومسلم (2122: 115)."},{"num":15540,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ: رَضِيَ اللَّهُ عَنْهَا أَنَّ جَارِيَةً، مِنَ الأَنْصَارِ تَزَوَّجَتْ، وَأَنَّهَا مَرِضَتْ فَتَمَعَّطَ شَعَرُهَا، فَأَرَادُوا أَنْ يَصِلُوهَا، فَسَأَلُوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَعَنَ اللَّهُ الْوَاصِلَةَ وَالْمُسْتَوْصِلَةَ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5934)، ومسلم في اللباس والزينة (2123: 117) كلاهما من طريق شعبة، عن عمرو بن مرة، قال: سمعت الحسن بن مسلم بن يناق، يحدث، عن صفية بنت شيبة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5934) and Muslim (2123:117).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["ʿĀ’ishah narrated: A young woman from the Anṣār got married. She then became ill and her hair fell out. Her family wanted to attach hair extensions for her, so they asked the Prophet ﷺ. He said: “Allah has cursed the woman who attaches hair and the woman who has hair attached.”"]},"buhuth":{"en":["The word “tamaʿʿaṭa” means that the hair came out from its roots.","The root maʿṭ means pulling or stretching, as though the hair had been pulled until it broke. It can also be used simply for hair falling out.","Fatḥ al-Bārī (10/376)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5934)، ومسلم (2123: 117)."},{"num":15541,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ يَقُولُ:  زَجَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تَصِلَ الْمَرْأَةُ بِرَأْسِهَا شَيْئًا."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2126) من طريق عبد الرزاق، أخبرنا ابن جريج، أخبرني أبو الزبير، أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2126).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: “The Prophet ﷺ prohibited a woman from attaching anything to the hair of her head.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2126)."},{"num":15542,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: لُعِنَتِ الْوَاصِلَةُ وَالْمُسْتَوْصِلَةُ، وَالنَّامِصَةُ وَالْمُتَنَمِّصَةُ، وَالْوَاشِمَةُ وَالْمُسْتَوْشِمَةُ مِنْ غَيْرِ دَاءٍ."],"takhrij":"حسن: رواه أبو داود (4170) عن ابن السرح، حدثنا ابن وهب، عن أسامة، عن أبان بن صالح، عن مجاهد، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن الوصل والوشم وغيرها","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4170).","chapter_en":"Prohibition of Hair Extensions, Tattooing, and Related Practices","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās said: “The woman who attaches hair, the woman who has it attached, the woman who plucks facial hair, the woman who has it plucked, the woman who tattoos, and the woman who has herself tattooed are cursed when this is done without a medical need.”"]},"buhuth":{"en":["The expression “they were cursed” carries the ruling of a statement attributed to the Prophet ﷺ, just as statements such as “we were commanded” or “we were prohibited” do.","It is also narrated explicitly from Ibn ʿAbbās through another route that the Messenger of Allah ﷺ cursed the woman who attaches hair and the woman to whom it is attached, as well as men who imitate women and women who imitate men.","Narrated by Aḥmad (2263) and al-Ṭabarānī in al-Muʿjam al-Kabīr (11/204).","Abū Dāwūd said after the above hadith of Ibn ʿAbbās:","“The wāṣilah is the woman who attaches women’s hair to other hair.","The mustawṣilah is the woman for whom this is done.","The nāmiṣah is the woman who removes hair from the eyebrow until she makes it thin.","The mutanammaṣah is the woman for whom this is done.","The wāshimah is the woman who places marks resembling beauty spots on her face using kohl or ink.","The mustawshimah is the woman for whom this is done.”","The wāṣilah originally means a woman who joins natural hair with the hair of other women.","As for attaching strands of silk and similar material, the author states that there is no harm in that, based on what is narrated from Saʿīd ibn Jubayr:","“There is no harm in qarāmil.”","Abū Dāwūd narrated it (4171) through a chain containing Sharīk ibn ʿAbdullāh al-Nakhaʿī, who had a weak memory.","Abū Dāwūd said after this statement of Saʿīd ibn Jubayr:","“It appears that he understood the prohibition to refer specifically to women’s natural hair.”","Abū Dāwūd then said: “Aḥmad used to say: There is no harm in qarāmil.”","Qarāmil are braided extensions made from hair, wool, or silk thread that a woman attaches to her hair."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4170)."},{"num":15543,"demo":false,"sanad":"","matn":["عن فَضَالَةَ بن عبيد، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ قَالَ: ثَلَاثَةٌ لَا تَسْأَلْ عَنْهُمْ: رَجُلٌ فَارَقَ الْجَمَاعَةَ، وَعَصَى إِمَامَهُ، وَمَاتَ عَاصِيًا، وَأَمَةٌ أَوْ عَبْدٌ أَبَقَ فَمَاتَ، وَامْرَأَةٌ غَابَ عَنْهَا زَوْجُهَا، قَدْ كَفَاهَا مُؤْنَةَ الدُّنْيَا، فَتَبَرَّجَتْ بَعْدَهُ، فَلَا تَسْأَلْ عَنْهُمْ."],"takhrij":"صحيح: رواه أحمد (23943)، وصحّحه ابن حبان (4559)، والحاكم (411) كلهم من حديث أبي عبد الرحمن (المقرئ)، حدثنا حيوة بن شريح، أخبرني أبو هانئ الخولاني المصري أن أبا علي عمرو بن مالك الجنبي حدّثه فضالة بن عبيد فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب النهي عن التبرج","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23943), authenticated by Ibn Ḥibbān (4559), and al-Ḥākim (411).","chapter_en":"Prohibition of Tabarruj","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":10,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd narrated that the Messenger of Allah ﷺ said: “There are three about whom you need not ask: a man who separates himself from the Muslim community, disobeys his leader, and dies in disobedience; a male or female slave who runs away and dies; and a woman whose husband is absent but has provided her with all her worldly needs, yet she displays herself after his departure. Do not ask about them.”"]},"buhuth":{"en":["The phrase “do not ask about them” means: do not ask about the evil of their condition and the ugliness of their final outcome. It is an expression emphasizing the severity of their state.","According to the author, the hadiths mentioning women uncovering the face are either from before the revelation of the verse of ḥijāb and were subsequently superseded, or they concern situations in which uncovering the face was permitted because of a genuine need.","An example is a woman seeking marriage, as occurred in the time of the Prophet ﷺ in the story of the woman who offered herself in marriage, where her face would need to be seen in order for her appearance to be known.","Another possibility is that the woman was among the elderly women whom Allah permitted to put aside some of their outer garments, provided they did not display their adornment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23943)، وصححه ابن حبان (4559)، والحاكم (411)."},{"num":15544,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ كانت تَقُولُ: لَمَّا نَزَلَتْ هَذِهِ الآيَةُ: وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ [سورة النُّورِ: 31] أَخَذْنَ أُزْرَهُنَّ فَشَقَّقْنَهَا مِنْ قِبَلِ الْحَوَاشِي، فَاخْتَمَرْنَ بِهَا."],"takhrij":"صحيح: رواه البخاري في التفسير (4759) عن أبي نعيم، حدثنا إبراهيم بن نافع، عن الحسن بن مسلم، عن صفية بنت شيبة: أن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب الاختمار","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4759).","chapter_en":"Wearing the Khimār","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah used to say: When this verse was revealed: “And let them draw their head-coverings over their chests.” [Sūrat al-Nūr 24:31] the women took their waist-wraps, tore them from their edges, and used them as khimārs."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (4759)."},{"num":15545,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: يَرْحَمُ اللَّهُ نِسَاءَ الْمُهَاجِرَاتِ الأُوَلَ، لَمَّا أَنْزَلَ اللَّهُ: {وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ} شَقَّقْنَ مُرُوطَهُنَّ فَاخْتَمَرْنَ بِها."],"takhrij":"صحيح: رواه البخاري في التفسير (4758) فقال: قال أحمد بن شبيب: حدثنا أبي، عن يونس، قال ابن شهاب: عن عروة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب الاختمار","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4758).","chapter_en":"Wearing the Khimār","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah said: “May Allah have mercy on the first women of the Muhājirīn. When Allah revealed: ‘And let them draw their head-coverings over their chests,’ they tore their outer garments and used them as khimārs.”"]},"buhuth":{"en":["The word “murūṭ” is the plural of mirṭ, meaning a cloak or wrap used as an outer garment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4758)."},{"num":15546,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: ذُكِرَتْ نِسَاءُ الْأَنْصَارِ، فَأَثْنَتْ عَلَيْهِنَّ، وَقَالَتْ: لَهُنَّ مَعْرُوفًا، وَقَالَتْ: لَمَّا نَزَلَتْ سُورَةُ النُّورِ، عَمَدْنَ إِلَى حُجَزِ - أَوْ حُجُوزِ - مَنَاطِقِهِنَّ، فَشَقَقْنَهُ، ثُمَّ اتَّخَذْنَ مِنْهُ خُمُرًا، وَأَنَّهَا دَخَلَتْ امْرَأَةٌ مِنْهُنَّ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَتْ: يَا رَسُولَ اللَّهِ أَخْبِرْنِي عَنِ الطُّهُورِ مِنَ الْمَحِيضِ؟ فَقَالَ: نَعَمْ لِتَأْخُذْ إِحْدَاكُنَّ مَاءَهَا وَسِدْرَتَهَا فَلْتَطَّهَّرْ، ثُمَّ لِتُحْسِنِ الطُّهُورَ، ثُمَّ تَصُبَّ عَلَى رَأْسِهَا، ثُمَّ تُلْزِقْ بِشُؤُونِ رَأْسِهَا، ثُمَّ تَدْلُكْهُ، فَإِنَّ ذَلِكَ طُهُورٌ، ثُمَّ تَصُبَّ عَلَيْهَا مِنَ الْمَاءِ، ثُمَّ تَأْخُذْ فِرْصَةً مُمَسَّكَةً، فَلْتَطَّهَّرْ بِهَا. قَالَتْ: يَا رَسُولَ اللَّهِ، كَيْفَ أَتَطَهَّرُ بِهَا؟ فَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُكْنِي عَنْ ذَلِكَ، فَقَالَتْ عَائِشَةُ: تَتْبَعُ بِهَا أَثَرَ الدَّمِ."],"takhrij":"صحيح: رواه أحمد (25551) عن عبد الرحمن وعفان قالا: حدثنا أبو عوانة، عن إبراهيم بن مهاجر، عن صفية بنت شيبة، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب الاختمار","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (25551).","chapter_en":"Wearing the Khimār","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah mentioned the women of the Anṣār, praised them, and spoke well of them. She said: When Sūrat al-Nūr was revealed, they went to the waist portions of their garments, tore them, and made khimārs from them. One of those women entered upon the Messenger of Allah ﷺ and said: “O Messenger of Allah, tell me how to purify myself after menstruation.” He said: “One of you should take her water and sidr, purify herself and perform the purification thoroughly. Then she should pour water over her head and rub it so that it reaches the roots and divisions of her hair. Then she should pour water over herself, and afterward take a piece of cloth scented with musk and cleanse herself with it.” She asked: “O Messenger of Allah, how should I cleanse myself with it?” The Messenger of Allah ﷺ used an indirect expression rather than stating it explicitly. ʿĀ’ishah then explained: “Follow the trace of the blood with it.”"]},"buhuth":{"en":["Regarding the word “ḥujūz,” with the letter zāy, al-Khaṭṭābī said that the reading with rāʾ has no appropriate meaning here and that the correct reading is with zāy.","He related the chain through ʿAbdullāh ibn Aḥmad al-Makkī, ʿAlī ibn ʿAbd al-ʿAzīz, Abū ʿUbayd, ʿAbd al-Raḥmān ibn Mahdī, and Abū ʿAwānah, who narrated:","“They went to the ḥujaz or ḥujūz of their waist-wraps and tore them.”","Ḥujaz is the plural of ḥujzah. Originally, ḥujzah means the place where the izār is fastened, and the word later came to be used for the izār itself.","Ḥujūz is the plural of ḥajz. It is said that a man iḥtajaza with an izār when he fastens it around his waist."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (25551)."},{"num":15547,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: لَمَّا نَزَلَتْ: يُدْنِينَ عَلَيْهِنَّ مِنْ جَلَابِيبِهِنَّ [سورة الأَحْزَابِ: 59]، خَرَجَ نِسَاءُ الأَنْصَارِ كَأَنَّ عَلَى رؤوسهن الْغِرْبَانُ مِنَ الأَكْسِيَةِ."],"takhrij":"حسن: رواه أبو داود (4101) عن محمد بن عبيد، حدثنا ابن ثور، عن معمر، عن ابن خثيم، عن صفية بنت شيبة، عن أم سلمة فذكرته.","grade":"حسن","chapter_ar":"باب الاختمار","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4101).","chapter_en":"Wearing the Khimār","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Umm Salamah narrated: When the verse was revealed: “Let them draw their outer garments closely over themselves.” [Sūrat al-Aḥzāb 33:59] the women of the Anṣār went out as though there were crows upon their heads because of the dark coverings they wore."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4101)."},{"num":15548,"demo":false,"sanad":"","matn":["عَنْ صَفِيَّةَ بِنْتِ شَيْبَةَ قَالَتْ: بَيْنَمَا نَحْنُ عِنْدَ عَائِشَةَ قَالَتْ: وَذَكَرَتْ نِسَاءَ قُرَيْشٍ وَفَضْلَهُنَّ، فَقَالَتْ عَائِشَةُ: إِنَّ لِنِسَاءِ قُرَيْشٍ لَفَضْلا، وَإِنِّي وَاللَّهِ مَا رَأَيْتُ أَفْضَلَ مِنْ نِسَاءِ الأَنْصَارِ أَشَدَّ تَصْدِيقًا بِكِتَابِ اللَّهِ، وَلا إِيمَانًا بِالتَّنْزِيلِ، لَقَدْ أُنْزِلَتْ سُورَةُ النُّورِ وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَى جُيُوبِهِنَّ انْقَلَبَ رِجَالُهُنَّ إِلَيْهِنَّ يَتْلُونَ عَلَيْهِنَّ مَا أُنْزِلَ إليهن فيها، ويتلوا الرَّجُلُ عَلَى امْرَأَتِهِ وَابْنَتِهِ وَأُخْتِهِ، وَعَلَى كُلِّ ذِي قَرَابَتِهِ، مَا مِنْهُنَّ امْرَأَةٌ إِلا قَامَتْ إِلَى مِرْطِهَا الْمُرَحَّلِ فَاعْتَجَرَتْ بِهِ تَصْدِيقًا وَإِيمَانًا بِمَا أَنْزَلَ اللَّهُ مِنْ كِتَابِهِ، فَأَصْبَحْنَ يُصَلِّينَ وَرَاءَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  الصبح معتجرات كأن على رؤسهن الغربان."],"takhrij":"حسن: رواه ابن أبي حاتم في تفسيره (14406) عن أبيه، ثنا أحمد بن عبدالله بن يونس، حدثني الزنجي بن خالد، حدثني عبد الله بن عثمان بن خثيم، عن صفية بنت شيبة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب الاختمار","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Ḥātim in his Tafsīr (8/2575).","chapter_en":"Wearing the Khimār","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Ṣafiyyah bint Shaybah narrated: While we were with ʿĀ’ishah, she mentioned the women of Quraysh and their virtues. ʿĀ’ishah said: “The women of Quraysh certainly have virtue, but by Allah, I have never seen women better than the women of the Anṣār, nor any women stronger in affirming the Book of Allah or more believing in the revelation.” When Sūrat al-Nūr was revealed: “And let them draw their head-coverings over their chests,” their men returned to them reciting to them what had been revealed concerning them. A man would recite it to his wife, his daughter, his sister, and every female relative. There was not a woman among them except that she went to her patterned outer cloak and wrapped herself in it, out of belief and affirmation of what Allah had revealed in His Book. By morning, they were praying the dawn prayer behind the Messenger of Allah ﷺ wrapped in their coverings, as though there were crows upon their heads."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي حاتم في تفسيره (14406)."},{"num":15549,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَيْهَا وَهِيَ تَخْتَمِرُ، فَقَالَ: لَيَّةً لاَ لَيَّتَيْنِ."],"takhrij":"صحيح: رواه أبو داود (4115)، وأحمد (26522)، والحاكم (7417) كلهم من حديث سفيان الثوري، عن حبيب بن أبي ثابت، عن وهب، مولى أبي أحمد، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب الاختمار","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4115), Aḥmad (26522), and al-Ḥākim (7417).","chapter_en":"Wearing the Khimār","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":11,"content":{"translation":{"en":["Umm Salamah narrated: The Prophet ﷺ entered upon her while she was putting on her khimār. He said: “One wrap, not two.”"]},"buhuth":{"en":["Abū Dāwūd said:","“The meaning of his statement, ‘One wrap, not two,’ is: do not wrap it like a man’s turban by winding it around in one layer and then another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4115)، وأحمد (26522)، والحاكم (7417)."},{"num":15550,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْمَرْأَةُ عَوْرَةٌ، فَإِذَا خَرَجَتِ اسْتَشْرَفَهَا الشَّيْطَانُ."],"takhrij":"صحيح: رواه الترمذي (1173)، وابن خزيمة (1685)، وابن حبان (5598) كلهم من حديث عمرو بن عاصم، قال: حدثنا همام، عن قتادة، عن مورق، عن أبي الأحوص، عن عبد الله فذكره. واللفظ للترمذي. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في حجاب المرأة المسلمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (1173), Ibn Khuzaymah (1685), and Ibn Ḥibbān (5598).","chapter_en":"What Has Been Narrated Concerning the Ḥijāb of the Muslim Woman","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Ibn Masʿūd narrated that the Prophet ﷺ said: “The woman is ʿawrah, and when she goes out, Satan seeks to make her appear attractive.”"]},"buhuth":{"en":["Ibn Khuzaymah adds:","“The closest she is to the countenance of her Lord is when she is in the innermost part of her home.”","As for Allah’s statement:","“And they should not display their adornment except what ordinarily appears thereof,”","the Companions differed concerning precisely what this visible adornment refers to.","Ibn Masʿūd said that it refers to things such as the outer cloak and clothing.","It is also narrated from him that he said:","“Adornment is of two kinds: adornment seen only by the husband, such as a ring and bracelet, and adornment seen by non-maḥram men, which is the outward clothing.”","Ibn ʿAbbās said:","“The hand and the area of the face.”","Ibn Abī Shaybah narrated this (17281) from Ziyād ibn al-Rabīʿ, from Ṣāliḥ al-Dahhān, from Jābir ibn Zayd, from Ibn ʿAbbās.","Its chain is good.","Ṣāliḥ al-Dahhān is Ṣāliḥ ibn Ibrāhīm Abū Nūḥ. Ibn Maʿīn declared him trustworthy, and Abū Ḥātim said:","“There is no problem with him.”","Al-Jarḥ wa-l-Taʿdīl (4/393).","It is also narrated from Ibn ʿAbbās that he said:","“Kohl and the ring.”","Al-Bayhaqī mentioned this (2/225).","Ibn Jarīr narrated in his Tafsīr (17/259), through his chain from Ibn ʿAbbās:","“The visible adornment is the face, eye-kohl, dye on the hand, and the ring. These are visible in her home to those people who enter upon her.”","The author explains this as referring to her maḥrams.","Some scholars reconciled the two statements attributed to Ibn ʿAbbās by saying that his statement concerning the face and hands refers to the period before the revelation of ḥijāb, while his statement concerning kohl, the eye, dyed hands, and the ring refers to the period after the revelation of ḥijāb.","This is because the circumstances of women changed after the revelation of ḥijāb, as ʿĀ’ishah stated, and the following hadiths and reports are cited by the author as evidence for that.","Before the revelation of ḥijāb, women would appear openly before men. Allah then prohibited this, saying:","“Remain in your homes and do not display yourselves as was the display of the former times of ignorance.”","[Sūrat al-Aḥzāb 33:33]"]},"intro":{"ar":["قال اللّٰه تعالى:","﴿وَقُل لِّلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا مَا ظَهَرَ مِنْهَا وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ وَلَا يُبْدِينَ زِينَتَهُنَّ إِلَّا لِبُعُولَتِهِنَّ أَوْ آبَائِهِنَّ أَوْ آبَاءِ بُعُولَتِهِنَّ أَوْ أَبْنَائِهِنَّ أَوْ أَبْنَاءِ بُعُولَتِهِنَّ أَوْ إِخْوَانِهِنَّ أَوْ بَنِي إِخْوَانِهِنَّ أَوْ بَنِي أَخَوَاتِهِنَّ أَوْ نِسَائِهِنَّ أَوْ مَا مَلَكَتْ أَيْمَانُهُنَّ أَوِ التَّابِعِينَ غَيْرِ أُولِي الْإِرْبَةِ مِنَ الرِّجَالِ أَوِ الطِّفْلِ الَّذِينَ لَمْ يَظْهَرُوا عَلَىٰ عَوْرَاتِ النِّسَاءِ وَلَا يَضْرِبْنَ بِأَرْجُلِهِنَّ لِيُعْلَمَ مَا يُخْفِينَ مِن زِينَتِهِنَّ وَتُوبُوا إِلَى اللَّهِ جَمِيعًا أَيُّهَ الْمُؤْمِنُونَ لَعَلَّكُمْ تُفْلِحُونَ﴾ [سورة النور: ٣١].","في الآية الكريمة ذكر اللّٰه سبحانه وتعالى جملة المحارم الذين يجوز لهم إبداء الزينة، إلا أنهم جميعًا ليسوا على مرتبة واحدة.","قال القرطبي في تفسيره: “لما ذكر اللّٰه تعالى الأزواج وبدأ بهم، ثنى بذوي المحارم وسوى بينهم في إبداء الزينة، ولكن تختلف مراتبهم بحسب ما في نفوس البشر. فلا مرية أن كشف الأب والأخ على المرأة أحوط من كشف ولد زوجها. وتختلف مراتب ما يبدى لهم؛ فيبدى للأب ما لا يجوز إبداؤه لولد الزوج”."],"en":["Allah, the Exalted, says:","“And tell the believing women to lower their gaze, guard their chastity, and not display their adornment except what ordinarily appears thereof; and let them draw their head-coverings over their chests, and not display their adornment except to their husbands, their fathers, their husbands’ fathers, their sons, their husbands’ sons, their brothers, their brothers’ sons, their sisters’ sons, their women, those whom their right hands possess, male attendants having no sexual desire, or children who are not yet aware of women’s private aspects. And let them not stamp their feet so that what they conceal of their adornment becomes known. And turn to Allah in repentance, all of you, O believers, so that you may succeed.”","[Sūrat al-Nūr 24:31]","In this noble verse, Allah, Glorified and Exalted, mentions the categories of maḥram relatives before whom a woman may display her adornment. However, they are not all of the same degree.","Al-Qurṭubī said in his Tafsīr:","“After Allah, the Exalted, mentioned husbands and began with them, He next mentioned the maḥram relatives and placed them together regarding the permissibility of displaying adornment.","However, their ranks differ according to what naturally exists within human beings. There is no doubt that a woman being uncovered before her father or brother is safer than being uncovered before her husband’s son.","The degree of what may be shown to each also differs. A woman may show her father what she may not show her husband’s son.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1173)، وابن خزيمة (1685)، وابن حبان (5598)."},{"num":15551,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: قَالَ عُمَرُ: رَضِيَ اللَّهُ عَنْهُ قُلْتُ يَا رَسُولَ اللَّهِ، يَدْخُلُ عَلَيْكَ الْبَرُّ وَالْفَاجِرُ، فَلَوْ أَمَرْتَ أُمَّهَاتِ الْمُؤْمِنِينَ بِالْحِجَابِ، فَأَنْزَلَ اللَّهُ آيَةَ الْحِجَابِ."],"takhrij":"صحيح: رواه البخاري (4790) عن مسدد، عن يحيى بن أيوب، عن حميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حجاب المرأة المسلمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4790).","chapter_en":"What Has Been Narrated Concerning the Ḥijāb of the Muslim Woman","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Anas narrated that ʿUmar said: “O Messenger of Allah, both righteous and wicked people enter upon you. If only you would command the Mothers of the Believers to observe ḥijāb.” Then Allah revealed the verse of ḥijāb."]}},"tuhfa":{},"full":1,"rep":[13094],"tks":"صحيح: رواه البخاري (4790)."},{"num":15552,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: قال عمر: وافقت ربي في ثلاث ومنها: آية الحجاب."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (402) عن عمرو بن عون، قال: حدثنا هشيم، عن حميد، عن أنس فذكر الحديث بطوله وهو مخرج في موضعه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حجاب المرأة المسلمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (402) and Muslim (2399).","chapter_en":"What Has Been Narrated Concerning the Ḥijāb of the Muslim Woman","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik narrated that ʿUmar said: “I agreed with my Lord in three matters,” and among them he mentioned the verse of ḥijāb."]},"buhuth":{"en":["However, the Prophet ﷺ, who possessed greater knowledge and protective jealousy than ʿUmar, did not institute this until revelation came, as described in Sūrat al-Aḥzāb in the forthcoming story of Zaynab bint Jaḥsh.","According to the author, it is therefore mistaken to understand that ʿUmar merely requested that the Mothers of the Believers observe ḥijāb and that Allah immediately revealed the verse solely because of that request."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (402)، ومسلم (2399)."},{"num":15553,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: لَمَّا انْقَضَتْ عِدَّةُ زَيْنَبَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِزَيْدٍ: فَاذْكُرْهَا عَلَيَّ، قَالَ: فَانْطَلَقَ زَيْدٌ حَتَّى أَتَاهَا، وَهِْيَ تُخَمِّرُ عَجِينَهَا، قَالَ: فَلَمَّا رَأَيْتُهَا عَظُمَتْ فِي صَدْرِي، حَتَّى مَا أَسْتَطِيعُ أَنْ أَنْظُرَ إِلَيْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَكَرَهَا، فَوَلَّيْتُهَا ظَهْرِي، وَنَكَصْتُ عَلَى عَقِبِي، فَقُلْتُ: يَا زَيْنَبُ: أَرْسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَذْكُرُكِ، قَالَتْ: مَا أَنَا بِصَانِعَةٍ شَيْئًا حَتَّى أُوَامِرَ رَبِّي، فَقَامَتْ إِلَى مَسْجِدِهَا، وَنَزَلَ الْقُرْآنُ، وَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَدَخَلَ عَلَيْهَا بِغَيْرِ إِذْنٍ، قَالَ: فَقَالَ: وَلَقَدْ رَأَيْتُنَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَطْعَمَنَا الْخُبْزَ وَاللَّحْمَ حِينَ امْتَدَّ النَّهَارُ، فَخَرَجَ النَّاسُ، وَبَقِيَ رِجَالٌ يَتَحَدَّثُونَ فِي الْبَيْتِ بَعْدَ الطَّعَامِ، فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاتَّبَعْتُهُ، فَجَعَلَ يَتَتَبَّعُ حُجَرَ نِسَائِهِ يُسَلِّمُ عَلَيْهِنَّ، وَيَقُلْنَ: يَا رَسُولَ اللَّهِ، كَيْفَ وَجَدْتَ أَهْلَكَ؟ قَالَ: فَمَا أَدْرِي أَنَا أَخْبَرْتُهُ أَنَّ الْقَوْمَ قَدْ خَرَجُوا أَوْ أَخْبَرَنِي، قَالَ: فَانْطَلَقَ حَتَّى دَخَلَ الْبَيْتَ، فَذَهَبْتُ أَدْخُلُ مَعَهُ، فَأَلْقَى السِّتْرَ بَيْنِي وَبَيْنَهُ، وَنَزَلَ الْحِجَابُ، قَالَ: وَوُعِظَ الْقَوْمُ بِمَا وُعِظُوا بِهِ، زَادَ ابْنُ رَافِعٍ فِي حَدِيثِهِ: ﴿لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ﴾ [سورة الأحزاب: 53] إِلَى قَوْلِهِ: وَاللَّهُ لَا يَسْتَحْيِي مِنَ الْحَقِّ [سورة الأَحْزَابِ: 53]."],"takhrij":"صحيح: رواه مسلم في النكاح (1428) من طرق عن سليمان بن المغيرة، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حجاب المرأة المسلمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1428).","chapter_en":"What Has Been Narrated Concerning the Ḥijāb of the Muslim Woman","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Anas narrated: When Zaynab’s waiting period had ended, the Messenger of Allah ﷺ said to Zayd: “Mention me to her.” Zayd went to her while she was preparing dough. He said: When I saw her, she became so great in my heart because the Messenger of Allah ﷺ had mentioned her that I could not even look directly at her. So I turned my back to her and stepped backward, saying: “O Zaynab, the Messenger of Allah ﷺ has sent me to mention you to him.” She replied: “I will not do anything until I seek the decision of my Lord.” She then stood at her place of prayer. The Qurʾān was revealed, and the Messenger of Allah ﷺ came and entered upon her without seeking permission. Anas continued: I remember that the Messenger of Allah ﷺ fed us bread and meat after the day had advanced. The people departed, but some men remained talking in the house after the meal. The Messenger of Allah ﷺ went out, and I followed him. He went around to the apartments of his wives, greeting them, while they asked: “O Messenger of Allah, how did you find your new wife?” I do not know whether I informed him that the men had left or whether someone else informed him. He went and entered the house. I began to enter with him, but he lowered a curtain between me and himself. Then the ruling of ḥijāb was revealed. The people were admonished with what they were admonished with. Ibn Rāfiʿ added in his narration: “O you who believe, do not enter the houses of the Prophet unless permission is given to you for a meal, without waiting for its preparation…” up to Allah’s statement: “And Allah is not shy of the truth.” [Sūrat al-Aḥzāb 33:53]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1428)."},{"num":15554,"demo":false,"sanad":"","matn":["عن عائشة قالت (في حديث الإفك حين جاءها صفوان بن المعطل): \"فأتاني فعرفني حين رآني، وكان يراني قبل الحجاب، فاستيقظتُ باسترجاعه حين عرفني، فخمرت وجهي بجلبابي...\"."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4750)، ومسلم في التوبة (2770) كلاهما من حديث يونس بن يزيد، عن الزهري، قال: أخبرني عروة بن الزبير وسعيد بن المسيب، وعلقمة بن وقاص، وعبيد الله بن عبد الله بن عتبة بن مسعود، عن حديث عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حجاب المرأة المسلمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4750) and Muslim (2770).","chapter_en":"What Has Been Narrated Concerning the Ḥijāb of the Muslim Woman","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah said, in the hadith of the Incident of al-Ifk when Ṣafwān ibn al-Muʿaṭṭal came upon her: “He came to me and recognized me when he saw me, for he had seen me before the ruling of ḥijāb. I awoke when I heard him saying, ‘Indeed, to Allah we belong and to Him we shall return,’ upon recognizing me, so I covered my face with my jilbāb…”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (4750)، ومسلم (2770)."},{"num":15555,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: خَرَجَتْ سَوْدَةُ بَعْدَ مَا ضُرِبَ الْحِجَابُ لِحَاجَتِهَا، وَكَانَتِ امْرَأَةً جَسِيمَةً لاَ تَخْفَى عَلَى مَنْ يَعْرِفُهَا، فَرَآهَا عُمَرُ بْنُ الْخَطَّابِ فَقَالَ: يَا سَوْدَةُ، أَمَا وَاللَّهِ مَا تَخْفَيْنَ عَلَيْنَا، فَانْظُرِي كَيْفَ تَخْرُجِينَ."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4795)، ومسلم في السلام (2170) كلاهما من حديث أبي أسامة، عن هشام، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حجاب المرأة المسلمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4795) and Muslim (2170).","chapter_en":"What Has Been Narrated Concerning the Ḥijāb of the Muslim Woman","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah narrated: After the ruling of ḥijāb had been imposed, Sawdah went out to attend to a need. She was a large-built woman and could easily be recognized by anyone who knew her. ʿUmar ibn al-Khaṭṭāb saw her and said: “O Sawdah, by Allah, you are not hidden from us, so consider how you go out.”"]},"buhuth":{"en":["The statement:","“She could not be hidden from one who knew her”","means because of the size and build of her body, not because of her face."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4795)، ومسلم (2170)."},{"num":15556,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، قَالَتْ: لَمَّا نَزَلَتْ: { يُدْنِينَ عَلَيْهِنَّ مِنْ جَلاَبِيبِهِنَّ، } خَرَجَ نِسَاءُ الأَنْصَارِ كَأَنَّ عَلَى رُءُوسِهِنَّ الْغِرْبَانُ مِنَ الأَكْسِيَةِ."],"takhrij":"حسن: رواه أبو داود (4101) عن محمد بن عبيد، حدثنا ابن ثور، عن معمر، عن ابن خثيم، عن صفية بنت شيبة، عن أم سلمة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في حجاب المرأة المسلمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4101).","chapter_en":"What Has Been Narrated Concerning the Ḥijāb of the Muslim Woman","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Umm Salamah narrated: When the verse was revealed: “Let them draw their outer garments closely over themselves.” the women of the Anṣār went out as though there were crows upon their heads because of the coverings they wore."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4101)."},{"num":15557,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  كُنْتُ رِدْفَ أَبِي طَلْحَةَ يَوْمَ خَيْبَرَ، وَقَدَمِي تَمَسُّ قَدَمَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ: فَأَتَيْنَاهُمْ حِينَ بَزَغَتِ الشَّمْسُ، وَقَدْ أَخْرَجُوا مَوَاشِيَهُمْ، وَخَرَجُوا بِفُؤُوسِهِمْ وَمَكَاتِلِهِمْ وَمُرُورِهِمْ، فَقَالُوا: مُحَمَّدٌ، وَالْخَمِيسُ. قَالَ: وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ. قَالَ: وَهَزَمَهُمُ اللهُ عَزَّ وَجَلَّ، وَوَقَعَتْ فِي سَهْمِ دَِحْيَةَ جَارِيَةٌ جَمِيلَةٌ، فَاشْتَرَاهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعَةِ أَرْؤُسٍ، ثُمَّ دَفَعَهَا إِلَى أُمِّ سُلَيْمٍ تُصَنِّعُهَا لَهُ، وَتُهَيِّئُهَا، - قَالَ: وَأَحْسِبُهُ قَالَ: - وَتَعْتَدُّ فِي بَيْتِهَا، وَهِيَ صَفِيَّةُ بِنْتُ حُيَيٍّ، قَالَ: وَجَعَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلِيمَتَهَا التَّمْرَ وَالْأَقِطَ وَالسَّمْنَ، فُحِصَتِ الْأَرْضُ أَفَاحِيصَ، وَجِيءَ بِالْأَنْطَاعِ، فَوُضِعَتْ فِيهَا، وَجِيءَ بِالْأَقِطِ وَالسَّمْنِ فَشَبِعَ النَّاسُ، قَالَ: وَقَالَ النَّاسُ: لَا نَدْرِي أَتَزَوَّجَهَا أَمِ اتَّخَذَهَا أُمَّ وَلَدٍ، قَالُوا: إِنْ حَجَبَهَا فَهِْيَ امْرَأَتُهُ، وَإِنْ لَمْ يَحْجُبْهَا فَهِْيَ أُمُّ وَلَدٍ، فَلَمَّا أَرَادَ أَنْ يَرْكَبَ حَجَبَهَا."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4200) ومسلم في النكاح (87:1365) كلاهما من طريق ثابت، عن أنس قال: فذكره. والسياق لمسلم، وسياق البخاري مختصر. إلا أنه ذكره في مواضع كثيرة.","grade":"متفق عليه","chapter_ar":"باب ما جاء في حجاب المرأة المسلمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4200) and Muslim (1365:87).","chapter_en":"What Has Been Narrated Concerning the Ḥijāb of the Muslim Woman","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":12,"content":{"translation":{"en":["Anas narrated: I was riding behind Abū Ṭalḥah on the day of Khaybar, and my foot was touching the foot of the Messenger of Allah ﷺ. We reached them just as the sun rose. They had brought out their livestock and had gone out carrying their axes, baskets, and agricultural tools. When they saw us, they said: “Muḥammad and the army!” The Messenger of Allah ﷺ said: “Khaybar is ruined! Whenever we descend into the courtyard of a people, terrible is the morning of those who were warned.” Allah, Mighty and Majestic, defeated them. A beautiful slave woman fell to the share of Diḥyah. The Messenger of Allah ﷺ purchased her for seven captives, then entrusted her to Umm Sulaym to prepare and ready her for him—and, as the narrator thought, to observe her waiting period in her house. She was Ṣafiyyah bint Ḥuyayy. The Messenger of Allah ﷺ made her wedding feast from dates, dried yogurt, and clarified butter. Hollows were dug in the ground, leather mats were brought and laid in them, then the dried yogurt and butter were brought, and the people ate until they were satisfied. The people said: “We do not know whether he has married her or taken her as an umm walad. If he veils her, then she is his wife; and if he does not veil her, then she is an umm walad.” When he intended to mount, he screened her."]},"buhuth":{"en":["Shaykh al-Islām Ibn Taymiyyah, may Allah have mercy on him, and others cited the statement of the Prophet ﷺ:","“A woman in iḥrām must not wear a face veil or gloves”","as evidence that the woman’s face is not itself ʿawrah during iḥrām, although she must conceal it from non-maḥram men, as will be discussed in the commentary on Sūrat al-Nūr.","The author says:","Accordingly, every hadith in which a woman’s face is described as uncovered is understood as referring to the period before the revelation of ḥijāb."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4200)، ومسلم (87:1365)."},{"num":15558,"demo":false,"sanad":"","matn":["عَنِ الْحَارِثِ بْنِ قَيْسٍ قَالَ: كَتَبَ عُمَرُ بْنُ الْخَطَّابِ رَضِيَ اللَّهُ عَنْهُ إِلَى أَبِي عُبَيْدَةَ: رَضِيَ اللَّهُ عَنْهُ: أَمَّا بَعْدُ، فَإِنَّهُ بَلَغَنِي أَنَّ نِسَاءً مِنْ نِسَاءِ الْمُسْلِمِينَ يَدْخُلْنَ الْحَمَّامَاتِ مَعَ نِسَاءِ أَهْلِ الشِّرْكِ، فَإِنَّهُ مِنْ قِبَلِكَ عَنْ ذَلِكَ، فَإِنَّهُ لَا يَحِلُّ لِامْرَأَةٍ تُؤْمِنُ بِاللهِ وَالْيَوْمِ الْآخِرِ أَنْ يَنْظُرَ إِلَى عَوْرَتِهَا إِلَّا أَهْلُ مِلَّتِهَا."],"takhrij":"حسن: رواه البيهقي في الكبرى (13543) عن أبي نصر، أنبأنا أبو منصور، ثنا أحمد (ابن نجدة)، حدثنا سعيد (ابن منصور)، حدثنا إسماعيل بن عياش، عن هشام بن الغاز، عن عبادة بن نُسي، عن أبيه، عن الحارث بن قيس فذكره.","grade":"حسن","chapter_ar":"باب قوله تعالى: ﴿أَوْ نِسَائِهِنَّ﴾","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bayhaqī in al-Sunan al-Kubrā (7/95).","chapter_en":"Concerning Allah’s Statement: “Or Their Women”","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":13,"content":{"translation":{"en":["Al-Ḥārith ibn Qays narrated: ʿUmar ibn al-Khaṭṭāb wrote to Abū ʿUbaydah: “To proceed: It has reached me that some Muslim women enter bathhouses together with women from the polytheists. Prevent those under your authority from doing that, for it is not lawful for a woman who believes in Allah and the Last Day to have her ʿawrah looked at except by women of her own religious community.”"]},"buhuth":{"en":["The phrase “her ʿawrah” is understood here by the author as referring to the lesser degree of ʿawrah, as has been reported from some scholars.","As for the severe ʿawrah—the private parts, front and back—it is never permissible to look at them, because there is an explicit prohibition against a woman looking at another woman’s ʿawrah, just as a man may not look at another man’s ʿawrah."]},"intro":{"ar":["يستفاد من الآية الكريمة أنه لا يجوز إبداء الزينة لغير المسلمات من الكافرات."],"en":["According to the author, the noble verse indicates that a Muslim woman should not display her adornment before non-Muslim women."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البيهقي في الكبرى (13543)."},{"num":15559,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا زَوَّجَ أَحَدُكُمْ خَادِمَهُ عَبْدَهُ، أَوْ أَجِيرَهُ فَلاَ يَنْظُرْ إِلَى مَا دُونَ السُّرَّةِ، وَفَوْقَ الرُّكْبَةِ."],"takhrij":"حسن: رواه أبو داود (496، 4114) عن زهير بن حرب، حدثنا وكيع، حدثني داود بن سوار المزني، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب عورة الأمة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (496, 4114).","chapter_en":"The ʿAwrah of a Female Slave","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":14,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather, that the Prophet ﷺ said: “When one of you marries off his servant—his slave or hired servant—he should not look at what is below the navel and above the knee.”"]},"buhuth":{"en":["The author says:","This hadith is specifically about a female slave. Jurists, however, generalized it and said that a woman’s ʿawrah before another woman is like a man’s ʿawrah before another man, namely the area between the navel and the knee.","Accordingly, they held that a woman may look at the rest of another woman’s body apart from that area because they are of the same sex and sexual desire is generally absent. However, this becomes forbidden when accompanied by desire or fear of temptation.","They also cited the hadith of Abū Ayyūb, who said:","“I heard the Prophet ﷺ say: ‘What is above the knees is part of the ʿawrah, and what is below the navel is part of the ʿawrah.’”","Al-Bayhaqī narrated it (2/229) and said:","“Its chain contains Saʿīd ibn Abī Rāshid al-Baṣrī, who is weak.”","The author says:","This is an overly broad interpretation that conflicts with the noble verse in which Allah says:","“And let them not display their adornment except what normally appears thereof, and let them draw their head-coverings over their chests, and not display their adornment except to their husbands, their fathers, their husbands’ fathers, their sons, their husbands’ sons, their brothers, their brothers’ sons, their sisters’ sons, their women, those whom their right hands possess, male attendants having no sexual desire, or children who are not yet aware of women’s private aspects. And let them not stamp their feet so that what they conceal of their adornment becomes known. And turn to Allah in repentance, all of you, O believers, so that you may succeed.”","[Sūrat al-Nūr 24:31]","Allah, the Exalted, therefore exempted in this noble verse the usual places of adornment: the hand and forearm extending near the upper arm where an armlet is worn; the head, ears, and neck where necklaces and earrings are worn; and the foot and part of the lower leg where an anklet is worn.","And with Allah is success."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (496، 4114)."},{"num":15560,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ  أَنَّ أُمَّ سَلَمَةَ اسْتَأْذَنَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحِجَامَةِ، فَأَمَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبَا طَيْبَةَ أَنْ يَحْجُمَهَا. قَالَ: حَسِبْتُ أَنَّهُ قَالَ: كَانَ أَخَاهَا مِنَ الرَّضَاعَةِ، أَوْ غُلَامًا لَمْ يَحْتَلِمْ."],"takhrij":"صحيح: رواه مسلم في السلام (2206) من طرق عن الليث، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب جواز النظر إلى شعر المرأة للغلام الذي لم يحتلم","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2206).","chapter_en":"Permissibility of a Boy Who Has Not Reached Puberty Seeing a Woman’s Hair","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":15,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: Umm Salamah sought permission from the Messenger of Allah ﷺ to undergo cupping. He ordered Abū Ṭaybah to perform the cupping for her. The narrator said: “I think he was either her foster-brother or a boy who had not yet reached puberty.”"]}},"tuhfa":{},"full":1,"rep":[11560],"tks":"صحيح: رواه مسلم (2206)."},{"num":15561,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَتَى فَاطِمَةَ بِعَبْدٍ قَدْ وَهَبَهُ لَهَا، قَالَ: وَعَلَى فَاطِمَةَ رَضِيَ اللَّهُ عَنْهَا ثَوْبٌ، إِذَا قَنَّعَتْ بِهِ رَأْسَهَا لَمْ يَبْلُغْ رِجْلَيْهَا، وَإِذَا غَطَّتْ بِهِ رِجْلَيْهَا لَمْ يَبْلُغْ رَأْسَهَا، فَلَمَّا رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا تَلْقَى قَالَ: إِنَّهُ لَيْسَ عَلَيْكِ بَأْسٌ، إِنَّمَا هُوَ أَبُوكِ وَغُلاَمُكِ."],"takhrij":"حسن: رواه أبو داود (4106) عن محمد بن عيسى، حدثنا أبو جميع سالم بن دينار، عن ثابت، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب يجوز للعبد النظر إلى شعر مولاته","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4106).","chapter_en":"A Male Slave May See the Hair of His Female Owner","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":16,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ came to Fāṭimah with a male slave whom he had given to her. Fāṭimah was wearing a garment which, if she used it to cover her head, did not reach her feet, and if she covered her feet with it, it did not reach her head. When the Prophet ﷺ saw the difficulty she was experiencing, he said: “There is no harm upon you. It is only your father and your slave.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12873],"tks":"حسن: رواه أبو داود (4106)."},{"num":15562,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا قَالَتْ حِينَ ذُكِرَ الإِزَارُ: فَالْمَرْأَةُ يَا رَسُولَ اللَّهِ؟ قَالَ: تُرْخِيهِ شِبْرًا. قَالَتْ أُمُّ سَلَمَةَ: إِذًا يَنْكَشِفُ عَنْهَا. قَالَ: فَذِرَاعًا لاَ تَزِيدُ عَلَيْهِ."],"takhrij":"حسن: رواه مالك في اللباس (13) عن أبي بكر بن نافع، عن أبيه نافع مولى ابن عمر، عن صفية بنت أبي عبيد أنها أخبرته عن أم سلمة فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن إسبال المرأة ثوبها أكثر من ذراع","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Mālik (13), Abū Dāwūd (4117), and authenticated by Ibn Ḥibbān (5451).","chapter_en":"Prohibition of a Woman Lengthening Her Garment by More Than a Cubit","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated: When the matter of the izār was mentioned, she asked: “What about women, O Messenger of Allah?” He replied: “Let her lower it by a handspan.” Umm Salamah said: “Then her feet will become exposed.” He replied: “Then a cubit, but no more than that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه مالك (13)، وأبو داود (4117)، وصححه ابن حبان (5451)."},{"num":15563,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقَامَ بَعْضَ نِسَائِهِ، وَشَبَرَ مِنْ ذَيْلِهَا - شِبْرًا أَوْ شِبْرَيْنِ - وَقَالَ: لَا تَزِدْنَ عَلَى هَذَا."],"takhrij":"حسن: رواه أبو يعلى (3796) عن سويد بن سعيد، حدثنا معتمر بن سليمان، عن حميد، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن إسبال المرأة ثوبها أكثر من ذراع","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā (3796).","chapter_en":"Prohibition of a Woman Lengthening Her Garment by More Than a Cubit","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":17,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Prophet ﷺ had one of his wives stand, measured the hem of her garment by one or two handspans, and said: “Do not increase beyond this.”"]},"buhuth":{"en":["Fiqh of the Hadiths","The scholars agreed that women may allow their garments to trail.","However, they disliked extending them beyond two handspans or a cubit because that involves wasting wealth, competing in pride among women, and imitating non-Muslim foreign women who would trail garments five cubits or more while other women carried them from behind."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو يعلى (3796)."},{"num":15564,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ، أَنَّ امْرَأَةً، قَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّ لِي ضَرَّةً، فَهَلْ عَلَىَّ جُنَاحٌ إِنْ تَشَبَّعْتُ مِنْ زَوْجِي غَيْرَ الَّذِي يُعْطِينِي؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلاَبِسِ ثَوْبَىْ زُورٍ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5219)، ومسلم في اللباس (2130) من طريق هشام (هو ابن عروة)، حدثتني فاطمة (هي ابنة المنذر)، عن أسماء فذكرته.","grade":"متفق عليه","chapter_ar":"باب النهي عن التزوير في اللباس وغيره والمتشبع بما لم يعط","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5219) and Muslim (2130).","chapter_en":"Prohibition of False Pretence in Clothing and Elsewhere, and Pretending to Possess What One Was Not Given","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["Asmāʾ narrated: A woman said: “O Messenger of Allah, I have a co-wife. Is there any sin upon me if I pretend that my husband has given me things that he has not actually given me?” The Messenger of Allah ﷺ replied: “The one who pretends to have been given what he was not given is like one wearing two garments of falsehood.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5219)، ومسلم (2130)."},{"num":15565,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ:  أَنَّ امْرَأَةً قَالَتْ: يَا رَسُولَ اللَّهِ، أَقُولُ: إِنَّ زَوْجِي أَعْطَانِي مَا لَمْ يُعْطِنِي. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمُتَشَبِّعُ بِمَا لَمْ يُعْطَ كَلَابِسِ ثَوْبَيْ زُورٍ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2129) عن محمد بن عبد الله بن نمير، ثنا وكيع وعبدة، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب النهي عن التزوير في اللباس وغيره والمتشبع بما لم يعط","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2129).","chapter_en":"Prohibition of False Pretence in Clothing and Elsewhere, and Pretending to Possess What One Was Not Given","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":18,"content":{"translation":{"en":["ʿĀ’ishah narrated: A woman asked: “O Messenger of Allah, may I say that my husband gave me something he did not actually give me?” The Messenger of Allah ﷺ replied: “The one who pretends to have been given what he was not given is like one wearing two garments of falsehood.”"]},"buhuth":{"en":["Al-Nawawī explained the meaning of the hadith:","“The scholars said that it refers to one who pretends to possess more than he actually has, showing people that he possesses things he does not possess, thereby seeking status among them and adorning himself with falsehood. Such a person is blameworthy, just as one who wears two garments of falsehood is blameworthy.","Abū ʿUbayd and others said that it refers to one who wears the clothing of people known for asceticism, worship, and piety in order to make people think that he possesses those qualities, displaying more humility and asceticism outwardly than exists in his heart. These are garments of falsehood and showing off.","It has also been said that it is like someone who wears two garments belonging to someone else and makes people think they belong to him.","Another interpretation is a person who wears a single shirt but attaches two additional sleeves to its sleeves so that it appears that he is wearing two shirts.”","Al-Khaṭṭābī mentioned another interpretation: that “garment” here refers metaphorically to a person’s state or manner, because Arabs use clothing as a figure of speech for the condition of the person wearing it.","Thus, the meaning would be that such a person is like a liar who speaks of things that never occurred.","He also mentioned another interpretation: that it refers to a man who is asked to bear false witness and dresses himself in two fine garments so that his testimony will not be rejected because of his respectable appearance.","And Allah knows best."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2129)."},{"num":15566,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، قَالَتِ: اسْتَيْقَظَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ وَهْوَ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ، مَاذَا أُنْزِلَ اللَّيْلَةَ مِنَ الْفِتْنَةِ، مَاذَا أُنْزِلَ مِنَ الْخَزَائِنِ، مَنْ يُوقِظُ صَوَاحِبَ الْحُجُرَاتِ، كَمْ مِنْ كَاسِيَةٍ فِي الدُّنْيَا عَارِيَةٍ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه البخاري في اللباس (5844) عن عبد الله بن محمد، ثنا هشام، أخبرنا معمر، عن الزهري، أخبرتني هند بنت الحارث، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يحرم من الثياب على النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5844).","chapter_en":"Clothing That Is Forbidden for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Umm Salamah narrated: The Prophet ﷺ awoke during the night saying: “There is no deity worthy of worship except Allah! How many trials have been sent down tonight, and how many treasures have been opened! Who will awaken the women of the apartments? How many women clothed in this world will be naked on the Day of Resurrection.”"]},"buhuth":{"en":["The statement:","“How many women clothed in this world will be naked on the Day of Resurrection”","has been interpreted in several ways.","One interpretation is that a woman may outwardly be clothed, but the material is transparent and does not properly conceal her ʿawrah. She would then be punished in the Hereafter with nakedness as recompense for that."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5844)."},{"num":15567,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  صِنْفَانِ مِنْ أَهْلِ النَّارِ لَمْ أَرَهُمَا: قَوْمٌ مَعَهُمْ سِيَاطٌ كَأَذْنَابِ الْبَقَرِ يَضْرِبُونَ بِهَا النَّاسَ، وَنِسَاءٌ كَاسِيَاتٌ عَارِيَاتٌ، مُمِيلَاتٌ مَائِلَاتٌ، رُءُوسُهُنَّ كَأَسْنِمَةِ الْبُخْتِ الْمَائِلَةِ، لَا يَدْخُلْنَ الْجَنَّةَ، وَلَا يَجِدْنَ رِيحَهَا، وَإِنَّ رِيحَهَا لَيُوجَدُ مِنْ مَسِيرَةِ كَذَا وَكَذَا."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2128) عن زهير بن حرب، حدثنا جرير، عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما يحرم من الثياب على النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2128).","chapter_en":"Clothing That Is Forbidden for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “There are two categories of the people of the Fire whom I have not yet seen: people carrying whips like the tails of cattle with which they beat people, and women who are clothed yet naked, inclining others and themselves inclined, their heads like the leaning humps of Bactrian camels. They will not enter Paradise nor smell its fragrance, although its fragrance can be smelled from such-and-such a distance.”"]},"buhuth":{"en":["The phrase “clothed yet naked” has been interpreted to mean women who cover some parts of their bodies while exposing others.","It has also been interpreted as wearing thin clothing that reveals what is beneath it, or tight clothing that outlines the shape of the body.","The author considers the strongest understanding to be that the expression includes all of these meanings.","The phrase “like the humps of Bactrian camels” refers to women who arrange their hair high upon their heads like a turban so that it resembles the hump of a camel. The author says this was a characteristic style of female singers in that period.","Bactrian camels are camels with long necks."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7713,15847,16282],"tks":"صحيح: رواه مسلم (2128)."},{"num":15568,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بن زَيْدٍ قَالَ: كَسَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُبْطِيَّةً كَثِيفَةً كَانَتْ مِمَّا أَهْدَاهَا دِحْيَةُ الْكَلْبِيُّ، فَكَسَوْتُهَا امْرَأَتِي، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَا لَكَ لَمْ تَلْبَسِ الْقُبْطِيَّةَ؟ قُلْتُ: يَا رَسُولَ اللَّهِ كَسَوْتُهَا امْرَأَتِي، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مُرْها فَلْتَجْعَلْ تَحْتَهَا غِلَالَةً إِنِّي أَخَافُ أَنْ تَصِفَ حَجْمَ عِظَامِهَا."],"takhrij":"حسن: رواه أحمد (21786) عن أبي عامر، حدثنا زهير يعني ابن محمد، عن عبدالله يعني ابن محمد بن عقيل، عن ابن أسامة بن زيد، أن أباه أسامة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما يحرم من الثياب على النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (21786).","chapter_en":"Clothing That Is Forbidden for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["Usāmah ibn Zayd narrated: The Messenger of Allah ﷺ gave me a thick Coptic garment from among those gifted to him by Diḥyah al-Kalbī. I gave it to my wife to wear. The Messenger of Allah ﷺ asked me: “Why are you not wearing the Coptic garment?” I replied: “O Messenger of Allah, I gave it to my wife.” The Messenger of Allah ﷺ said: “Tell her to wear a slip underneath it, for I fear that it may reveal the shape of her bones.”"]},"buhuth":{"en":["The word “Qibṭiyyah” refers to garments associated with the Copts of Egypt. They were fine linen garments produced by the Copts.","The word “kathīfah” means relatively thick, but because of the softness and fineness of the material, it could still outline the shape of what was beneath it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (21786)."},{"num":15569,"demo":false,"sanad":"","matn":["عَبْدَ اللَّهِ بْنَ عَمْرٍو، يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: سَيَكُونُ فِي آخِرِ أُمَّتِي رِجَالٌ يَرْكَبُونَ عَلَى سُرُوجٍ، كَأَشْبَاهِ الرِّحَالِ، يَنْزِلُونَ عَلَى أَبْوَابِ الْمَسْجِدِ، نِسَاؤُهُمْ كَاسِيَاتٌ عَارِيَاتٌ، عَلَى رُءُوسِهِمْ كَأَسْنِمَةِ الْبُخْتِ الْعِجَافِ، الْعَنُوهُنَّ، فَإِنَّهُنَّ مَلْعُونَاتٌ، لَوْ كَانَتْ وَرَاءَكُمْ أُمَّةٌ مِنَ الْأُمَمِ لَخَدَمْنَ نِسَاؤُكُمْ نِسَاءَهُمْ، كَمَا يَخْدِمْنَكُمْ نِسَاءُ الْأُمَمِ قَبْلَكُمْ."],"takhrij":"حسن: رواه أحمد (7083)، وابن حبان (5753)، والحاكم (8346) كلهم من حديث عبد الله بن عياش بن عباس القتباني قال: سمعت أبي يقول: سمعت عيسى بن هلال الصدفي وأبا عبد الرحمن الحبلي يقولان: سمعنا عبد الله بن عمرو فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما يحرم من الثياب على النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (7083), Ibn Ḥibbān (5753), and al-Ḥākim (8346).","chapter_en":"Clothing That Is Forbidden for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: I heard the Messenger of Allah ﷺ say: “Near the end of my Ummah there will be men riding on saddles resembling camel saddles, dismounting at the doors of the mosques. Their women will be clothed yet naked, with their heads like the humps of lean Bactrian camels. Curse them, for they are cursed. If another nation were to come after you, your women would serve their women just as the women of nations before you serve you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (7083)، وابن حبان (5753)، والحاكم (8346)."},{"num":15570,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عمرو بْنِ الْعَاصِ قَالَ: جَاءَتْ أُمَيْمَةُ بِنْتُ رُقَيْقَةَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تُبَايِعُهُ عَلَى الْإِسْلَامِ فَقَالَ: أُبَايِعُكِ عَلَى أَنْ لَا تُشْرِكِي بِاللهِ شَيْئًا، وَلَا تَسْرِقِي، وَلَا تَزْنِي، وَلَا تَقْتُلِي وَلَدَكِ، وَلَا تَأْتِي بِبُهْتَانٍ تَفْتَرِينَهُ بَيْنَ يَدَيْكِ وَرِجْلَيْكِ، وَلَا تَنُوحِي، وَلَا تَبَرَّجِي تَبَرُّجَ الْجَاهِلِيَّةِ الْأُولَى."],"takhrij":"حسن: رواه أحمد (6850) عن خلف بن الوليد، حدثنا ابن عياش، عن سليمان بن سليم، عن عمرو بن شعيب، عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب ما يحرم من الثياب على النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6850).","chapter_en":"Clothing That Is Forbidden for Women","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated: Umaymah bint Ruqayqah came to the Messenger of Allah ﷺ to pledge allegiance to him upon Islam. He said: “I accept your pledge that you will not associate anything with Allah, will not steal, will not commit adultery, will not kill your child, will not produce a slander you have fabricated between your hands and feet, will not engage in wailing, and will not display yourself with the display of the former age of ignorance.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6850)."},{"num":15571,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا اسْتَعْطَرَتِ الْمَرْأَةُ فَمَرَّتْ عَلَى الْقَوْمِ لِيَجِدُوا رِيحَهَا، فَهِيَ كَذَا وَكَذَا. قَالَ قَوْلاً شَدِيدًا."],"takhrij":"حسن: رواه أبو داود (4173) واللفظ له، والترمذي (2786)، والنسائي (5126)، وأحمد (19578)، وصحّحه ابن خزيمة (1681)، وابن حبان (4424) والحاكم (2/396) كلهم من طريق ثابت –يعني ابن عمارة، عن غُنيم، عن أبي موسى الأشعري فذكره.","grade":"حسن","chapter_ar":"باب التحذير من خروج المرأة متطيبة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4173), and this is his wording; al-Tirmidhī (2786), al-Nasā’ī (5126), and Aḥmad (19578); authenticated by Ibn Khuzaymah (1681), Ibn Ḥibbān (4424), and al-Ḥākim (2/396).","chapter_en":"Warning Against a Woman Going Out Wearing Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated that the Prophet ﷺ said: “If a woman applies perfume and passes by people so that they may smell her fragrance, then she is such-and-such.” The narrator said that he used a very severe expression."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2404],"tks":"حسن: رواه أبو داود (4173) واللفظ له، والترمذي (2786)، والنسائي (5126)، وأحمد (19578)، وصححه ابن خزيمة (1681)، وابن حبان (4424)، والحاكم (2/396)."},{"num":15572,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَيُّمَا امْرَأَةٍ أَصَابَتْ بَخُورًا فَلَا تَشْهَدْ مَعَنَا الْعِشَاءَ الْآخِرَةَ."],"takhrij":"صحيح: رواه مسلم في الصلاة (444) من طرق عن عبدالله بن محمد بن عبدالله بن أبي فروة، عن يزيد بن خصيفة، عن بسر بن سعيد، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب التحذير من خروج المرأة متطيبة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (444).","chapter_en":"Warning Against a Woman Going Out Wearing Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Any woman who has applied incense perfume should not attend the later ʿIshāʾ prayer with us.”"]},"buhuth":{"en":["The phrase “she should not attend the later ʿIshāʾ prayer with us” is explained by the author as referring to the fact that temptation may be greater at that time.","Otherwise, the warning applies generally at all times."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2402],"tks":"صحيح: رواه مسلم (444)."},{"num":15573,"demo":false,"sanad":"","matn":["عَنْ زَيْنَبَ امْرَأَةِ عَبْدِ اللَّهِ، قَالَتْ:  قَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا شَهِدَتْ إِحْدَاكُنَّ الْمَسْجِدَ فَلَا تَمَسَّ طِيبًا."],"takhrij":"صحيح: رواه مسلم في الصلاة (443: 142) من طرق عن بسر بن سعيد، عن زينب فذكرته. وفي لفظ: إذا شهدت إحداكن العشاء فلا تطيب.","grade":"صحيح","chapter_ar":"باب التحذير من خروج المرأة متطيبة","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (443:142).","chapter_en":"Warning Against a Woman Going Out Wearing Perfume","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":20,"content":{"translation":{"en":["Zaynab, the wife of ʿAbdullāh, narrated: The Messenger of Allah ﷺ said to us: “If one of you attends the mosque, she should not apply perfume.”"]},"buhuth":{"en":["In another wording:","“If one of you attends the ʿIshāʾ prayer, she should not perfume herself.”","The author explains that ʿIshāʾ is specifically mentioned because temptation may be greater at that time, though the warning applies at all times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (443: 142)."},{"num":15574,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بْنِ عَبْدِ الرَّحْمَنِ، قَالَ: دَخَلْتُ عَلَى عَائِشَةَ أَنَا وَأَخُوهَا مِنَ الرَّضَاعَةِ، فَسَأَلَهَا عَنْ غُسْلِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ الْجَنَابَةِ؟ وَقَالَ: وَكَانَ أَزْوَاجُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْخُذْنَ مِنْ رُؤُوسِهِنَّ حَتَّى تَكُونَ كَالْوَفْرَةِ."],"takhrij":"متفق عليه: رواه مسلم في الحيض (320)، والبخاري في الغسل (251) كلاهما من حديث شعبة حدثني أبوبكر بن حفص، سمعت أبا سلمة فذكره. واللفظ لمسلم، ولم يذكر البخاري جزّ شعرهن، واقتصر على ذكر كيفية غسل الجنابة.","grade":"متفق عليه","chapter_ar":"باب جواز جز المرأة شعرها والنهي عن حلقه","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim in The Book of Menstruation (320) and al-Bukhārī in The Book of Ghusl (251). The wording is Muslim’s. Al-Bukhārī did not mention the wives cutting their hair and limited his version to the description of ghusl from janābah.","chapter_en":"Permissibility of a Woman Cutting Her Hair and Prohibition of Shaving It","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في لباس المرأة وزينتها","group_en":"Collection of What Has Been Narrated Concerning Women’s Clothing and Adornment","part_no":63,"group_no":3,"chapter_no":21,"content":{"translation":{"en":["Abū Salamah ibn ʿAbd al-Raḥmān narrated: I entered upon ʿĀ’ishah together with her foster-brother, and he asked her about how the Prophet ﷺ performed ghusl from major ritual impurity. He also said: “The wives of the Prophet ﷺ used to cut their hair until it became like a wafrah.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه مسلم (320)، والبخاري (251). واللفظ لمسلم، ولم يذكر البخاري جز شعرهن، واقتصر على ذكر كيفية غسل الجنابة."},{"num":15575,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا أَرَادَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكْتُبَ إِلَى الرُّومِ قِيلَ لَهُ: إِنَّهُمْ لَنْ يَقْرَءُوا كِتَابَكَ إِذَا لَمْ يَكُنْ مَخْتُومًا. فَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، وَنَقْشُهُ: مُحَمَّدٌ رَسُولُ اللَّهِ. فَكَأَنَّمَا أَنْظُرُ إِلَى بَيَاضِهِ فِي يَدِهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5875)، ومسلم في اللباس (2092: 56) كلاهما من طريق شعبة قال: سمعت قتادة يحدث عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب اتخاذ النبي ﷺ خاتمًا من فضة لختم الرسائل إلى الملوك","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5875) and Muslim (2092:56).","chapter_en":"The Prophet ﷺ Took a Silver Ring to Seal Letters Sent to Kings","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik narrated: When the Prophet ﷺ intended to write to the Romans, he was told: “They will not read your letter unless it is sealed.” So he had a silver ring made, engraved with: “Muḥammad, the Messenger of Allah.” Anas said: “It is as though I can still see its whiteness on his hand.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5875)، ومسلم (2092: 56)."},{"num":15576,"demo":false,"sanad":"","matn":["عَنْ ثَابِتٍ  أَنَّهُمْ سَأَلُوا أَنَسًا، عَنْ خَاتَمِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أَخَّرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْعِشَاءَ ذَاتَ لَيْلَةٍ إِلَى شَطْرِ اللَّيْلِ، أَوْ كَادَ يَذْهَبُ شَطْرُ اللَّيْلِ، ثُمَّ جَاءَ، فَقَالَ: إِنَّ النَّاسَ قَدْ صَلَّوْا، وَنَامُوا، وَإِنَّكُمْ لَمْ تَزَالُوا فِي صَلَاةٍ مَا انْتَظَرْتُمُ الصَّلَاةَ. قَالَ أَنَسٌ: كَأَنِّي أَنْظُرُ إِلَى وَبِيصِ خَاتَمِهِ مِنْ فِضَّةٍ، وَرَفَعَ إِصْبَعَهُ الْيُسْرَى بِالْخِنْصِرِ."],"takhrij":"متفق عليه: رواه مسلم في المساجد (640: 22) عن أبي بكر بن نافع العبدي، حدثنا بهز بن أسد العمي، حدثنا حماد بن سلمة، عن ثابت فذكره.","grade":"متفق عليه","chapter_ar":"باب اتخاذ النبي ﷺ خاتمًا من فضة لختم الرسائل إلى الملوك","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (640:22) and al-Bukhārī (572).","chapter_en":"The Prophet ﷺ Took a Silver Ring to Seal Letters Sent to Kings","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Thābit narrated that they asked Anas about the ring of the Messenger of Allah ﷺ. Anas said: One night the Messenger of Allah ﷺ delayed the ʿIshāʾ prayer until half the night had passed, or nearly passed. Then he came and said: “The people have prayed and gone to sleep, but you have remained in prayer for as long as you have been waiting for the prayer.” Anas said: “It is as though I can see the gleam of his silver ring.” He pointed to the little finger of his left hand."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (640: 22)، والبخاري (572)."},{"num":15577,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ:  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرَادَ أَنْ يَكْتُبَ إِلَى كِسْرَى، وَقَيْصَرَ، وَالنَّجَاشِيِّ، فَقِيلَ: إِنَّهُمْ لَا يَقْبَلُونَ كِتَابًا إِلَّا بِخَاتَِمٍ، فَصَاغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا حَلْقَتُهُ فِضَّةٌ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في اللباس (2092: 58) عن نصر بن علي الجهضمي، حدثنا نوح بن قيس، عن أخيه خالد بن قيس، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب اتخاذ النبي ﷺ خاتمًا من فضة لختم الرسائل إلى الملوك","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2092:58).","chapter_en":"The Prophet ﷺ Took a Silver Ring to Seal Letters Sent to Kings","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":1,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ intended to write to Kisrā, Caesar, and the Negus. He was told: “They do not accept a letter unless it bears a seal.” So the Messenger of Allah ﷺ had a ring made, its band of silver, and engraved upon it: “Muḥammad, the Messenger of Allah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2092: 58)."},{"num":15578,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: اتَّخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ وَرِقٍ، وَكَانَ فِي يَدِهِ، ثُمَّ كَانَ بَعْدُ فِي يَدِ أَبِي بَكْرٍ، ثُمَّ كَانَ بَعْدُ فِي يَدِ عُمَرَ، ثُمَّ كَانَ بَعْدُ فِي يَدِ عُثْمَانَ، حَتَّى وَقَعَ بَعْدُ فِي بِئْرِ أَرِيسَ، نَقْشُهُ: مُحَمَّدٌ رَسُولُ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5873)، ومسلم في اللباس (2091: 54) كلاهما من حديث عبد الله بن نمير، عن عبيد الله، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب اتخاذ النبي ﷺ خاتمًا من ورق نقشه: “محمد رسول اللّٰه”","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5873) and Muslim (2091:54).","chapter_en":"The Prophet ﷺ Took a Silver Ring Engraved “Muḥammad, the Messenger of Allah”","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Messenger of Allah ﷺ took a silver ring. It remained in his hand, then afterward in the hand of Abū Bakr, then in the hand of ʿUmar, and then in the hand of ʿUthmān, until it eventually fell into the well of Arīs. Its inscription was: “Muḥammad, the Messenger of Allah.”"]},"buhuth":{"en":["This hadith establishes the permissibility of silver rings for men.","A woman may likewise wear a silver ring. According to the author, there is no evidence for the view that this is disliked for women.","The well of Arīs was located in a garden near Qubāʾ."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9604],"tks":"متفق عليه: رواه البخاري (5873)، ومسلم (2091: 54)."},{"num":15579,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَبِسَ خَاتَمًا مِنْ ذَهَبٍ ثَلاَثَةَ أَيَّامٍ، فَلَمَّا رَآهُ أَصْحَابُهُ فَشَتْ خَوَاتِيمُ الذَّهَبِ، فَرَمَى بِهِ، فَلاَ نَدْرِي مَا فَعَلَ، ثُمَّ أَمَرَ بِخَاتَمٍ مِنْ فِضَّةٍ، فَأَمَرَ أَنْ يُنْقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ، وَكَانَ فِي يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى مَاتَ، وَفِي يَدِ أَبِي بَكْرٍ حَتَّى مَاتَ، وَفِي يَدِ عُمَرَ حَتَّى مَاتَ، وَفِي يَدِ عُثْمَانَ سِتَّ سِنِينَ مِنْ عَمَلِهِ، فَلَمَّا كَثُرَتْ عَلَيْهِ الْكُتُبُ دَفَعَهُ إِلَى رَجُلٍ مِنَ الأَنْصَارِ، فَكَانَ يَخْتِمُ بِهِ، فَخَرَجَ الأَنْصَارِيُّ إِلَى قَلِيبٍ لِعُثْمَانَ، فَسَقَطَ، فَالْتُمِسَ فَلَمْ يُوجَدْ، فَأَمَرَ بِخَاتَمٍ مِثْلِهِ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ."],"takhrij":"حسن: رواه النسائي (5217) واللفظ له، وأبو داود (4220) مختصرا- كلاهما من حديث أبي عاصم، عن المغيرة بن زياد، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب اتخاذ النبي ﷺ خاتمًا من ورق نقشه: “محمد رسول اللّٰه”","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (5217), and this is his wording, and Abū Dāwūd (4220).","chapter_en":"The Prophet ﷺ Took a Silver Ring Engraved “Muḥammad, the Messenger of Allah”","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Messenger of Allah ﷺ wore a gold ring for three days. When his Companions saw it, they also began wearing gold rings. He then threw his ring away, and we do not know what became of it. Afterward, he ordered that a silver ring be made and instructed that it be engraved: “Muḥammad, the Messenger of Allah.” It remained in the hand of the Messenger of Allah ﷺ until he died, then in the hand of Abū Bakr until he died, then in the hand of ʿUmar until he died, and then in the hand of ʿUthmān for six years of his caliphate. When the amount of correspondence increased, ʿUthmān entrusted it to a man from the Anṣār who used it to seal documents. The Anṣārī went to a well belonging to ʿUthmān, and the ring fell into it. They searched for it but could not find it. So ʿUthmān ordered another ring like it to be made, engraved: “Muḥammad, the Messenger of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5217) واللفظ له، وأبو داود (4220)."},{"num":15580,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ لَمَّا اسْتُخْلِفَ كَتَبَ لَهُ، وَكَانَ نَقْشُ الْخَاتَمِ ثَلاَثَةَ أَسْطُرٍ. مُحَمَّدٌ سَطْرٌ، وَرَسُولُ سَطْرٌ، وَاللَّهِ سَطْرٌ."],"takhrij":"صحيح: رواه البخاري في اللباس (5878) عن محمد بن عبد الله الأنصاري، ثني أبي، عن ثمامة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب اتخاذ النبي ﷺ خاتمًا من ورق نقشه: “محمد رسول اللّٰه”","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5878).","chapter_en":"The Prophet ﷺ Took a Silver Ring Engraved “Muḥammad, the Messenger of Allah”","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":2,"content":{"translation":{"en":["Anas narrated: When Abū Bakr became caliph, he wrote a letter to him. The inscription on the ring consisted of three lines: “Muḥammad” on one line, “Messenger” on one line, “Allah” on one line."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5878)."},{"num":15581,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، وَنَقَشَ فِيهِ، مُحَمَّدٌ رَسُولُ اللَّهِ. وَقَالَ: إِنِّي اتَّخَذْتُ خَاتَمًا مِنْ وَرِقٍ، وَنَقَشْتُ فِيهِ، مُحَمَّدٌ رَسُولُ اللَّهِ. فَلاَ يَنْقُشَنَّ أَحَدٌ عَلَى نَقْشِهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5877)، ومسلم في اللباس والزينة (2092) كلاهما من طريق حماد بن زيد، عن عبدالعزيز بن صهيب، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن نقش الخاتم على نقش خاتم رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5877) and Muslim (2092).","chapter_en":"Prohibition of Engraving a Ring with the Same Inscription as the Ring of the Messenger of Allah ﷺ","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Messenger of Allah ﷺ had a silver ring made and engraved upon it: “Muḥammad, the Messenger of Allah.” He said: “I have taken a silver ring and engraved upon it ‘Muḥammad, the Messenger of Allah,’ so no one should engrave a ring with the same inscription as mine.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5877)، ومسلم (2092)."},{"num":15582,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ:  اتَّخَذَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ ذَهَبٍ، ثُمَّ أَلْقَاهُ، ثُمَّ اتَّخَذَ خَاتَمًا مِنْ وَرِقٍ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ. وَقَالَ: لَا يَنْقُشْ أَحَدٌ عَلَى نَقْشِ خَاتَمِي هَذَا. وَكَانَ إِذَا لَبِسَهُ جَعَلَ فَصَّهُ مِمَّا يَلِي بَطْنَ كَفِّهِ، وَهُوَ الَّذِي سَقَطَ مِنْ مُعَيْقِيبٍ فِي بِئْرِ أَرِيسٍ."],"takhrij":"صحيح: رواه مسلم في اللباس (2091: 55) من طرق عن سفيان بن عيينة، عن أيوب بن موسى، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن نقش الخاتم على نقش خاتم رسول اللّٰه ﷺ","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2091:55).","chapter_en":"Prohibition of Engraving a Ring with the Same Inscription as the Ring of the Messenger of Allah ﷺ","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Prophet ﷺ took a gold ring, then discarded it. Afterward, he took a silver ring engraved: “Muḥammad, the Messenger of Allah.” He said: “No one should engrave a ring with the same inscription as this ring of mine.” Whenever he wore it, he placed the stone toward the inside of his palm. This was the ring that later fell from Muʿayqīb into the well of Arīs."]},"buhuth":{"en":["The statement of the Prophet ﷺ:","“No one should engrave a ring with the same inscription as this ring of mine”","was because he corresponded with kings, rulers, and others and sealed his letters with it.","If another person had used the same official inscription during his lifetime, it could have led to confusion and harm.","The situation of the caliphs who came after him was different."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2091: 55)."},{"num":15583,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ خَاتَمُهُ مِنْ فِضَّةٍ، وَكَانَ فَصُّهُ مِنْهُ."],"takhrij":"صحيح: رواه البخاري في اللباس (5870) عن إسحاق، أخبرنا معتمر قال: سمعت حميدا، يحدث عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فص خاتم النبي ﷺ","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5870).","chapter_en":"What Has Been Narrated Concerning the Stone of the Prophet’s ﷺ Ring","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Anas narrated: “The ring of the Prophet ﷺ was made of silver, and its stone was also made from the same material.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5870)."},{"num":15584,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ:  كَانَ خَاتَِمُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ وَرِقٍ، وَكَانَ فَصُّهُ حَبَشِيًّا."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2094: 61) عن يحيى بن أيوب، ثنا عبد الله بن وهب المصري، أخبرني يونس بن يزيد، عن ابن شهاب، حدثني أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في فص خاتم النبي ﷺ","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2094:61).","chapter_en":"What Has Been Narrated Concerning the Stone of the Prophet’s ﷺ Ring","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik narrated: “The ring of the Messenger of Allah ﷺ was made of silver, and its stone was Abyssinian.”"]},"buhuth":{"en":["The statement here that:","“Its stone was Abyssinian”","and the previous report saying:","“Its stone was made from the same material”","are understood by the author as referring to two different periods.","However, the author says he did not find anyone who explicitly identified which of the two was the later ring inherited by the caliphs."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2094: 61)."},{"num":15585,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَبِسَ خَاتَمَ فِضَّةٍ فِي يَمِينِهِ فِيهِ فَصٌّ حَبَشِيٌّ، كَانَ يَجْعَلُ فَصَّهُ مِمَّا يَلِي كَفَّهُ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2094: 62) من طرق عن طلحة بن يحيى الزرقي، عن يونس، عن ابن شهاب، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب لبس الخاتم في اليد اليمنى","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2094:62).","chapter_en":"Wearing the Ring on the Right Hand","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Anas narrated: The Messenger of Allah ﷺ wore a silver ring on his right hand. It had an Abyssinian stone, and he would place the stone toward the inside of his palm."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2094: 62)."},{"num":15586,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَلْبَسُ خَاتَمَهُ فِي يَمِينِهِ."],"takhrij":"حسن: رواه أبو داود (4226)، والنسائي (5203)، والترمذي في الشمائل (90)، وصحّحه ابن حبان (5501) كلهم من حديث ابن وهب، أخبرني سليمان بن بلال، عن شريك بن أبي نمر، عن إبراهيم بن عبد الله بن حنين، عن أبيه، عن علي فذكره.","grade":"حسن","chapter_ar":"باب لبس الخاتم في اليد اليمنى","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4226), al-Nasā’ī (5203), al-Tirmidhī in al-Shamā’il (90), and authenticated by Ibn Ḥibbān (5501).","chapter_en":"Wearing the Ring on the Right Hand","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: “The Prophet ﷺ used to wear his ring on his right hand.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9610],"tks":"حسن: رواه أبو داود (4226)، والنسائي (5203)، والترمذي في الشمائل (90)، وصححه ابن حبان (5501)."},{"num":15587,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ إِسْحَاقَ، قَالَ: رَأَيْتُ عَلَى الصَّلْتِ بْنِ عَبْدِ اللَّهِ بْنِ نَوْفَلِ بْنِ عَبْدِ الْمُطَّلِبِ خَاتَمًا فِي خِنْصَرِهِ الْيُمْنَى، فَقُلْتُ: مَا هَذَا؟ قَالَ: رَأَيْتُ ابْنَ عَبَّاسٍ يَلْبَسُ خَاتَمَهُ هَكَذَا، وَجَعَلَ فَصَّهُ عَلَى ظَهْرِهَا. قَالَ: وَلاَ يَخَالُ ابْنَ عَبَّاسٍ إِلاَّ قَدْ كَانَ يَذْكُرُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَلْبَسُ خَاتَمَهُ كَذَلِكَ."],"takhrij":"حسن: رواه أبو داود (4229)، والترمذي (1742) كلاهما من طريق محمد بن إسحاق قال: فذكره.","grade":"حسن","chapter_ar":"باب لبس الخاتم في اليد اليمنى","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4229) and al-Tirmidhī (1742).","chapter_en":"Wearing the Ring on the Right Hand","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":5,"content":{"translation":{"en":["Muḥammad ibn Isḥāq narrated: I saw a ring on the little finger of the right hand of al-Ṣalt ibn ʿAbdullāh ibn Nawfal ibn ʿAbd al-Muṭṭalib. I asked: “What is this?” He replied: “I saw Ibn ʿAbbās wearing his ring like this.” He placed its stone on the outer side of the finger. The narrator said: I do not think Ibn ʿAbbās did so except that he used to mention that the Messenger of Allah ﷺ wore his ring in the same manner."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4229)، والترمذي (1742)."},{"num":15588,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَخَتَّمُ فِي يَسَارِهِ، وَكَانَ فَصُّهُ فِي بَاطِنِ كَفِّهِ."],"takhrij":"حسن: رواه أبو داود (4227) عن نصر بن علي، حدثني أبي، ثنا عبد العزيز بن أبي رواد، عن نافع، عن ابن عمر فذكره.","grade":"حسن","chapter_ar":"باب جواز لبس الخاتم في اليد اليسرى","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4227).","chapter_en":"Permissibility of Wearing the Ring on the Left Hand","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿUmar narrated: “The Prophet ﷺ used to wear his ring on his left hand, with its stone toward the inside of his palm.”"]},"buhuth":{"en":["The hadiths of these two chapters establish that wearing a ring on the right hand is permissible, just as wearing it on the left hand is permissible, without either being disliked.","The author considers the right hand preferable and suggests that the Prophet ﷺ may have worn it on the left on some occasions in order to demonstrate permissibility.","Al-Ḥāfiẓ Ibn Ḥajar likewise said there is nothing anomalous in these narrations.","Al-Nawawī, may Allah have mercy on him, said:","“As for the legal ruling, the jurists unanimously agreed that wearing a ring on the right hand is permissible and that wearing it on the left hand is also permissible, with neither being disliked.","They differed over which is preferable.","Many of the early Muslims wore rings on the right hand, while many others wore them on the left.","Mālik preferred the left and disliked the right.","Within our school there are two views. The correct view is that the right hand is preferable because the ring is an adornment, and the right hand is more noble and more fitting for adornment and honor.”","Al-Ḥāfiẓ Ibn al-Qayyim said:","“The hadiths differ as to whether he wore it on his right or his left hand, and all of them have authentic chains.”","Zād al-Maʿād (1/139).","The author says that this is indeed the case and points to the following hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4227)."},{"num":15589,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  كَانَ خَاتَِمُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذِهِ، وَأَشَارَ إِلَى الْخِنْصِرِ مِنْ يَدِهِ الْيُسْرَى."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2095) عن أبي بكر بن خلاد الباهلي، ثنا عبد الرحمن بن مهدي، ثنا حماد بن سلمة، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب التختم في الخنصر من اليد اليسرى","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2095).","chapter_en":"Wearing the Ring on the Little Finger of the Left Hand","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Anas narrated: “The ring of the Prophet ﷺ was on this finger.” He pointed to the little finger of his left hand."]}},"tuhfa":{},"full":1,"rep":[9613],"tks":"صحيح: رواه مسلم (2095)."},{"num":15590,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَنَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا قَالَ: إِنَّا اتَّخَذْنَا خَاتَمًا، وَنَقَشْنَا فِيهِ نَقْشًا، فَلاَ يَنْقُشْ عَلَيْهِ أَحَدٌ. قَالَ: فَإِنِّي لأَرَى بَرِيقَهُ فِي خِنْصَرِهِ."],"takhrij":"صحيح: رواه البخاري في اللباس (5874) عن أبي معمر (هو عبد الله بن عمرو)، ثنا عبد الوارث، ثنا عبد العزيز بن صهيب، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب التختم في الخنصر من اليد اليسرى","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5874).","chapter_en":"Wearing the Ring on the Little Finger of the Left Hand","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":7,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ had a ring made and said: “We have taken a ring and engraved an inscription upon it, so no one should engrave the same inscription.” Anas said: “I can still see its gleam on his little finger.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5874)."},{"num":15591,"demo":false,"sanad":"","matn":["عَنْ علي قَالَ: نَهَانِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَتَخَتَّمَ فِي إِصْبَعِي هَذِهِ أَوْ هَذِهِ، قَالَ: فَأَوْمَأَ إِلَى الْوُسْطَى وَالَّتِي تَلِيهَا."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2078: 65) عن يحيى بن يحيى (هو النيسابوري)، أنا أبو الأحوص، عن عاصم بن كليب، عن أبي بردة، قال: قال علي فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن التختم في الوسطى والتي تليها للرجال دون النساء","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2078:65).","chapter_en":"Prohibition for Men, but Not Women, of Wearing Rings on the Middle Finger and the Finger Next to It","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":8,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: “The Messenger of Allah ﷺ prohibited me from wearing a ring on this finger or this one.” He pointed to the middle finger and the finger next to it."]},"buhuth":{"en":["The scholars stated that this prohibition is specific to men.","Al-Nawawī said:","“The Muslims unanimously agreed that the Sunnah for a man is to wear his ring on the little finger. As for a woman, she may wear rings on her fingers.”","Sharḥ Ṣaḥīḥ Muslim."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2078: 65)."},{"num":15592,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: جَاءَتِ امْرَأَةٌ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ, جئتُ أهبُ لَكَ نَفْسِي.فَنَظَرَ إِلَيْهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَعَّدَ النَّظَرَ فِيهَا وَصَوَّبَهُ, ثُمَّ طَأْطَأَ رَأْسَهُ, فَلَمَّا رَأَتِ الْمَرْأَةُ أَنَّهُ لَمْ يَقْضِ فِيهَا شَيْئًا جَلَسَتْ, فَقَامَ رجلٌ مِنْ أَصْحَابِهِ فَقَالَ: يَا رَسُولَ اللَّهِ! إِنْ لَمْ يكنْ لَكَ بِهَا حَاجَةٌ فَزَوِّجْنِيهَا فَقَالَ: هَلْ عِنْدَكَ شيء؟ قَالَ: لاَ وَاللَّهِ يَا رَسُولَ اللَّهِ. قَالَ: اذْهَبْ إِلَى أَهْلِكَ فَانْظُرْ هَلْ تَجِدُ شَيْئًا؟ فَذَهَبَ ثُمَّ رَجَعَ, فَقَالَ: لاَ وَاللَّهِ, مَا وَجَدْتُ شَيْئًا. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : انْظُرْ وَلَوْ خَاتَمًا مِنْ حَدِيدٍ, فَذَهَبَ ثُمَّ رَجَعَ, فَقَالَ: لاَ وَاللَّهِ يَا رَسُولَ اللَّهِ وَلاَ خَاتَمًا مِنْ حَدِيدٍ, وَلَكِنْ هَذَا إِزَارِي – قَالَ سَهْلٌ: مَا لَهُ رِدَاءٌ – فَلَهَا نِصْفُهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَا تَصْنَعُ بِإِزَارِكَ, إِنْ لَبِسْتَهُ لَمْ يَكُنْ عَلَيْهَا مِنْهُ شيء, وَإِنْ لَبِسَتْهُ لَمْ يَكُنْ عَلَيْكَ مِنْهُ شيء. فَجَلَسَ الرَّجُلُ حَتَّى إِذَا طَالَ مَجْلِسُهُ قَامَ، فَرَآهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُوَلِّيًا، فَأَمَرَ بِهِ فَدُعِيَ لَهُ، فَلَمَّا جَاءَ، قَالَ: مَا مَعَكَ مِنَ الْقُرْآنِ؟ قَالَ: مَعِي سُورَةُ كَذَا، وَسُورَةُ كَذَا عَدَّدَهَا. فَقَالَ: تَقْرَؤُهُنَّ عَنْ ظَهْرِ قلب؟ قَالَ: نَعَمْ. قَالَ: اذْهَبْ لَقَدْ مَلَّكْتُكَهَا بِمَا معكَ مِنَ الْقُرْآنِ."],"takhrij":"متفق عليه: رواه البخاري في النكاح (5087) ومسلم في النكاح (1425) كلاهما عن قتيبة بن سعيد الثقفي، حدثنا عبد العزيز بن أبي حازم, عن أبيه, عن سهل بن سعد الساعدي فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في اتخاذ الخاتم من حديد","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5087) and Muslim (1425).","chapter_en":"What Has Been Narrated Concerning a Ring Made of Iron","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Sahl ibn Saʿd narrated: A woman came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, I have come to offer myself to you in marriage.” The Messenger of Allah ﷺ looked at her, raising his gaze and lowering it, then bowed his head. When the woman saw that he had made no decision concerning her, she sat down. A man from among his Companions stood and said: “O Messenger of Allah, if you have no need of her, then marry her to me.” He asked: “Do you possess anything?” The man replied: “No, by Allah, O Messenger of Allah.” He said: “Go to your family and see whether you can find anything.” He went away and returned, saying: “No, by Allah, I found nothing.” The Messenger of Allah ﷺ said: “Look for something, even if it is only an iron ring.” He went away and returned, saying: “No, by Allah, O Messenger of Allah, not even an iron ring. But I have this izār.” Sahl said that the man had no upper garment. The man said: “She may have half of it.” The Messenger of Allah ﷺ said: “What would she do with your izār? If you wear it, she will have nothing of it, and if she wears it, you will have nothing of it.” The man sat down. After he had remained sitting for a long time, he stood to leave. The Messenger of Allah ﷺ saw him walking away and ordered that he be called back. When he returned, the Prophet ﷺ asked: “What do you know of the Qurʾān?” He replied: “I know such-and-such a sūrah and such-and-such a sūrah,” and he listed them. The Prophet ﷺ asked: “Can you recite them from memory?” He replied: “Yes.” The Prophet ﷺ said: “Go. I have married her to you in return for what you know of the Qurʾān.”"]}},"tuhfa":{},"full":1,"rep":[6500],"tks":"متفق عليه: رواه البخاري (5087)، ومسلم (1425)."},{"num":15593,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: أَقْبَلَ رَجُلٌ مِنَ الْبَحْرَيْنِ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَلَّمَ، فَلَمْ يَرُدَّ عَلَيْهِ، وَكَانَ فِي يَدِهِ خَاتَمٌ مِنْ ذَهَبٍ، وَجُبَّةُ حَرِيرٍ، فَأَلْقَاهُمَا ثُمَّ سَلَّمَ، فَرَدَّ عَلَيْهِ السَّلاَمَ، ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ، أَتَيْتُكَ آنِفًا فَأَعْرَضْتَ عَنِّي. فَقَالَ: إِنَّهُ كَانَ فِي يَدِكَ جَمْرَةٌ مِنْ نَارٍ. قَالَ: لَقَدْ جِئْتُ إِذًا بِجَمْرٍ كَثِيرٍ. قَالَ: إِنَّ مَا جِئْتَ بِهِ لَيْسَ بِأَجْزَأَ عَنَّا مِنْ حِجَارَةِ الْحَرَّةِ، وَلَكِنَّهُ مَتَاعُ الْحَيَاةِ الدُّنْيَا. قَالَ: فَمَاذَا أَتَخَتَّمُ؟ قَالَ: حَلْقَةً مِنْ حَدِيدٍ أَوْ وَرِقٍ أَوْ صُفْرٍ."],"takhrij":"حسن: رواه النسائي(5206، 5188)، وفي الكبرى (9461)، وابن وهب في الجامع (593)، وأحمد (11109)، وابن حبان (5489) كلهم من حديث عمرو بن الحارث، عن بكر بن سوادة، عن أبي النجيب، عن أبي سعيد الخدري قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في اتخاذ الخاتم من حديد","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (5188, 5206), in al-Sunan al-Kubrā (9461), Ibn Wahb in al-Jāmiʿ (593), Aḥmad (11109), and Ibn Ḥibbān (5489).","chapter_en":"What Has Been Narrated Concerning a Ring Made of Iron","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":9,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: A man from Bahrain came to the Prophet ﷺ and greeted him, but the Prophet ﷺ did not return his greeting. The man was wearing a gold ring and a silk cloak. So he removed them, then greeted him again, and the Prophet ﷺ returned his greeting. The man said: “O Messenger of Allah, I came to you a short while ago and you turned away from me.” He replied: “There was an ember of fire in your hand.” The man said: “Then I have come with a great deal of embers.” He said: “What you have brought is no more useful to us than the stones of al-Ḥarrah; it is merely the enjoyment of worldly life.” The man asked: “Then what should I use as a ring?” He replied: “A ring of iron, silver, or brass.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (5188، 5206)، وفي الكبرى (9461)، وابن وهب في الجامع (593)، وأحمد (11109)، وابن حبان (5489)."},{"num":15594,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَأَى عَلَى بَعْضِ أَصْحَابِهِ خَاتَمًا مِنْ ذَهَبٍ، فَأَعْرَضَ عَنْهُ، فَأَلْقَاهُ، وَاتَّخَذَ خَاتَمًا مِنْ حَدِيدٍ، فَقَالَ: هَذَا شَرٌّ، هَذَا حِلْيَةُ أَهْلِ النَّارِ، فَأَلْقَاهُ، فَاتَّخَذَ خَاتَمًا مِنْ وَرِقٍ، فَسَكَتَ عَنْهُ."],"takhrij":"حسن: رواه أحمد (6518)، والبخاري في الأدب المفرد (1021) كلاهما من حديث ابن عجلان، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب اتخاذ الخاتم من فضة وكراهية اتخاذه من حديد","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6518) and al-Bukhārī in al-Adab al-Mufrad (1021).","chapter_en":"Taking a Silver Ring and the Dislike of Taking an Iron Ring","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather: The Prophet ﷺ saw one of his Companions wearing a gold ring and turned away from him. The man threw it away and took an iron ring instead. The Prophet ﷺ said: “This is worse; this is the adornment of the people of the Fire.” So the man threw it away and took a silver ring, and the Prophet ﷺ remained silent regarding it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6518)، والبخاري في الأدب المفرد (1021)."},{"num":15595,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِ: أَنَّهُ لَبِسَ خَاتَمًا مِنْ ذَهَبٍ، فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، كَأَنَّهُ كَرِهَهُ، فَطَرَحَهُ، ثُمَّ لَبِسَ خَاتَمًا مِنْ حَدِيدٍ، فَقَالَ: هَذَا أَخْبَثُ وَأَخْبَثُ، فَطَرَحَهُ، ثُمَّ لَبِسَ خَاتَمًا مِنْ وَرِقٍ، فَسَكَتَ عَنْهُ."],"takhrij":"حسن: رواه أحمد (6977) عن سريج، حدثنا عبد الله بن المؤمل، عن ابن أبي مليكة، عن عبد الله بن عمرو بن العاص فذكره.","grade":"حسن","chapter_ar":"باب اتخاذ الخاتم من فضة وكراهية اتخاذه من حديد","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6977).","chapter_en":"Taking a Silver Ring and the Dislike of Taking an Iron Ring","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: He wore a gold ring, and the Messenger of Allah ﷺ looked at it as though he disliked it. So he threw it away. Then he wore an iron ring, and the Prophet ﷺ said: “This is even more repugnant and more repugnant.” So he threw it away. Then he wore a silver ring, and the Prophet ﷺ remained silent."]},"buhuth":{"en":["Fiqh of the Hadiths","The prohibition is understood as indicating dislike rather than absolute prohibition.","Imām Aḥmad was asked:","“Is an iron ring disliked?”","He replied:","“Yes, by Allah.”","Understanding it as absolutely forbidden would conflict with the authentic hadith concerning the woman who offered herself in marriage, in which the Prophet ﷺ told the man to seek even an iron ring.","Some scholars replied that permission to seek an iron ring does not necessarily prove permission to wear it.","The author responds that the primary purpose of a ring is to wear it, and an iron ring has little monetary value and is not normally useful for another purpose, such as being turned into a knife or something similar.","If, however, it is plated or covered with silver, there is no harm in it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6977)."},{"num":15596,"demo":false,"sanad":"","matn":["عن ابن عمر أن النبي صلى الله عليه وسلم جعل فص خاتمه في باطن كفه."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5876)، ومسلم في اللباس (2091) كلاهما من حديث نافع، عن ابن عمر فذكره في سياق أطول منه.","grade":"متفق عليه","chapter_ar":"باب جعل فص الخاتم في باطن الكف","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5876) and Muslim (2091).","chapter_en":"Placing the Stone of the Ring Toward the Inside of the Palm","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar narrated: “The Prophet ﷺ placed the stone of his ring toward the inside of his palm.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5876)، ومسلم (2091)."},{"num":15597,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْعَلُ فَصَّهُ مِمَّا يَلِي كَفَّهُ."],"takhrij":"صحيح: رواه مسلم في اللباس والزينة (2094: 62) من طرق عن طلحة بن يحيى الزرقي، عن يونس، عن ابن شهاب، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب جعل فص الخاتم في باطن الكف","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2094:62).","chapter_en":"Placing the Stone of the Ring Toward the Inside of the Palm","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الخاتم","group_en":"Collection of What Has Been Narrated Concerning Rings","part_no":63,"group_no":4,"chapter_no":11,"content":{"translation":{"en":["Anas narrated: “The Messenger of Allah ﷺ used to place the stone of his ring toward the inside of his palm.”"]},"buhuth":{"en":["Regarding the phrase:","“He placed its stone toward his palm,”","the scholars said that the Prophet ﷺ did not issue any specific command concerning this.","Therefore, it is permissible to place the stone on the inside of the palm or on the outer side, and the early Muslims practiced both ways.","They said that placing it toward the inside is preferable in imitation of the Prophet ﷺ, because it better protects the stone, keeps it safer, and is further removed from ostentation and self-admiration.","Al-Nawawī stated this."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2094: 62)."},{"num":15598,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهَا اشْتَرَتْ نُمْرُقَةً فِيهَا تَصَاوِيرُ، فَلَمَّا رَآهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ عَلَى الْبَابِ، فَلَمْ يَدْخُلْ، فَعَرَفَتْ فِي وَجْهِهِ الْكَرَاهِيَةَ. وقالت: يَا رَسُولَ اللَّهِ، أَتُوبُ إِلَى اللَّهِ وَإِلَى رَسُولِهِ، فَمَاذَا أَذْنَبْتُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : مَا بَالُ هَذِهِ النُّمْرُقَةِ؟ قَالَتْ: اشْتَرَيْتُهَا لَكَ تقعد عَلَيْهَا، وَتَوَسَّدَهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ أَصْحَابَ هَذِهِ الصُّوَرِ يُعَذَّبُونَ يَوْمَ الْقِيَامَةِ، يُقَالُ لَهُمْ: أَحْيُوا مَا خَلَقْتُمْ ثُمَّ قَالَ: إِنَّ الْبَيْتَ الَّذِي فِيهِ الصُّوَرُ، لاَ تَدْخُلُهُ الْمَلاَئِكَةُ."],"takhrij":"متفق عليه: رواه مالك في الاستئذان (8) عن نافع، عن القاسم بن محمد، عن عائشة فذكرته. ورواه البخاري في اللباس (5961)، ومسلم في اللباس (2107: 96) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الوعيد للمصورين","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Istiʾdhān (8), al-Bukhārī (5961), and Muslim (2107:96).","chapter_en":"The Threat Reported Concerning Image-Makers","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الصور والمصورين","group_en":"Collection of What Has Been Narrated Concerning Images and Image-Makers","part_no":63,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, narrated: She purchased a cushion containing images. When the Messenger of Allah ﷺ saw it, he stopped at the doorway and did not enter. She recognized displeasure on his face and said: “O Messenger of Allah, I repent to Allah and His Messenger. What sin have I committed?” The Messenger of Allah ﷺ said: “What is the matter with this cushion?” She replied: “I bought it for you to sit upon and use as a pillow.” The Messenger of Allah ﷺ said: “Those who make these images will be punished on the Day of Resurrection, and it will be said to them: ‘Give life to what you created.’” Then he said: “The angels do not enter a house in which there are images.”"]},"buhuth":{"en":["The word “numruqah” means a cushion."]}},"tuhfa":{},"full":1,"dr":1,"rep":[517],"tks":"متفق عليه: رواه مالك (8)، والبخاري (5961)، ومسلم (2107: 96)."},{"num":15599,"demo":false,"sanad":"","matn":["عن عَائِشَةَ قَالَتْ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ سَفَرٍ، وَقَدْ سَتَرْتُ بِقِرَامٍ لِي عَلَى سَهْوَةٍ لِي فِيهَا تَمَاثِيلُ، فَلَمَّا رَآهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ هَتَكَهُ وَقَالَ: أَشَدُّ النَّاسِ عَذَابًا يَوْمَ الْقِيَامَةِ الَّذِينَ يُضَاهُونَ بِخَلْقِ اللَّهِ. قَالَتْ: فَجَعَلْنَاهُ وِسَادَةً أَوْ وِسَادَتَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5954)، ومسلم في اللباس (2107: 92) كلاهما من حديث سفيان بن عيينة، سمعت عبد الرحمن بن القاسم، -وما بالمدينة يومئذ أفضل منه-، قال: سمعت أبي، قال: سمعت عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الوعيد للمصورين","chapter_ur":"","part_ar":"كتاب اللباس والزينة","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5954) and Muslim (2107:92).","chapter_en":"The Threat Reported Concerning Image-Makers","part_en":"Clothing and Adornment","group_ar":"جموع ما جاء في الصور والمصورين","group_en":"Collection of What Has Been Narrated Concerning Images and Image-Makers","part_no":63,"group_no":5,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Messenger of Allah ﷺ returned from a journey while I had covered a recess in my house with a curtain containing figures. When the Messenger of Allah ﷺ saw it, he tore it down and said: “Among the people who will receive the severest punishment on the Day of Resurrection are those who imitate the creation of Allah.” She said: “So we turned it into one or two cushions.”"]},"buhuth":{"en":["The word “yuḍāhūn” means “they imitate” or “resemble.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5954)، ومسلم (2107: 92)."}]);